INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'missing-bracket'), 1, 'This won''t run at all - read the error message, it tells you exactly what Python was still waiting for.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'missing-bracket'), 2, 'Count the opening and closing parentheses on the `print` line.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'missing-bracket'), 3, 'Add the missing `)` at the end of the `print(...)` line.');
