INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'missing-bracket'), (SELECT id FROM bh_concepts WHERE slug = 'unclosed-brackets'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('lonely-quote', (SELECT id FROM bh_tracks WHERE slug = 'spot-the-typo'), 'The Lonely Quote', 3, 1, NULL, 'syntax', 'This program should print a level-complete message.

Example output: `Level complete!`', 'print("Level complete!)
', 'print("Level complete!")
', 'script', NULL, 'A string needs a quote mark at both ends, matching in type (both `"` or both `''`). Miss one and Python treats everything afterwards as still being inside the string.', 'Count quote marks in pairs, the same way you would brackets.', NULL, 'published', 'c02f95389c3c4b0e8efc2f682891c5ce7ab9020435d5bb6254d901638afab8e2', NOW());
