INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'capital-offence'), (SELECT id FROM bh_concepts WHERE slug = 'case-sensitivity'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('single-equals', (SELECT id FROM bh_tracks WHERE slug = 'spot-the-typo'), 'Single Equals', 7, 2, NULL, 'syntax', '`check(x)` should return `"five"` if `x` equals 5, and `"not five"` otherwise.

Example: `check(5)` should return `"five"`.', 'def check(x):
    if x = 5:
        return "five"
    return "not five"
', 'def check(x):
    if x == 5:
        return "five"
    return "not five"
', 'function', 'check', '`=` and `==` look similar but do very different jobs. `=` stores a value in a variable; `==` asks "are these equal?" and gives back `True` or `False`. Conditions always need the question, not the assignment.', 'Whenever you write an `if` or `while` condition, check for a single `=` - it should almost always be `==`.', NULL, 'published', '14b30efadffaf2c6b27b0f6199ef1e019ac41f3bc77fe863ceebde07380485a6', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'single-equals'), 1, 'check(5)', '(5,)', NULL, NULL, 'returns', '"five"', 'exact', 0);
