INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'single-equals'), 3, 'Change `=` to `==` inside the `if` condition.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'single-equals'), 1, 2, 2, 'syntax', (SELECT id FROM bh_concepts WHERE slug = 'assignment-vs-comparison'), '`=` assigns a value; `==` compares two values. An `if` condition needs a comparison.', 'Change `if x = 5:` to `if x == 5:`.');
