INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('while-single-equals', (SELECT id FROM bh_tracks WHERE slug = 'spot-the-typo'), 'Single Equals in while', 21, 2, NULL, 'syntax', 'This program should loop while `status` is `"pending"`, and print how many times it looped.

Example output: `3`', 'status = "pending"
count = 0
while status = "pending":
    count += 1
    if count >= 3:
        status = "done"
print(count)
', 'status = "pending"
count = 0
while status == "pending":
    count += 1
    if count >= 3:
        status = "done"
print(count)
', 'script', NULL, 'This is the same mix-up as a single `=` in an `if` condition, just in a `while` loop instead - any condition needs `==`, never a bare `=`.', 'Check every `while` condition for a stray single `=`, the same way you would an `if`.', NULL, 'published', '499a78722774a9b25b5f94c08120e157de8f00195fe3b4f2b60583a7106751f9', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'while-single-equals'), 1, 'prints the count', NULL, NULL, '', 'stdout', '"3\\n"', 'exact', 0);
