INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'while-single-equals'), 1, 'This is a syntax error about assignment, in a place Python only allows a comparison.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'while-single-equals'), 2, 'A `while` condition needs to ask a question, not store a value.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'while-single-equals'), 3, 'Change `=` to `==` in the `while` line.');
