Example output: `1`', 'prices = {"apple" = 1, "pear" = 2}
print(prices["apple"])
', 'prices = {"apple": 1, "pear": 2}
print(prices["apple"])
', 'script', NULL, 'A dictionary literal looks like `{key: value, key: value}`. The colon is what links each key to its value - `=` is for variable assignment, a different thing entirely.', 'Every entry inside a `{}` dictionary literal should use `:`, never `=`.', NULL, 'published', 'e512acdab6d70462065c1e981f855cc523754d69682249dbc2932428a566f366', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'dict-equals-not-colon'), 1, 'prints the price', NULL, NULL, '', 'stdout', '"1\\n"', 'exact', 0);
