Example output: `C:\\Users\\notes`', 'path = "C:\\Users\\notes\\"
print(path)
', 'path = r"C:\\Users\\notes"
print(path)
', 'script', NULL, 'Inside an ordinary string, `\\` starts an escape sequence - a backslash right before the closing quote escapes that quote instead of ending the string. A raw string (`r"..."`) turns off escaping entirely, which is exactly what file paths usually want.', 'When a string contains Windows-style file paths, reach for a raw string (`r"..."`) to avoid backslash surprises.', NULL, 'published', 'fbfa2f86db99f66d514840478d0e89b49222e2fab94a4a0df8ebdd7fd7193ed8', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'trailing-backslash-string'), 1, 'prints the path', NULL, NULL, '', 'stdout', '"C:\\\\Users\\\\notes\\n"', 'exact', 0);
