INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('return-outside-function', (SELECT id FROM bh_tracks WHERE slug = 'spot-the-typo'), 'return Outside a Function', 29, 2, NULL, 'syntax', 'This program should print a greeting.

Example output: `Hello, Ada`', 'def greet(name):
    print("Hello, " + name)
return "done"

greet("Ada")
', 'def greet(name):
    print("Hello, " + name)
    return "done"

greet("Ada")
', 'script', NULL, '`return` sends a value back from a function call - it only makes sense while Python is inside a function, so writing one outside any function is a syntax error, not a logic one.', 'If a `return` line isn''t indented inside a `def` block, that''s the problem, not what it''s trying to return.', NULL, 'published', 'b96eae99939105e9b8af3d9a372a0b6dad771d255c0a0c94eef6e4c5292d4842', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'return-outside-function'), 1, 'prints the greeting', NULL, NULL, '', 'stdout', '"Hello, Ada\\n"', 'exact', 0);
