INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'return-outside-function'), 3, 'Indent `return "done"` so it sits inside `greet`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'return-outside-function'), 1, 3, 3, 'syntax', (SELECT id FROM bh_concepts WHERE slug = 'control-flow-context'), '`return "done"` sits outside `greet` (it isn''t indented), but `return` is only valid inside a function.', 'Indent that line so it belongs to `greet`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'return-outside-function'), (SELECT id FROM bh_concepts WHERE slug = 'control-flow-context'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('break-outside-loop', (SELECT id FROM bh_tracks WHERE slug = 'spot-the-typo'), 'break Outside a Loop', 30, 2, NULL, 'syntax', 'This program should print each item in a list.

Example output:
```
1
2
3
```', 'items = [1, 2, 3]
for item in items:
    print(item)
break
', 'items = [1, 2, 3]
for item in items:
    print(item)
', 'script', NULL, '`break` exits the loop it is written inside - it only makes sense while Python is inside a loop body, so one sitting outside any loop is a syntax error.', 'Check that every `break` (and `continue`) is indented inside a `for` or `while` body, not sitting next to it.', NULL, 'published', '3057de5b43326378727ed3f9494cdcf40aeb603406ef396a72de55e0b2ba2516', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'break-outside-loop'), 1, 'prints each item', NULL, NULL, '', 'stdout', '"1\\n2\\n3\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'break-outside-loop'), 2, 'prints each item (repeat check)', NULL, NULL, '', 'stdout', '"1\\n2\\n3\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'break-outside-loop'), 1, 'This won''t run - the error names the exact keyword that''s misplaced.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'break-outside-loop'), 2, '`break` only makes sense inside a loop. Check this one''s indentation against the `for` line.');
