Example output: `10`', 'student-count = 10
print(student-count)
', 'student_count = 10
print(student_count)
', 'script', NULL, 'Python variable names can contain letters, digits and underscores, but not hyphens - a hyphen is always read as a minus sign.', 'Join words in a variable name with an underscore (`_`), never a hyphen.', NULL, 'published', '3b0dee0222bd99e3929a5c4034bf90e1a079582a218db9d16d367fe4d23ac8a7', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'hyphen-in-variable-name'), 1, 'prints the count', NULL, NULL, '', 'stdout', '"10\\n"', 'exact', 0);
