INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'hyphen-in-variable-name'), 1, 'This won''t run - Python reads a punctuation mark here as an operator, not part of a name.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'hyphen-in-variable-name'), 2, 'A hyphen means subtraction to Python. Variable names use a different character to join words.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'hyphen-in-variable-name'), 3, 'Change the hyphen to an underscore: `student_count`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'hyphen-in-variable-name'), 1, 1, 2, 'syntax', (SELECT id FROM bh_concepts WHERE slug = 'identifier-rules'), 'Python reads `student-count` as `student - count` (subtraction), not as one name - hyphens are not allowed in identifiers.', 'Use an underscore instead: `student_count`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'hyphen-in-variable-name'), (SELECT id FROM bh_concepts WHERE slug = 'identifier-rules'));

