Example output: `16`', 'square = lambda x x * x
print(square(4))
', 'square = lambda x: x * x
print(square(4))
', 'script', NULL, 'A `lambda` is a small, unnamed function written on one line: `lambda parameters: expression`. The colon is required, just like in a `def`.', 'Check every `lambda` has exactly one colon, separating its parameters from what it computes.', NULL, 'published', 'f1651baea398f6acf5f319f1a92885814c2e1846816d7aea627cdb5906021f5d', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'lambda-missing-colon'), 1, 'prints square(4)', NULL, NULL, '', 'stdout', '"16\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'lambda-missing-colon'), 2, 'prints square(4) (repeat check)', NULL, NULL, '', 'stdout', '"16\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'lambda-missing-colon'), 1, 'This won''t run - a `lambda` has a required shape, same idea as a block header.');
