INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'lambda-missing-colon'), (SELECT id FROM bh_concepts WHERE slug = 'lambda-syntax'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('bad-line-continuation', (SELECT id FROM bh_tracks WHERE slug = 'spot-the-typo'), 'Broken Multi-line Expression', 35, 2, NULL, 'syntax', 'This program should print the sum of four numbers, split across two lines.

Example output: `10`', 'total = 1 + 2 +
3 + 4
print(total)
', 'total = (1 + 2 +
         3 + 4)
print(total)
', 'script', NULL, 'Python normally ends a statement at the end of a line. To spread one expression over several lines, either wrap it in brackets (the usual way) or end each line with a backslash `\\` - without one of those, Python treats the next line as a brand new statement.', 'If an expression needs to span multiple lines, wrap it in parentheses rather than relying on a trailing backslash.', NULL, 'published', '2b8254e712e38e763733675fab9405397ff48da5cf837170283968817082e7ef', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bad-line-continuation'), 1, 'prints the total', NULL, NULL, '', 'stdout', '"10\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bad-line-continuation'), 2, 'prints the total (repeat check)', NULL, NULL, '', 'stdout', '"10\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bad-line-continuation'), 1, 'This won''t run - the first line ends expecting more, and never gets it.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bad-line-continuation'), 2, 'An expression split across lines needs to either be wrapped in brackets, or use a line-continuation backslash.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bad-line-continuation'), 3, 'Wrap the whole expression in parentheses: `total = (1 + 2 +` then `3 + 4)`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bad-line-continuation'), 1, 1, 2, 'syntax', (SELECT id FROM bh_concepts WHERE slug = 'line-continuation'), 'Line 1 ends with `+`, leaving the expression unfinished, and nothing tells Python the next line continues it.', 'Wrap the whole expression in parentheses so it can span multiple lines safely.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bad-line-continuation'), (SELECT id FROM bh_concepts WHERE slug = 'line-continuation'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('global-assignment-syntax', (SELECT id FROM bh_tracks WHERE slug = 'spot-the-typo'), 'global With an Assignment', 36, 2, NULL, 'syntax', 'This program should increment a counter and print it.

Example output: `1`', 'counter = 0

def increment():
    global counter = counter + 1

increment()
print(counter)
', 'counter = 0

def increment():
    global counter
    counter = counter + 1

increment()
print(counter)
', 'script', NULL, '`global name` tells Python "inside this function, `name` means the module-level variable, not a new local one" - it is purely a declaration, never an assignment, so it can never include `=`.', 'A `global` line should only ever contain the keyword and the name(s) - never an `=`.', NULL, 'published', 'a1a7a8ed3060a8e747c1a06162e62e9b5be517a8a1f8ef088e48c550094343a8', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'global-assignment-syntax'), 1, 'prints the counter', NULL, NULL, '', 'stdout', '"1\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'global-assignment-syntax'), 2, 'prints the counter (repeat check)', NULL, NULL, '', 'stdout', '"1\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'global-assignment-syntax'), 1, 'This won''t run - `global` only ever does one job, and this line asks it to do two.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'global-assignment-syntax'), 2, '`global` just declares which name you mean. The actual assignment needs its own line.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'global-assignment-syntax'), 3, 'Split it into two lines: `global counter` then `counter = counter + 1`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'global-assignment-syntax'), 1, 4, 4, 'syntax', (SELECT id FROM bh_concepts WHERE slug = 'global-statement'), '`global` only declares that a name refers to the module-level variable - it cannot also assign a value on the same line.', 'Write `global counter` on its own line, then assign to it on the next.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'global-assignment-syntax'), (SELECT id FROM bh_concepts WHERE slug = 'global-statement'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('old-style-print', (SELECT id FROM bh_tracks WHERE slug = 'spot-the-typo'), 'Old-style print Statement', 37, 1, NULL, 'syntax', 'This program should print a message.

Example output: `Game over`', 'print "Game over"
', 'print("Game over")
', 'script', NULL, 'In older versions of Python, `print` was a special statement written without parentheses. Current Python made `print` an ordinary function, so it needs to be called like any other: with `()`.', 'If you see `print` followed directly by text with no parentheses in an example online, it''s written for an old Python version.', NULL, 'published', 'b9c80996b45d429f03195b89dc15c369d51875be5c16d80394420503cac20f1a', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'old-style-print'), 1, 'prints the message', NULL, NULL, '', 'stdout', '"Game over\\n"', 'exact', 0);
