        return "C"
', 'function', 'grade', '`elif` is a block header in exactly the same way as `if` and `else` - every one of them needs its own colon.', 'In an if/elif/else chain, check every single header, not just the first one you see.', NULL, 'published', 'ffc021e70f4e5603af71f3faf71d21590149b642ae452b98e0a4b1dbdd0c282c', NOW());
