Example output: `Hello, Ada`', 'name = "Ada"
message = f"Hello, {name}
print(message)
', 'name = "Ada"
message = f"Hello, {name}"
print(message)
', 'script', NULL, 'An f-string still needs its outer quote marks to match, completely separately from the `{}` used inside it - both have to be checked.', 'Check an f-string in two passes: do the outer quotes match, and does every `{` have its `}`?', NULL, 'published', '19a83b5a2d46f7d28ae5502a641f01cb6f457f7ded9bba7ed054dbbd4ac9b752', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unterminated-fstring'), 1, 'prints the message', NULL, NULL, '', 'stdout', '"Hello, Ada\\n"', 'exact', 0);
