INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('mismatched-triple-quotes', (SELECT id FROM bh_tracks WHERE slug = 'spot-the-typo'), 'Mismatched Triple Quotes', 40, 2, NULL, 'syntax', 'This program should print a short poem.

Example output:
```
Roses are red
Violets are blue
```', 'poem = ''''''Roses are red
Violets are blue"""
print(poem)
', 'poem = ''''''Roses are red
Violets are blue''''''
print(poem)
', 'script', NULL, 'A triple-quoted string has to close with the exact same quote character it opened with - three of `''` need three of `''` to close, not three of `"`.', 'When a multi-line string refuses to end, check the closing quote type matches the opening one, not just that there are three of them.', NULL, 'published', 'c8d2025bc1015128f16c1cf177d9418c580738ffa78310069bb33d8cf4216d8e', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'mismatched-triple-quotes'), 1, 'prints the poem', NULL, NULL, '', 'stdout', '"Roses are red\\nViolets are blue\\n"', 'exact', 0);
