INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'mismatched-triple-quotes'), 3, 'Change the closing `"""` to `''''''`, matching how the string opened.');
