INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('mystery-name', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Mystery Name', 1, 1, NULL, 'runtime', '`greet(name)` should return a greeting like `"Hello, Ada!"`.

Example: `greet("Ada")` should return `"Hello, Ada!"`.', 'def greet(name):
    message = "Hello, " + nmae + "!"
    return message
', 'def greet(name):
    message = "Hello, " + name + "!"
    return message
', 'function', 'greet', 'Python only recognises a name once it''s been created - it doesn''t guess what you meant. A typo in a variable name looks right to the eye but is a completely different, undefined name to Python, so it crashes as soon as that line runs.', 'When you see a `NameError`, compare the named variable letter-by-letter against where it was created.', NULL, 'published', '8fa305c3f67692f3251ec0c811c8fc4e5621645d9217c298a69935975e20e568', NOW());
