INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('text-plus-number', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Text Plus Number', 2, 1, NULL, 'runtime', '`describe_age(age)` should return a string like `"Age: 17"`.

Example: `describe_age(17)` should return `"Age: 17"`.', 'def describe_age(age):
    return "Age: " + age
', 'def describe_age(age):
    return "Age: " + str(age)
', 'function', 'describe_age', 'Python''s `+` operator means something different depending on the types either side of it: joining for two strings, addition for two numbers. Mixing a string and a number directly leaves Python unable to decide which you meant.', 'Before joining a value to a string with `+`, check its type - numbers need `str()` first.', NULL, 'published', 'f7b12336f99fc507d5bc05fddefc57bc8d25268c01ee6c6b53c45ee8101aab0a', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'text-plus-number'), 1, 'describe_age(17)', '(17,)', NULL, NULL, 'returns', '"Age: 17"', 'exact', 0);
