INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'past-the-end'), 3, 'Use `items[len(items) - 1]` instead of `items[len(items)]`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'past-the-end'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'indexing'), 'Valid indexes run from `0` to `len(items) - 1`. `items[len(items)]` is one position past the last real item.', 'Subtract 1: `items[len(items) - 1]`.');
