INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'missing-key'), 3, 'Use `colours.get(fruit, "unknown")` instead of `colours[fruit]`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'missing-key'), 1, 3, 3, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'dictionaries'), '`colours[fruit]` crashes if `fruit` isn''t a key already in the dictionary.', 'Use `.get(fruit, "unknown")` to supply a default instead of crashing.');
