INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('divide-by-nothing', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Divide by Nothing', 5, 2, NULL, 'runtime', '`average(nums)` should return the mean of the numbers in `nums`, or `0` if the list is empty.

Example: `average([2, 4, 6])` should return `4`.', 'def average(nums):
    return sum(nums) / len(nums)
', 'def average(nums):
    if len(nums) == 0:
        return 0
    return sum(nums) / len(nums)
', 'function', 'average', 'Dividing by zero always crashes in Python. Any time a divisor comes from a count that could be zero - like the length of a list - it needs a guard before the division runs.', 'Ask "could this count ever be zero?" for every division, and test with an empty input to check.', NULL, 'published', '6a947c268ccf7c3d800b60c4a85dfab8ae80bfd21a9285f414996e3547dc3211', NOW());
