Example: `to_whole("3.5")` should return `3`.', 'def to_whole(text):
    return int(text)
', 'def to_whole(text):
    return int(float(text))
', 'function', 'to_whole', '`int(text)` requires the text to look like a whole number already. Text containing a decimal point needs `float()` first, which `int()` can then round down.', 'If text might contain a decimal point, convert with `float()` before `int()`.', NULL, 'published', '5c3e19597c15f27c03f473d740a31976a227a88cbfcf424f4f5b791efbecccb3', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'not-a-number'), 1, 'to_whole("4")', '(''4'',)', NULL, NULL, 'returns', '4', 'exact', 0);
