INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nothing-returned'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'return-values'), 'The function computes `total` but never returns it, so it implicitly returns `None`.', 'Add `return total`.');
