INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('local-trouble', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Local Trouble', 8, 3, NULL, 'runtime', 'This program keeps a running `count` and should print `1` then `2`.

Example output:
```
1
2
```', 'count = 0

def increment():
    count = count + 1
    return count

print(increment())
print(increment())
', 'count = 0

def increment():
    global count
    count = count + 1
    return count

print(increment())
print(increment())
', 'script', NULL, 'Python decides whether a name is local or global by scanning the whole function for assignments - not line by line. Assigning to `count` anywhere inside `increment` makes every use of `count` in that function local, which crashes if it reads `count` before any local assignment has happened.', 'If a function needs to update a variable from outside it, add `global name` at the top of the function.', NULL, 'published', 'd9a9d7decdf3153798abc37b14f1cc77e36d4fd961904c0ceb07ee2610e2a926', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'local-trouble'), 1, 'prints 1 then 2', NULL, NULL, '', 'stdout', '"1\\n2\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'local-trouble'), 2, 'prints 1 then 2 (repeat check)', NULL, NULL, '', 'stdout', '"1\\n2\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'local-trouble'), 1, 'This crashes with an `UnboundLocalError` - a variable is used before it has a value, inside this function specifically.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'local-trouble'), 2, 'Assigning to a name anywhere inside a function makes Python treat it as local for the *whole* function, even on lines before the assignment. Is `count` meant to be local here?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'local-trouble'), 3, 'Add `global count` as the first line inside `increment`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'local-trouble'), 1, 4, 4, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'names-and-scope'), 'Assigning to `count` inside the function makes Python treat it as a local variable throughout the function - including on the right-hand side, before it''s been given a local value.', 'Add `global count` before using it.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'local-trouble'), (SELECT id FROM bh_concepts WHERE slug = 'names-and-scope'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('string-that-looked-like-a-number', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'The String That Looked Like a Number', 9, 2, NULL, 'runtime', '`total_cost(price_text, quantity)` should return the cost of `quantity` items at the price given in `price_text` (a string, as if it came from `input()`), plus a flat £5 delivery fee.

Example: `total_cost("4", 3)` should return `17`.', 'def total_cost(price_text, quantity):
    return price_text * quantity + 5
', 'def total_cost(price_text, quantity):
    return int(price_text) * quantity + 5
', 'function', 'total_cost', 'Text that *looks* like a number is still text until it''s explicitly converted. `input()` always returns a string, which is exactly why this bug is so common in real programs - multiplying text by a number repeats it instead of doing arithmetic.', 'If a value could have come from `input()` or another text source, check it''s been converted before doing arithmetic with it.', NULL, 'published', '1891e8a9c2e87fabf02beb2f206dd3f4f4c2fbb672895e3bf010f4b5ee340c11', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'string-that-looked-like-a-number'), 1, 'total_cost("4", 3)', '(''4'', 3)', NULL, NULL, 'returns', '17', 'exact', 0);
