INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'string-that-looked-like-a-number'), 3, 'total_cost("2", 5)', '(''2'', 5)', NULL, NULL, 'returns', '15', 'exact', 1);
