INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('attr-error-string-method', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'The Method That Never Was', 11, 1, NULL, 'runtime', '`shout_name(name)` should return `name` in uppercase.

Example: `shout_name("ada")` should return `"ADA"`.', 'def shout_name(name):
    return name.uppercase()
', 'def shout_name(name):
    return name.upper()
', 'function', 'shout_name', '`AttributeError` means the object exists, but it doesn''t have the attribute or method you asked for - usually because of a typo or a method name remembered from a different language.', 'When you see `AttributeError: ''...'' object has no attribute ''...''`, check the exact spelling against Python''s real method names.', NULL, 'published', '3843548672553c13daf60c6fbf5fff4242c9a2fdd7e76429bfd2d668aa2f3e10', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attr-error-string-method'), 1, 'shout_name("ada")', '(''ada'',)', NULL, NULL, 'returns', '"ADA"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attr-error-string-method'), 2, 'shout_name("Sam")', '(''Sam'',)', NULL, NULL, 'returns', '"SAM"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attr-error-string-method'), 3, 'shout_name("")', '('''',)', NULL, NULL, 'returns', '""', 'exact', 1);
