INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attr-error-string-method'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'string-methods'), '`.uppercase()` is not a real string method - the correct one is `.upper()`.', 'Change it to `.upper()`.');
