INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('attr-error-none', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'A Function That Forgot to Return', 12, 2, NULL, 'runtime', '`greeting(record)` should return a greeting using `record["name"]` in uppercase, or `"UNKNOWN"` if there is no name.

Example: `greeting({"name": "ada"})` should return `"ADA"`.', 'def get_name(record):
    if record.get("name"):
        return record["name"]

def greeting(record):
    name = get_name(record)
    return name.upper()
', 'def get_name(record):
    if record.get("name"):
        return record["name"]
    return "unknown"

def greeting(record):
    name = get_name(record)
    return name.upper()
', 'function', 'greeting', 'A function with no matching `return` for some path implicitly returns `None`. That `None` is a perfectly valid value right up until something tries to use it as if it were the real thing - here, calling `.upper()` on it.', 'If an `AttributeError` mentions `NoneType`, trace backwards to find where that `None` actually came from - it''s rarely the line that crashed.', NULL, 'published', '296b01e80612946f7173ed2351e4460460fc64951d2e6ec21540f2af668c3932', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attr-error-none'), 1, 'greeting({"name": "ada"})', '({''name'': ''ada''},)', NULL, NULL, 'returns', '"ADA"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attr-error-none'), 2, 'greeting({})', '({},)', NULL, NULL, 'returns', '"UNKNOWN"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attr-error-none'), 3, 'greeting({"name": "Sam"})', '({''name'': ''Sam''},)', NULL, NULL, 'returns', '"SAM"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attr-error-none'), 1, 'The crash is in `greeting`, but the real mistake is one function earlier, in `get_name`.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attr-error-none'), 2, '`get_name` has no `return` for the case where there''s no name - which means it silently returns `None` instead.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attr-error-none'), 3, 'Add `return "unknown"` at the end of `get_name`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attr-error-none'), 1, 1, 3, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'return-values'), '`get_name` has no `return` statement for the "no name" case, so it falls off the end and returns `None` instead - which then crashes when `.upper()` is called on it.', 'Add an explicit `return "unknown"` as the fallback.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attr-error-none'), (SELECT id FROM bh_concepts WHERE slug = 'return-values'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('typeerror-list-not-callable', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Calling a List', 13, 1, NULL, 'runtime', '`get_first(totals)` should return the first item in `totals`.

Example: `get_first([10, 20, 30])` should return `10`.', 'def get_first(totals):
    return totals(0)
', 'def get_first(totals):
    return totals[0]
', 'function', 'get_first', 'This runs because the syntax is valid - `totals(0)` is a legal-looking function call. It only fails once Python actually tries to call a list as if it were a function.', 'A `TypeError` mentioning "not callable" almost always means `()` was used where `[]` was meant.', NULL, 'published', 'e0e246107c8f6c7088114595dbbae0d02318bcfc67a05d3804094e91c43a4a9c', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-list-not-callable'), 1, 'get_first([10, 20, 30])', '([10, 20, 30],)', NULL, NULL, 'returns', '10', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-list-not-callable'), 2, 'get_first([5])', '([5],)', NULL, NULL, 'returns', '5', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-list-not-callable'), 3, 'get_first([1, 2, 3, 4])', '([1, 2, 3, 4],)', NULL, NULL, 'returns', '1', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-list-not-callable'), 1, 'The error says something isn''t callable - that''s a strong clue about which bracket is wrong.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-list-not-callable'), 2, '`totals` is a list. Calling it like a function with `()` isn''t the same as indexing into it.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-list-not-callable'), 3, 'Change `totals(0)` to `totals[0]`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-list-not-callable'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'bracket-types'), 'Round brackets `()` call something; square brackets `[]` index into it. `totals` is a list, so it needs `[]`.', 'Change `totals(0)` to `totals[0]`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-list-not-callable'), (SELECT id FROM bh_concepts WHERE slug = 'bracket-types'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('typeerror-int-not-iterable', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Looping Over a Number', 14, 1, NULL, 'runtime', '`digits_of(n)` should return a list of the digits of `n` as characters.

Example: `digits_of(123)` should return `["1", "2", "3"]`.', 'def digits_of(n):
    result = []
    for digit in n:
        result.append(digit)
    return result
', 'def digits_of(n):
    result = []
    for digit in str(n):
        result.append(digit)
    return result
', 'function', 'digits_of', 'A `for` loop needs something iterable - a sequence of values to step through. A whole number is a single value, not a sequence, so Python has nothing to loop over until you convert it to something that is, like a string.', '"not iterable" in the error means check what type the thing after `in` actually is.', NULL, 'published', 'e38e9db5521eb8755e4aacd505d9d3842bd4f40c1443a4b015b2f58685d70832', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-int-not-iterable'), 1, 'digits_of(123)', '(123,)', NULL, NULL, 'returns', '["1", "2", "3"]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-int-not-iterable'), 2, 'digits_of(7)', '(7,)', NULL, NULL, 'returns', '["7"]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-int-not-iterable'), 3, 'digits_of(0)', '(0,)', NULL, NULL, 'returns', '["0"]', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-int-not-iterable'), 1, 'The error says a number is "not iterable" - `for` only works on things you can step through.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-int-not-iterable'), 2, 'You can loop over the characters of a string, but not the digits of a number directly.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-int-not-iterable'), 3, 'Convert `n` to a string first: `for digit in str(n):`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-int-not-iterable'), 1, 3, 3, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'types-and-conversion'), 'You cannot loop directly over an `int` - only over things like strings, lists and other collections.', 'Convert `n` to a string with `str(n)` before looping over it.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-int-not-iterable'), (SELECT id FROM bh_concepts WHERE slug = 'types-and-conversion'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('typeerror-int-not-subscriptable', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Indexing a Number', 15, 1, NULL, 'runtime', '`get_units(n)` should return the units (last) digit of `n`, as an integer.

Example: `get_units(123)` should return `3`.', 'def get_units(n):
    return n[-1]
', 'def get_units(n):
    return int(str(n)[-1])
', 'function', 'get_units', '"not subscriptable" means the object does not support `[]` indexing at all. Converting between types - here, number to string and back - is how you get at individual digits.', 'If `[]` on a number crashes, convert it to a string first.', NULL, 'published', 'b7805e8e727782d2cbd7dbbc8db8e84c92b7fa15fcb80c95c3cdcc3ab8185036', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-int-not-subscriptable'), 1, 'get_units(123)', '(123,)', NULL, NULL, 'returns', '3', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-int-not-subscriptable'), 2, 'get_units(7)', '(7,)', NULL, NULL, 'returns', '7', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-int-not-subscriptable'), 3, 'get_units(500)', '(500,)', NULL, NULL, 'returns', '0', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-int-not-subscriptable'), 1, 'The error says a number is "not subscriptable" - indexing with `[]` only works on sequences.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-int-not-subscriptable'), 2, 'To get at individual digits, convert the number to a string first, then convert the result back.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-int-not-subscriptable'), 3, 'Use `int(str(n)[-1])`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-int-not-subscriptable'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'types-and-conversion'), 'An `int` cannot be indexed with `[]` - only sequences like strings and lists can.', 'Convert to a string, index it, then convert the single character back to an `int`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-int-not-subscriptable'), (SELECT id FROM bh_concepts WHERE slug = 'types-and-conversion'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('indexerror-negative-overflow', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Negative Index Out of Range', 16, 2, NULL, 'runtime', '`second_to_last(scores)` should return the second-to-last score, or `None` if there are fewer than two scores.

Example: `second_to_last([10, 20, 30])` should return `20`.', 'def second_to_last(scores):
    return scores[-2]
', 'def second_to_last(scores):
    if len(scores) < 2:
        return None
    return scores[-2]
', 'function', 'second_to_last', 'Negative indexes (`-1`, `-2`, ...) count backwards from the end, but they are just as capable of going out of range as positive ones - a one-item list has no `-2`.', 'Before using a negative index, check the collection is actually long enough for it.', NULL, 'published', 'b0cf7be6ce94ebd63d6386ece02041df3f64cbac374a90bf0e2175008bb60275', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-negative-overflow'), 1, 'second_to_last([10, 20, 30])', '([10, 20, 30],)', NULL, NULL, 'returns', '20', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-negative-overflow'), 2, 'second_to_last([5, 6])', '([5, 6],)', NULL, NULL, 'returns', '5', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-negative-overflow'), 3, 'second_to_last([9])', '([9],)', NULL, NULL, 'returns', 'None', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-negative-overflow'), 1, 'Negative indexes count from the end - but they can still go out of range.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-negative-overflow'), 2, 'What happens when the list is too short to have a "second to last" item?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-negative-overflow'), 3, 'Check `len(scores) < 2` first, and return `None` in that case.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-negative-overflow'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'indexing'), '`scores[-2]` crashes if `scores` has fewer than two items - negative indexes are still bounded by the list''s actual length.', 'Check the length first and return `None` for a too-short list.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-negative-overflow'), (SELECT id FROM bh_concepts WHERE slug = 'indexing'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('keyerror-pop-missing', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Popping a Missing Key', 17, 1, NULL, 'runtime', '`remove_item(cart, item)` should remove `item` from the `cart` dictionary if present, and return the dictionary either way.

Example: `remove_item({"apple": 1, "pear": 2}, "apple")` should return `{"pear": 2}`.', 'def remove_item(cart, item):
    cart.pop(item)
    return cart
', 'def remove_item(cart, item):
    if item in cart:
        cart.pop(item)
    return cart
', 'function', 'remove_item', '`.pop()` removes and returns a value by key, but like direct indexing, it crashes if the key doesn''t exist. Checking membership first (or using `.pop(key, default)`) avoids the crash.', 'Before popping a dictionary key that might not exist, check for it first or supply a default.', NULL, 'published', 'db67b545faae08e3d26324d2d8cb882be85d6ddd54e3622b06335fb5cc102f93', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'keyerror-pop-missing'), 1, 'remove_item({"apple": 1, "pear": 2}, "apple")', '({''apple'': 1, ''pear'': 2}, ''apple'')', NULL, NULL, 'returns', '{"pear": 2}', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'keyerror-pop-missing'), 2, 'remove_item({"apple": 1}, "banana")', '({''apple'': 1}, ''banana'')', NULL, NULL, 'returns', '{"apple": 1}', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'keyerror-pop-missing'), 3, 'remove_item({}, "pear")', '({}, ''pear'')', NULL, NULL, 'returns', '{}', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'keyerror-pop-missing'), 1, 'This crashes with a `KeyError` - the exact same idea as indexing a missing dictionary key.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'keyerror-pop-missing'), 2, '`.pop()` on a dictionary needs the key to actually be there, unless you check first.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'keyerror-pop-missing'), 3, 'Check `if item in cart:` before calling `.pop(item)`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'keyerror-pop-missing'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'dictionaries'), '`.pop(key)` raises `KeyError` if `key` isn''t in the dictionary, the same as `dict[key]` would.', 'Check `item in cart` before popping it.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'keyerror-pop-missing'), (SELECT id FROM bh_concepts WHERE slug = 'dictionaries'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('indexerror-pop-empty', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Popping From an Empty List', 18, 1, NULL, 'runtime', '`take_turn(queue)` should remove and return the first item in `queue`, or `None` if `queue` is empty.

Example: `take_turn([1, 2, 3])` should return `1`.', 'def take_turn(queue):
    return queue.pop(0)
', 'def take_turn(queue):
    if not queue:
        return None
    return queue.pop(0)
', 'function', 'take_turn', 'Removing an item by position only works if that position actually exists - an empty list has no position `0`, so `.pop(0)` crashes exactly like indexing past the end would.', 'Before popping from a list that might be empty, check it first.', NULL, 'published', '4dc496ea3629f1f210fb78e3ed1865f3e146f7a62aa3770cbf46b73848182504', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-pop-empty'), 1, 'take_turn([1, 2, 3])', '([1, 2, 3],)', NULL, NULL, 'returns', '1', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-pop-empty'), 2, 'take_turn([5])', '([5],)', NULL, NULL, 'returns', '5', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-pop-empty'), 3, 'take_turn([])', '([],)', NULL, NULL, 'returns', 'None', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-pop-empty'), 1, 'This crashes with an `IndexError` - the same family as indexing past the end of a list.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-pop-empty'), 2, 'There is nothing at position 0 of an empty list to remove.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-pop-empty'), 3, 'Check `if not queue:` first and return `None` in that case.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-pop-empty'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'indexing'), '`.pop(0)` on an empty list has nothing to remove, which raises an `IndexError`.', 'Check whether `queue` is empty before popping from it.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-pop-empty'), (SELECT id FROM bh_concepts WHERE slug = 'indexing'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('typeerror-len-on-int', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Length of a Number', 19, 1, NULL, 'runtime', '`count_digits(n)` should return how many digits `n` has.

Example: `count_digits(123)` should return `3`.', 'def count_digits(n):
    return len(n)
', 'def count_digits(n):
    return len(str(n))
', 'function', 'count_digits', '`len()` counts the items in a sequence. A number on its own is not a sequence - converting it to a string first turns it into one, letting you count its digits.', '"object of type ''int'' has no len()" means you need a conversion before measuring length.', NULL, 'published', '9e9bf39ebce2fd818b52e419ea739df2e93b2055314bc62d9a02a646ac7187bf', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-len-on-int'), 1, 'count_digits(123)', '(123,)', NULL, NULL, 'returns', '3', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-len-on-int'), 2, 'count_digits(7)', '(7,)', NULL, NULL, 'returns', '1', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-len-on-int'), 3, 'count_digits(10000)', '(10000,)', NULL, NULL, 'returns', '5', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-len-on-int'), 1, '`len()` only works on things with a length - a plain number does not have one.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-len-on-int'), 2, 'Converting the number to a string gives you something `len()` can measure.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-len-on-int'), 3, 'Use `len(str(n))`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-len-on-int'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'types-and-conversion'), '`len()` works on sequences (strings, lists, ...), not on a plain `int`.', 'Convert `n` to a string before measuring its length.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-len-on-int'), (SELECT id FROM bh_concepts WHERE slug = 'types-and-conversion'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('valueerror-int-with-text', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Parsing a Number With Extra Text', 20, 2, NULL, 'runtime', '`parse_age(text)` should return the age as an integer, from text like `"25 years"`.

Example: `parse_age("25 years")` should return `25`.', 'def parse_age(text):
    return int(text)
', 'def parse_age(text):
    return int(text.split()[0])
', 'function', 'parse_age', '`int(text)` expects `text` to be exactly a number, with nothing else around it. Real-world text often needs cleaning up - splitting, stripping, or slicing - before it is safe to convert.', 'If a `ValueError` happens converting user text to a number, check for extra characters sneaking in alongside the digits.', NULL, 'published', '51f31d036c9fbb4d74661f4227dfb82bc660cc3a12444a9b2e99756f1a75dae0', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'valueerror-int-with-text'), 1, 'parse_age("25 years")', '(''25 years'',)', NULL, NULL, 'returns', '25', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'valueerror-int-with-text'), 2, 'parse_age("7")', '(''7'',)', NULL, NULL, 'returns', '7', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'valueerror-int-with-text'), 3, 'parse_age("100 years old")', '(''100 years old'',)', NULL, NULL, 'returns', '100', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'valueerror-int-with-text'), 1, '`int()` needs text that looks like just a number, nothing else.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'valueerror-int-with-text'), 2, 'Splitting the text on spaces gives you the first word on its own.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'valueerror-int-with-text'), 3, 'Use `int(text.split()[0])`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'valueerror-int-with-text'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'types-and-conversion'), '`int()` cannot parse text that contains anything other than digits (and an optional sign) - `"25 years"` has extra words in it.', 'Split the text and convert only the first word.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'valueerror-int-with-text'), (SELECT id FROM bh_concepts WHERE slug = 'types-and-conversion'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('typeerror-list-plus-int', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Adding a Number to a List', 21, 2, NULL, 'runtime', '`add_bonus(scores, bonus)` should return a new list with `bonus` added to every score.

Example: `add_bonus([1, 2, 3], 5)` should return `[6, 7, 8]`.', 'def add_bonus(scores, bonus):
    return scores + bonus
', 'def add_bonus(scores, bonus):
    return [s + bonus for s in scores]
', 'function', 'add_bonus', '`+` means different things for different types: numeric addition for numbers, concatenation for lists (list-plus-list only). Mixing a list with a plain number is not defined.', 'If you want to apply an operation to every item in a list, use a loop or comprehension - `+` on the list itself concatenates, it does not map.', NULL, 'published', 'e6444acdde98fecb6f592ed3a711a42182f32d843935bafb79f104eebdbe9866', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-list-plus-int'), 1, 'add_bonus([1, 2, 3], 5)', '([1, 2, 3], 5)', NULL, NULL, 'returns', '[6, 7, 8]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-list-plus-int'), 2, 'add_bonus([0], 10)', '([0], 10)', NULL, NULL, 'returns', '[10]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-list-plus-int'), 3, 'add_bonus([1, 1, 1], 1)', '([1, 1, 1], 1)', NULL, NULL, 'returns', '[2, 2, 2]', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-list-plus-int'), 1, '`+` between a list and a number is not allowed - only list-plus-list is.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-list-plus-int'), 2, 'You want to add `bonus` to every item, not add `bonus` to the list itself.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-list-plus-int'), 3, 'Use a list comprehension: `[s + bonus for s in scores]`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-list-plus-int'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'types-and-conversion'), '`list + int` is not a valid operation - `+` on a list only works with another list.', 'Add `bonus` to each item individually with a list comprehension.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-list-plus-int'), (SELECT id FROM bh_concepts WHERE slug = 'types-and-conversion'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('typeerror-compare-str-int', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Comparing a Number to Text', 22, 1, NULL, 'runtime', '`is_adult(age)` should return `True` if `age` is 18 or over.

Example: `is_adult(20)` should return `True`.', 'def is_adult(age):
    return age >= "18"
', 'def is_adult(age):
    return age >= 18
', 'function', 'is_adult', 'A stray pair of quote marks turns a number into text. Python won''t guess which one you meant when comparing sizes - `int` and `str` just are not comparable that way.', 'If a comparison crashes with a type error, check both sides are actually the type you think they are.', NULL, 'published', '0fe7bd5d10fd37ea9fccd3a6ba84cf4e74613a1bdabbd5b848d997abee5ae077', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-compare-str-int'), 1, 'is_adult(20)', '(20,)', NULL, NULL, 'returns', 'True', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-compare-str-int'), 2, 'is_adult(10)', '(10,)', NULL, NULL, 'returns', 'False', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-compare-str-int'), 3, 'is_adult(18)', '(18,)', NULL, NULL, 'returns', 'True', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-compare-str-int'), 1, 'Python refuses to say whether a number is bigger than a piece of text - they are not comparable.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-compare-str-int'), 2, 'Look closely at the `18` on the right of `>=` - is it really a number?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-compare-str-int'), 3, 'Remove the quote marks: `age >= 18`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-compare-str-int'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'types-and-conversion'), '`"18"` is a string, not a number - comparing an `int` to a `str` with `>=` is not supported.', 'Use the number `18`, not the string `"18"`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-compare-str-int'), (SELECT id FROM bh_concepts WHERE slug = 'types-and-conversion'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('attributeerror-method-typo', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'A Typo in a Method Name', 23, 1, NULL, 'runtime', '`add_item(cart, item)` should add `item` to the end of the `cart` list and return it.

Example: `add_item([], "apple")` should return `["apple"]`.', 'def add_item(cart, item):
    cart.appned(item)
    return cart
', 'def add_item(cart, item):
    cart.append(item)
    return cart
', 'function', 'add_item', 'A single swapped letter is enough to turn a real method into an undefined one. The error message spells out the exact (wrong) name it tried to find - comparing it letter by letter against the real method usually reveals the typo instantly.', 'When an `AttributeError` names a method that *looks* right, check it letter by letter - it''s often one character off.', NULL, 'published', '5b27ce91d9d0a9010e58e8214ff3bc2e7ebc6ce5a8819ae96d21b14667f2ab2b', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-method-typo'), 1, 'add_item([], "apple")', '([], ''apple'')', NULL, NULL, 'returns', '["apple"]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-method-typo'), 2, 'add_item(["pear"], "fig")', '([''pear''], ''fig'')', NULL, NULL, 'returns', '["pear", "fig"]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-method-typo'), 3, 'add_item([], "x")', '([], ''x'')', NULL, NULL, 'returns', '["x"]', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-method-typo'), 1, 'The error names the exact method it looked for - read it character by character.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-method-typo'), 2, 'There''s a real list method that adds one item to the end, spelled slightly differently to this.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-method-typo'), 3, 'Change `.appned` to `.append`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-method-typo'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'string-methods'), '`.appned` is a typo of `.append` - no such method exists on a list.', 'Fix the spelling: `.append(item)`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-method-typo'), (SELECT id FROM bh_concepts WHERE slug = 'string-methods'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('indexerror-while-loop', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'One Step Too Far in a while Loop', 24, 2, NULL, 'runtime', '`find_first_negative(numbers)` should return the first negative number in the list, or `None` if there isn''t one.

Example: `find_first_negative([1, -2, 3])` should return `-2`.', 'def find_first_negative(numbers):
    i = 0
    while i <= len(numbers):
        if numbers[i] < 0:
            return numbers[i]
        i += 1
    return None
', 'def find_first_negative(numbers):
    i = 0
    while i < len(numbers):
        if numbers[i] < 0:
            return numbers[i]
        i += 1
    return None
', 'function', 'find_first_negative', 'A `while` loop walking through a list by index needs to stop one short of the list''s length, not at it - `len(numbers)` is one past the last valid index.', 'In a manual `while` loop over indexes, double-check the boundary: is it `<` or `<=`, and is that actually correct?', NULL, 'published', 'ac4d9798eba7a4a244b66846796e405ae7446c17017e81a72b62329f6bc737c3', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-while-loop'), 1, 'find_first_negative([1, -2, 3])', '([1, -2, 3],)', NULL, NULL, 'returns', '-2', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-while-loop'), 2, 'find_first_negative([1, 2, 3])', '([1, 2, 3],)', NULL, NULL, 'returns', 'None', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-while-loop'), 3, 'find_first_negative([-1])', '([-1],)', NULL, NULL, 'returns', '-1', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-while-loop'), 1, 'When there''s no negative number, this crashes right at the end of the list - that timing is a clue.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-while-loop'), 2, 'Compare the `while` condition to the valid index range of the list - `len(numbers)` itself is never a valid index.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-while-loop'), 3, 'Change `i <= len(numbers)` to `i < len(numbers)`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-while-loop'), 1, 3, 3, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'off-by-one'), 'The loop continues while `i <= len(numbers)`, but the valid indexes only go up to `len(numbers) - 1` - at `i == len(numbers)` the index is out of range.', 'Change `<=` to `<`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-while-loop'), (SELECT id FROM bh_concepts WHERE slug = 'off-by-one'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('unboundlocal-leftover-print', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Using a Variable Before It Exists', 25, 3, NULL, 'runtime', '`total_with_tax(price)` should return `price` multiplied by 1.2.

Example: `total_with_tax(100)` should return `120.0`.', 'def total_with_tax(price):
    print(total)
    total = price * 1.2
    return total
', 'def total_with_tax(price):
    total = price * 1.2
    return total
', 'function', 'total_with_tax', 'Python decides whether a name is local to a function by scanning the *whole* function body for an assignment to it - not just the lines before the one you''re looking at. If it''s assigned anywhere in the function, every use of that name in that function is local, even before the assignment runs.', '`UnboundLocalError` almost always means a variable is assigned somewhere later in the same function - look for a leftover line that runs before that assignment.', NULL, 'published', 'dd59387b7706fbd23e624d187189fd4d6f065852f269c3372b0c3eced64c6361', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unboundlocal-leftover-print'), 1, 'total_with_tax(100)', '(100,)', NULL, NULL, 'returns', '120', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unboundlocal-leftover-print'), 2, 'total_with_tax(0)', '(0,)', NULL, NULL, 'returns', '0', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unboundlocal-leftover-print'), 3, 'total_with_tax(50)', '(50,)', NULL, NULL, 'returns', '60', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unboundlocal-leftover-print'), 1, 'The error is about a local variable being referenced before it has a value.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unboundlocal-leftover-print'), 2, 'Because `total` is assigned somewhere inside this function, Python treats it as local for the *whole* function - including the line before it is assigned.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unboundlocal-leftover-print'), 3, 'Remove the stray `print(total)` line that comes before `total` is ever assigned.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unboundlocal-leftover-print'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'names-and-scope'), '`total` is assigned later in this function, which makes it local throughout the whole function - so referencing it on the line before that assignment fails, rather than falling back to an outer `total` (there isn''t one here anyway).', 'Remove the leftover `print(total)` line written before `total` exists.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unboundlocal-leftover-print'), (SELECT id FROM bh_concepts WHERE slug = 'names-and-scope'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('wrong-args-round', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Too Many Arguments to round()', 26, 1, NULL, 'runtime', '`round_price(price)` should return `price` rounded to 2 decimal places.

Example: `round_price(19.995)` should return `20.0`.', 'def round_price(price):
    return round(price, 2, 10)
', 'def round_price(price):
    return round(price, 2)
', 'function', 'round_price', 'Every function - built-in or your own - has a fixed set of parameters it accepts. Supplying more arguments than it is written to take is a `TypeError`, not a logic bug.', 'If a `TypeError` mentions "takes at most N arguments", count exactly how many you actually passed.', NULL, 'published', '7ff2436f102ea750ad6e9175261bc6521b13f01bfe0870ef9fd2dbbe3ca63720', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-args-round'), 1, 'round_price(19.995)', '(19.995,)', NULL, NULL, 'returns', '20', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-args-round'), 2, 'round_price(5)', '(5,)', NULL, NULL, 'returns', '5', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-args-round'), 3, 'round_price(3.14159)', '(3.14159,)', NULL, NULL, 'returns', '3.14', 'float_tol', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-args-round'), 1, 'The error names the function and says how many arguments it actually accepts.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-args-round'), 2, '`round()` only ever takes a number and (optionally) how many decimal places - nothing more.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-args-round'), 3, 'Remove the extra `10`: `round(price, 2)`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-args-round'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'function-calls'), '`round()` takes at most two arguments (the number and the number of decimal places) - a third one is one too many.', 'Remove the extra third argument.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-args-round'), (SELECT id FROM bh_concepts WHERE slug = 'function-calls'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('keyerror-grade-lookup', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'A Subject That Was Never Taken', 27, 1, NULL, 'runtime', '`get_grade(grades, subject)` should return the grade for `subject`, or `"Not taken"` if it is not in `grades`.

Example: `get_grade({"Maths": "A"}, "Maths")` should return `"A"`.', 'def get_grade(grades, subject):
    return grades[subject]
', 'def get_grade(grades, subject):
    return grades.get(subject, "Not taken")
', 'function', 'get_grade', '`dict[key]` crashes if the key is missing; `dict.get(key, default)` returns `default` instead. Whenever a missing key is a normal, expected possibility (not a bug), `.get()` is the safer choice.', 'If a dictionary lookup could reasonably be missing, use `.get()` with a sensible default rather than direct indexing.', NULL, 'published', '06b873dad0e8bf8d4be841f4933b9219c37362f7a2e9f44f157031a8a0d33925', NOW());
