Example: `tag_route([1, 2, 3])` should return `1`.', 'def tag_route(stops):
    visited = {}
    visited[stops] = True
    return len(visited)
', 'def tag_route(stops):
    visited = {}
    visited[tuple(stops)] = True
    return len(visited)
', 'function', 'tag_route', 'Dictionary keys must be hashable, which roughly means "never changes after creation". Lists can be modified in place, so they''re explicitly disallowed as keys - tuples, which look similar but can''t be changed, work fine instead.', '"unhashable type: ''list''" means swap the list for a tuple if you need to use it as a dictionary key.', NULL, 'published', 'e2743624dd6d0ffc429653b807ae6b2f8685a398527d9c7ba610f09966ccfe90', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-unhashable-list-key'), 1, 'tag_route([1, 2, 3])', '([1, 2, 3],)', NULL, NULL, 'returns', '1', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-unhashable-list-key'), 2, 'tag_route([4, 5])', '([4, 5],)', NULL, NULL, 'returns', '1', 'exact', 0);
