Example: `last_char("hello")` should return `"o"`.', 'def last_char(word):
    return word[len(word)]
', 'def last_char(word):
    return word[len(word) - 1]
', 'function', 'last_char', 'A string of length `n` has valid indexes `0` through `n - 1`. Forgetting the `-1` is one of the most common off-by-one mistakes there is.', 'Whenever you index using `len(...)` directly, check whether you actually need `len(...) - 1`.', NULL, 'published', 'b90b4a0a8e2131caa52079dc2df4ae150e254275768a2f1d8f18b0e0d37e17ad', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-string-index'), 1, 'last_char("hello")', '(''hello'',)', NULL, NULL, 'returns', '"o"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'indexerror-string-index'), 2, 'last_char("a")', '(''a'',)', NULL, NULL, 'returns', '"a"', 'exact', 0);
