INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('nameerror-function-order', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Called Before It Existed', 31, 2, NULL, 'runtime', 'This program should print `Game started`.

Example output: `Game started`', 'def run_game():
    return "preparing"

result = run_game()
print(start_game())

def start_game():
    return "Game started"
', 'def run_game():
    return "preparing"

def start_game():
    return "Game started"

result = run_game()
print(start_game())
', 'script', NULL, 'Defining a function doesn''t make it exist at every point in the file - only from the moment Python actually runs that `def` line onwards. Calling it any earlier is a plain `NameError`, the same as any other undefined name.', 'If a `NameError` names something that is clearly defined later in the file, check the actual order the lines run in, not just where things appear on the page.', NULL, 'published', 'e026991c1370db2300ec827ee301d087b28c3bdb2badf764ce8d6ed508ebf6d6', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nameerror-function-order'), 1, 'prints Game started', NULL, NULL, '', 'stdout', '"Game started\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nameerror-function-order'), 2, 'prints Game started (repeat check)', NULL, NULL, '', 'stdout', '"Game started\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nameerror-function-order'), 1, 'This crashes with a `NameError` - but the name really is defined somewhere in this file.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nameerror-function-order'), 2, 'Python runs a script top to bottom. A function has to be *defined* before the line that calls it actually runs.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nameerror-function-order'), 3, 'Move the `def start_game():` block above the line that calls it.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nameerror-function-order'), 1, 5, 5, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'names-and-scope'), '`start_game()` is called before its `def` has been reached, so it does not exist yet at that point in the script.', 'Move the `start_game` definition above the code that calls it.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nameerror-function-order'), (SELECT id FROM bh_concepts WHERE slug = 'names-and-scope'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('attributeerror-sort-on-string', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Sorting a String in Place', 32, 1, NULL, 'runtime', '`sorted_letters(word)` should return the letters of `word` sorted alphabetically, as a string.

Example: `sorted_letters("bca")` should return `"abc"`.', 'def sorted_letters(word):
    word.sort()
    return word
', 'def sorted_letters(word):
    return "".join(sorted(word))
', 'function', 'sorted_letters', '`.sort()` is a list method that rearranges a list in place - it relies on the list being mutable. Strings are immutable, so there is no in-place sort; `sorted(...)` instead returns a brand new sorted sequence.', 'If you want a sorted version of a string, use `sorted()` (which returns a list) and join it back together - don''t look for an in-place `.sort()`.', NULL, 'published', 'c5bcea7d925682f40cad57f27fac7ff23df9d53c5d20a0a2e1cd8b1541e4b8ec', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-sort-on-string'), 1, 'sorted_letters("bca")', '(''bca'',)', NULL, NULL, 'returns', '"abc"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-sort-on-string'), 2, 'sorted_letters("hi")', '(''hi'',)', NULL, NULL, 'returns', '"hi"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-sort-on-string'), 3, 'sorted_letters("zyx")', '(''zyx'',)', NULL, NULL, 'returns', '"xyz"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-sort-on-string'), 1, 'Strings don''t have the method this is trying to use.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-sort-on-string'), 2, '`.sort()` changes a list in place. Strings can''t be changed in place at all - but there''s a function that builds a new sorted result instead.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-sort-on-string'), 3, 'Use `"".join(sorted(word))` instead.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-sort-on-string'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'string-methods'), 'Strings have no `.sort()` method because strings are immutable - they cannot be changed in place.', 'Use the `sorted()` function, which returns a new sorted list, then join it back into a string.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-sort-on-string'), (SELECT id FROM bh_concepts WHERE slug = 'string-methods'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('recursion-no-base-case', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Recursion With No Way Out', 33, 2, NULL, 'runtime', '`countdown(n)` should count down to 0 and return `"Liftoff!"`.

Example: `countdown(3)` should return `"Liftoff!"`.', 'def countdown(n):
    return countdown(n - 1)
', 'def countdown(n):
    if n <= 0:
        return "Liftoff!"
    return countdown(n - 1)
', 'function', 'countdown', 'Every recursive function needs a base case - a condition where it stops calling itself and just returns a value directly. Without one, it recurses until Python hits its recursion limit and raises `RecursionError`.', 'When you write a recursive function, write the base case first, before the recursive call.', NULL, 'published', '1bb076a156f1bf23b522679be789464afbe52ce4ac9559f9d872ef51a004d1bc', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'recursion-no-base-case'), 1, 'countdown(3)', '(3,)', NULL, NULL, 'returns', '"Liftoff!"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'recursion-no-base-case'), 2, 'countdown(0)', '(0,)', NULL, NULL, 'returns', '"Liftoff!"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'recursion-no-base-case'), 1, 'This crashes after calling itself an enormous number of times - that specific error has a name.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'recursion-no-base-case'), 2, 'Every recursive function needs a condition that stops it calling itself again.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'recursion-no-base-case'), 3, 'Add `if n <= 0: return "Liftoff!"` before the recursive call.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'recursion-no-base-case'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'recursion'), 'There is no base case - `countdown` calls itself unconditionally, forever, until Python runs out of stack space.', 'Add a base case that returns without recursing once `n` reaches 0 or below.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'recursion-no-base-case'), (SELECT id FROM bh_concepts WHERE slug = 'recursion'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('stopiteration-manual-next', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Asking an Iterator for Too Much', 34, 2, NULL, 'runtime', '`first_two(items)` should return the first two items of `items` as a list.

Example: `first_two([1, 2, 3])` should return `[1, 2]`.', 'def first_two(items):
    it = iter(items)
    a = next(it)
    b = next(it)
    c = next(it)
    return [a, b, c]
', 'def first_two(items):
    it = iter(items)
    a = next(it)
    b = next(it)
    return [a, b]
', 'function', 'first_two', 'An iterator gives out one value per call to `next()`, and raises `StopIteration` once it has nothing left. Asking for more items than exist is a crash, not a graceful empty result.', 'Count exactly how many times you call `next()` against how many items you actually expect to be there.', NULL, 'published', 'bf24e7ddd6047eca7344dd85fb711019a6c666025fdc35dc3a0c02bd4487518c', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'stopiteration-manual-next'), 1, 'first_two([1, 2, 3])', '([1, 2, 3],)', NULL, NULL, 'returns', '[1, 2]', 'exact', 0);
