INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('zerodivision-modulo-zero', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Modulo by Zero', 35, 1, NULL, 'runtime', '`is_even_group(n, group_size)` should return whether `n` divides evenly into `group_size`-sized groups, or `False` if `group_size` is 0.

Example: `is_even_group(10, 5)` should return `True`.', 'def is_even_group(n, group_size):
    return n % group_size == 0
', 'def is_even_group(n, group_size):
    if group_size == 0:
        return False
    return n % group_size == 0
', 'function', 'is_even_group', 'Modulo (`%`) computes a remainder, which is undefined when dividing by zero - it raises the exact same `ZeroDivisionError` as ordinary division.', 'Don''t forget that `%` needs a zero-guard too, not just `/`.', NULL, 'published', 'fa818e8d297a85f84b51e8b33efb635e0d21bd2a4d5a308a7f01cfd3c458fb36', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'zerodivision-modulo-zero'), 1, 'is_even_group(10, 5)', '(10, 5)', NULL, NULL, 'returns', 'True', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'zerodivision-modulo-zero'), 2, 'is_even_group(7, 5)', '(7, 5)', NULL, NULL, 'returns', 'False', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'zerodivision-modulo-zero'), 3, 'is_even_group(10, 0)', '(10, 0)', NULL, NULL, 'returns', 'False', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'zerodivision-modulo-zero'), 1, '`%` (modulo) crashes for the same reason `/` does, in the same situation.');
