INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'zerodivision-modulo-zero'), (SELECT id FROM bh_concepts WHERE slug = 'zero-division-and-guards'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('typeerror-mixed-type-sum', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Starting a Total With the Wrong Type', 36, 2, NULL, 'runtime', '`total_price(prices)` should return the sum of the numbers in `prices`.

Example: `total_price([10, 20, 30])` should return `60`.', 'def total_price(prices):
    total = ""
    for p in prices:
        total += p
    return total
', 'def total_price(prices):
    total = 0
    for p in prices:
        total += p
    return total
', 'function', 'total_price', 'An accumulator''s starting value has to be the identity for whatever you''re accumulating - `0` for adding numbers, `""` for joining text, `[]` for building a list. Mixing them up crashes on the first step.', 'When a `TypeError` mentions concatenation on the very first loop iteration, check the accumulator''s starting value against what you''re actually adding to it.', NULL, 'published', '45e13bcef64861947c2a2cf83a30ee8982bc946ce07cb9dd19ea1c67d2b137d6', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-mixed-type-sum'), 1, 'total_price([10, 20, 30])', '([10, 20, 30],)', NULL, NULL, 'returns', '60', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-mixed-type-sum'), 2, 'total_price([5])', '([5],)', NULL, NULL, 'returns', '5', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-mixed-type-sum'), 3, 'total_price([1, 1, 1, 1])', '([1, 1, 1, 1],)', NULL, NULL, 'returns', '4', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-mixed-type-sum'), 1, 'This crashes on the very first number it tries to add.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-mixed-type-sum'), 2, 'The starting value for an accumulator needs to match the type of thing you are accumulating.');
