INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('attributeerror-keys-on-list', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Treating a List Like a Dictionary', 37, 1, NULL, 'runtime', '`unique_names(students)` should return the names in `students`, keeping only the first occurrence of each.

Example: `unique_names(["Ada", "Sam", "Ada"])` should return `["Ada", "Sam"]`.', 'def unique_names(students):
    return students.keys()
', 'def unique_names(students):
    seen = []
    for s in students:
        if s not in seen:
            seen.append(s)
    return seen
', 'function', 'unique_names', 'It''s easy to reach for a dictionary method out of habit when working with any collection - but lists and dictionaries have genuinely different methods, because they store data differently.', 'If an `AttributeError` names a dictionary-only method, double check the variable is actually a dictionary, not a list.', NULL, 'published', '5fd8fb51edae223b64a743151fd4629f84f7cd2f9f85af6f11e55b4e404fbf5a', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-keys-on-list'), 1, 'unique_names(["Ada", "Sam", "Ada"])', '([''Ada'', ''Sam'', ''Ada''],)', NULL, NULL, 'returns', '["Ada", "Sam"]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-keys-on-list'), 2, 'unique_names(["Sam"])', '([''Sam''],)', NULL, NULL, 'returns', '["Sam"]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-keys-on-list'), 3, 'unique_names([])', '([],)', NULL, NULL, 'returns', '[]', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-keys-on-list'), 1, '`.keys()` is specifically a dictionary method - check what type `students` actually is.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-keys-on-list'), 2, '`students` is a list of names, not a dictionary - there is no "keys" to ask for.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-keys-on-list'), 3, 'Build the unique list yourself with a loop, checking `if s not in seen`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-keys-on-list'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'dictionaries'), '`.keys()` only exists on dictionaries - `students` here is a list, which has no such method.', 'Loop through the list and collect names you have not already added.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'attributeerror-keys-on-list'), (SELECT id FROM bh_concepts WHERE slug = 'dictionaries'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('typeerror-unexpected-keyword', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'The Wrong Keyword Argument Name', 38, 3, NULL, 'runtime', '`checkout(price, tax)` should return `price + tax`.

Example: `checkout(10, 2)` should return `12`.', 'def compute_total(price, tax):
    return price + tax

def checkout(price, tax):
    return compute_total(prices=price, tax=tax)
', 'def compute_total(price, tax):
    return price + tax

def checkout(price, tax):
    return compute_total(price=price, tax=tax)
', 'function', 'checkout', 'When calling a function with `name=value` keyword arguments, `name` must exactly match one of the parameter names in that function''s definition - a near-miss spelling is just as invalid as a completely wrong name.', 'When a keyword argument is "unexpected", go back to the function definition and compare its exact parameter names.', NULL, 'published', '74c32c4f2d73df3fee95429e6a82296c4816c9a8e122d0c30cdd1dfcc5720a89', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-unexpected-keyword'), 1, 'checkout(10, 2)', '(10, 2)', NULL, NULL, 'returns', '12', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-unexpected-keyword'), 2, 'checkout(5, 0)', '(5, 0)', NULL, NULL, 'returns', '5', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-unexpected-keyword'), 3, 'checkout(100, 20)', '(100, 20)', NULL, NULL, 'returns', '120', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-unexpected-keyword'), 1, 'The error names an "unexpected keyword argument" - the name used does not match any real parameter.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-unexpected-keyword'), 2, 'Compare the keyword used in the call (`prices=`) to the parameter name in the function definition above it.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-unexpected-keyword'), 3, 'Change `prices=price` to `price=price`.');
