INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'typeerror-unexpected-keyword'), (SELECT id FROM bh_concepts WHERE slug = 'function-calls'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('valueerror-unpack-too-many', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Too Many Values to Unpack', 39, 2, NULL, 'runtime', '`split_name(full_name)` should return `[last_word, first_word]` from a space-separated name.

Example: `split_name("Ada Lovelace")` should return `["Lovelace", "Ada"]`.', 'def split_name(full_name):
    first, last = full_name.split(" ")
    return [last, first]
', 'def split_name(full_name):
    parts = full_name.split(" ")
    first = parts[0]
    last = parts[-1]
    return [last, first]
', 'function', 'split_name', 'Unpacking (`a, b = something`) requires exactly as many values on the right as names on the left. It is a convenient shorthand, but only safe when you are certain of the exact count.', 'If unpacking might receive a different number of values than expected, split into a list first and index into it instead.', NULL, 'published', 'c73f1ecf0f2e269ad926b3777e1b1bffbc5254a1f39d1aaa33b349cde35b3092', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'valueerror-unpack-too-many'), 1, 'split_name("Ada Lovelace")', '(''Ada Lovelace'',)', NULL, NULL, 'returns', '["Lovelace", "Ada"]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'valueerror-unpack-too-many'), 2, 'split_name("Ada Lovelace Byron")', '(''Ada Lovelace Byron'',)', NULL, NULL, 'returns', '["Byron", "Ada"]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'valueerror-unpack-too-many'), 3, 'split_name("Cher")', '(''Cher'',)', NULL, NULL, 'returns', '["Cher", "Cher"]', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'valueerror-unpack-too-many'), 1, 'This crashes only on names with more than two words - that timing is a clue.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'valueerror-unpack-too-many'), 2, '`a, b = something` needs `something` to have exactly two items - a three-word name splits into three.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'valueerror-unpack-too-many'), 3, 'Split into a list first, then take the first and last items with indexing instead of unpacking.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'valueerror-unpack-too-many'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'types-and-conversion'), 'Unpacking `first, last = full_name.split(" ")` requires exactly two parts - a name with three or more words produces more values than there are variables to catch them.', 'Split into a list and take the first and last items by index instead of unpacking directly.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'valueerror-unpack-too-many'), (SELECT id FROM bh_concepts WHERE slug = 'types-and-conversion'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('valueerror-unpack-too-few', (SELECT id FROM bh_tracks WHERE slug = 'crash-course'), 'Not Enough Values to Unpack', 40, 2, NULL, 'runtime', '`get_coordinates(point)` should return `[x, y]` from a 2-item point.

Example: `get_coordinates([3, 4])` should return `[3, 4]`.', 'def get_coordinates(point):
    x, y, z = point
    return [x, y]
', 'def get_coordinates(point):
    x, y = point
    return [x, y]
', 'function', 'get_coordinates', 'Just as unpacking fails with too many values, it fails the other way too - not enough values for the number of names you are trying to fill.', 'Before unpacking, check the number of names on the left genuinely matches the number of values you expect on the right.', NULL, 'published', 'dc98d676d05fa82c25f000c11e0c897a2a439e8b610b00e93832ed73c0d34a09', NOW());
