INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('sum-to-n-off-by-one', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'The Missing Number', 1, 2, NULL, 'logic', '`sum_to(n)` should return the sum of all whole numbers from 1 up to and including `n`.

Example: `sum_to(4)` should return `10` (1 + 2 + 3 + 4).', 'def sum_to(n):
    total = 0
    for i in range(1, n):
        total += i
    return total
', 'def sum_to(n):
    total = 0
    for i in range(1, n + 1):
        total += i
    return total
', 'function', 'sum_to', 'Python''s `range(a, b)` includes `a` but excludes `b` - a deliberate design choice that trips almost everyone up at least once. Whenever a loop should include the upper value, add one to the second argument.', 'Any time you loop with `range`, check the first and last values by hand with a tiny input like `n = 1` or `n = 2`.', 'What do you think `sum_to(4)` returns? Write it down before you run anything.', 'published', 'c2cce40ef041d810d878a68da015a43af8c9b0d5a1a112bad5741ddb7f2f0d96', NOW());
