INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('string-concat-not-sum', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'Adding Scores Given as Text', 17, 2, NULL, 'logic', '`total_score(score1, score2)` should return the sum of two scores given as text.

Example: `total_score("10", "20")` should return `30`.', 'def total_score(score1, score2):
    return score1 + score2
', 'def total_score(score1, score2):
    return int(score1) + int(score2)
', 'function', 'total_score', '`+` does different things depending on type: numeric addition for numbers, concatenation for strings. Text that looks like a number is still a string until you explicitly convert it.', 'If `+` on numbers-that-look-like-text gives a suspiciously long result instead of a sum, you''re concatenating, not adding.', NULL, 'published', '98df5163d366c600673bad12ea43f5c937d14c52ca8b1e48bfb1bc1f6c889298', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'string-concat-not-sum'), 1, 'total_score("10", "20")', '(''10'', ''20'')', NULL, NULL, 'returns', '30', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'string-concat-not-sum'), 2, 'total_score("5", "5")', '(''5'', ''5'')', NULL, NULL, 'returns', '10', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'string-concat-not-sum'), 3, 'total_score("100", "1")', '(''100'', ''1'')', NULL, NULL, 'returns', '101', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'string-concat-not-sum'), 1, 'Check the actual value this returns for `"10"` and `"20"` - is it a number, or something else?');
