INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'string-concat-not-sum'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'types-and-conversion'), '`score1 + score2` concatenates the two strings (`"10" + "20"` gives `"1020"`) instead of adding their numeric values - no error, just the wrong kind of answer.', 'Convert both arguments to `int` before adding them.');
