INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('sorted-ascending-not-descending', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'Top Scores, Sorted the Wrong Way', 18, 2, NULL, 'logic', '`top_scores(scores)` should return the 3 highest scores, highest first.

Example: `top_scores([5, 1, 9, 3, 7])` should return `[9, 7, 5]`.', 'def top_scores(scores):
    return sorted(scores)[:3]
', 'def top_scores(scores):
    return sorted(scores, reverse=True)[:3]
', 'function', 'top_scores', '`sorted()` always sorts ascending unless told otherwise. "Top N" or "highest first" always needs `reverse=True` (or sorting by a negated key).', 'Whenever you see "top" or "highest" alongside `sorted()`, check for `reverse=True`.', NULL, 'published', '061460d9c6e82f1904448a426843b42df4fd8d1d2e46f8110e6bf29cfc1ad585', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sorted-ascending-not-descending'), 1, 'top_scores([5, 1, 9, 3, 7])', '([5, 1, 9, 3, 7],)', NULL, NULL, 'returns', '[9, 7, 5]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sorted-ascending-not-descending'), 2, 'top_scores([1, 2])', '([1, 2],)', NULL, NULL, 'returns', '[2, 1]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sorted-ascending-not-descending'), 3, 'top_scores([10, 20, 30, 5])', '([10, 20, 30, 5],)', NULL, NULL, 'returns', '[30, 20, 10]', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sorted-ascending-not-descending'), 1, 'Check whether the result actually contains the *highest* scores, or the lowest.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sorted-ascending-not-descending'), 2, '`sorted()` arranges smallest-to-largest by default - taking the first 3 of that gives the lowest, not the highest.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sorted-ascending-not-descending'), 3, 'Add `reverse=True` so the sort runs largest-to-smallest.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sorted-ascending-not-descending'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'sorting'), '`sorted()` defaults to ascending order, so `[:3]` takes the 3 *smallest* values, not the 3 largest.', 'Pass `reverse=True` to sort largest-first.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sorted-ascending-not-descending'), (SELECT id FROM bh_concepts WHERE slug = 'sorting'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('lexicographic-number-compare', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'Comparing Numbers Stored as Text', 19, 3, NULL, 'logic', '`highest_id(ids)` should return the numerically largest id from a list of id strings.

Example: `highest_id(["9", "10", "2"])` should return `"10"`.', 'def highest_id(ids):
    return max(ids)
', 'def highest_id(ids):
    return max(ids, key=int)
', 'function', 'highest_id', 'Comparing strings never looks at their numeric meaning - `"9"` and `"10"` are compared letter by letter, the same way a dictionary orders words, and `"9"` comes after `"10"` that way purely because `''9''` is a "bigger" character than `''1''`.', 'If you are comparing numbers that happen to be stored as text, convert them (or supply a `key=int`) before comparing.', 'What do you think `highest_id(["9", "10", "2"])` returns? Write it down before you run anything.', 'published', '79b2602256470926dc60844e1d73913a84313fc220f13a43607a1ec2ee72ef76', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'lexicographic-number-compare'), 1, 'highest_id(["9", "10", "2"])', '([''9'', ''10'', ''2''],)', NULL, NULL, 'returns', '"10"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'lexicographic-number-compare'), 2, 'highest_id(["1", "2", "3"])', '([''1'', ''2'', ''3''],)', NULL, NULL, 'returns', '"3"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'lexicographic-number-compare'), 3, 'highest_id(["100", "99"])', '([''100'', ''99''],)', NULL, NULL, 'returns', '"100"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'lexicographic-number-compare'), 1, 'Try `highest_id(["9", "10", "2"])` - "10" should win numerically, but does it?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'lexicographic-number-compare'), 2, 'Comparing strings compares them character by character, like a dictionary - `"9"` comes after `"1"` that way, even though 9 is smaller than 10.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'lexicographic-number-compare'), 3, 'Tell `max()` to compare by numeric value: `max(ids, key=int)`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'lexicographic-number-compare'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'types-and-conversion'), '`max()` on strings compares them character by character (lexicographically), not numerically - `"9"` sorts after `"10"` that way.', 'Use `max(ids, key=int)` to compare by numeric value instead.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'lexicographic-number-compare'), (SELECT id FROM bh_concepts WHERE slug = 'types-and-conversion'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('truncation-not-rounding', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'Truncating Instead of Rounding', 20, 2, NULL, 'logic', '`nearest_dollar(cents)` should return the nearest whole number of dollars.

Example: `nearest_dollar(149)` should return `1`.', 'def nearest_dollar(cents):
    return int(cents / 100)
', 'def nearest_dollar(cents):
    return round(cents / 100)
', 'function', 'nearest_dollar', '`int(x)` and `round(x)` are not the same thing: `int()` just chops off everything after the decimal point, while `round()` picks the nearest whole number - the difference shows up for any value with a fractional part of 0.5 or more.', 'If a value should round to the "nearest" whole number rather than always down, use `round()`, not `int()`.', NULL, 'published', 'f416fea1432133c4a9fc5ec0861d352b50e4950f318983b55870cbfbd5ef06f5', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'truncation-not-rounding'), 1, 'nearest_dollar(149)', '(149,)', NULL, NULL, 'returns', '1', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'truncation-not-rounding'), 2, 'nearest_dollar(350)', '(350,)', NULL, NULL, 'returns', '4', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'truncation-not-rounding'), 3, 'nearest_dollar(199)', '(199,)', NULL, NULL, 'returns', '2', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'truncation-not-rounding'), 1, 'Try an amount very close to the next whole dollar, like 199 cents - should that round up or stay down?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'truncation-not-rounding'), 2, '`int(...)` always cuts off the decimal part - it never rounds up, no matter how close.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'truncation-not-rounding'), 3, 'Use `round(cents / 100)` instead of `int(cents / 100)`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'truncation-not-rounding'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'rounding'), '`int()` truncates (always rounds towards zero) rather than rounding to the nearest whole number.', 'Use `round()` instead of `int()`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'truncation-not-rounding'), (SELECT id FROM bh_concepts WHERE slug = 'rounding'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('wrong-grade-boundary', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'An Exclusive Grade Boundary', 21, 2, NULL, 'logic', '`grade(score)` should return `"A"` for 90 or above, `"B"` for 80 or above, and `"C"` otherwise.

Example: `grade(95)` should return `"A"`.', 'def grade(score):
    if score > 90:
        return "A"
    elif score > 80:
        return "B"
    else:
        return "C"
', 'def grade(score):
    if score >= 90:
        return "A"
    elif score >= 80:
        return "B"
    else:
        return "C"
', 'function', 'grade', '"90 or above" and "above 90" differ by exactly one value - the boundary itself. Reading the brief''s exact wording (inclusive or exclusive?) decides whether you need `>=` or `>`.', 'Test boundary values exactly - if the brief says "X or above", does your code''s `>` actually need to be `>=`?', NULL, 'published', 'a7d98b2676ffbdf3960301732b149dc9f788e93f1f77ee9ecc85752428174369', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-grade-boundary'), 1, 'grade(95)', '(95,)', NULL, NULL, 'returns', '"A"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-grade-boundary'), 2, 'grade(75)', '(75,)', NULL, NULL, 'returns', '"C"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-grade-boundary'), 3, 'grade(90)', '(90,)', NULL, NULL, 'returns', '"A"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-grade-boundary'), 1, 'Try the exact boundary value, 90, and check the brief again - should "90 or above" include 90 itself?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-grade-boundary'), 2, '`>` excludes the boundary value itself; `>=` includes it.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-grade-boundary'), 3, 'Change both `>` to `>=`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-grade-boundary'), 1, 2, 4, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'off-by-one'), '`score > 90` excludes a score of exactly 90, but the brief says 90 should count as "A".', 'Change `>` to `>=` on both boundaries.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-grade-boundary'), (SELECT id FROM bh_concepts WHERE slug = 'off-by-one'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('case-sensitive-name-match', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'A Name Lookup That Cares About Case', 22, 2, NULL, 'logic', '`is_registered(names, name)` should return whether `name` is in the list `names`, ignoring case.

Example: `is_registered(["Ada", "Sam"], "ada")` should return `True`.', 'def is_registered(names, name):
    return name in names
', 'def is_registered(names, name):
    return name.lower() in [n.lower() for n in names]
', 'function', 'is_registered', 'Membership checks (`in`) and equality (`==`) both compare text exactly, case included. "Ignoring case" always needs an explicit `.lower()` (or `.upper()`) on both sides being compared.', 'If a lookup should be "case-insensitive", check that both sides are actually lower-cased (or upper-cased) before comparing.', NULL, 'published', '195a31f466818e70e64d86ed0e450e291afee75279b03055062a86153d05c234', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'case-sensitive-name-match'), 1, 'is_registered(["Ada", "Sam"], "ada")', '([''Ada'', ''Sam''], ''ada'')', NULL, NULL, 'returns', 'True', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'case-sensitive-name-match'), 2, 'is_registered(["Ada"], "Bob")', '([''Ada''], ''Bob'')', NULL, NULL, 'returns', 'False', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'case-sensitive-name-match'), 3, 'is_registered(["SAM"], "sam")', '([''SAM''], ''sam'')', NULL, NULL, 'returns', 'True', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'case-sensitive-name-match'), 1, 'Try a name that is spelled right but in different letter-case to how it was stored.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'case-sensitive-name-match'), 2, '`in` compares text exactly, including case - `"ada"` and `"Ada"` are different strings to Python.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'case-sensitive-name-match'), 3, 'Lower-case both sides before comparing.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'case-sensitive-name-match'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'case-sensitivity'), '`name in names` compares text exactly as written - it treats `"ada"` and `"Ada"` as completely different.', 'Convert both the name and the list to lower case before checking membership.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'case-sensitive-name-match'), (SELECT id FROM bh_concepts WHERE slug = 'case-sensitivity'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('is-not-equality-for-lists', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'is Instead of == for Lists', 23, 3, NULL, 'logic', '`same_order(list1, list2)` should return whether the two lists contain the same values in the same order.

Example: `same_order([1, 2, 3], [1, 2, 3])` should return `True`.', 'def same_order(list1, list2):
    return list1 is list2
', 'def same_order(list1, list2):
    return list1 == list2
', 'function', 'same_order', '`==` asks "do these have the same value?"; `is` asks "are these the exact same object?". Two freshly-built lists with identical contents will always fail an `is` check, even though they are equal.', 'Use `==` for value comparisons. Reserve `is` for identity checks like `x is None`.', NULL, 'published', '537769fe84e11a985a69e357bcba5dbe860554eed6e68074fbb87da429eb6ea9', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'is-not-equality-for-lists'), 1, 'same_order([1, 2, 3], [1, 2, 3])', '([1, 2, 3], [1, 2, 3])', NULL, NULL, 'returns', 'True', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'is-not-equality-for-lists'), 2, 'same_order([1, 2], [3, 4])', '([1, 2], [3, 4])', NULL, NULL, 'returns', 'False', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'is-not-equality-for-lists'), 3, 'same_order([], [])', '([], [])', NULL, NULL, 'returns', 'True', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'is-not-equality-for-lists'), 1, 'Call it with two separately-written lists that contain exactly the same values - does it say they match?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'is-not-equality-for-lists'), 2, '`is` checks whether two names refer to the *exact same object in memory* - two separately-built lists with equal contents are still two different objects.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'is-not-equality-for-lists'), 3, 'Change `is` to `==`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'is-not-equality-for-lists'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'identity-vs-equality'), '`is` checks object identity, not value equality - two lists with identical contents are still different objects unless they are literally the same one.', 'Use `==` to compare values instead of `is`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'is-not-equality-for-lists'), (SELECT id FROM bh_concepts WHERE slug = 'identity-vs-equality'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('wrong-range-step', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'Evens With the Wrong Step', 24, 2, NULL, 'logic', '`even_numbers_up_to(n)` should return a list of even numbers from 0 up to (not including) `n`.

Example: `even_numbers_up_to(10)` should return `[0, 2, 4, 6, 8]`.', 'def even_numbers_up_to(n):
    return list(range(0, n, 1))
', 'def even_numbers_up_to(n):
    return list(range(0, n, 2))
', 'function', 'even_numbers_up_to', '`range(start, stop, step)`''s third argument controls the gap between values. Stepping by 1 visits every number; stepping by 2 from an even start visits only even numbers.', 'When a range should skip values (evens, every third item, and so on), check its step argument matches that.', NULL, 'published', '06030cc923992948087df04599cf2aed3f58a460267719d8e259d94c19eff0c0', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-range-step'), 1, 'even_numbers_up_to(10)', '(10,)', NULL, NULL, 'returns', '[0, 2, 4, 6, 8]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-range-step'), 2, 'even_numbers_up_to(5)', '(5,)', NULL, NULL, 'returns', '[0, 2, 4]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-range-step'), 3, 'even_numbers_up_to(1)', '(1,)', NULL, NULL, 'returns', '[0]', 'exact', 1);
