INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-range-step'), (SELECT id FROM bh_concepts WHERE slug = 'range-function'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('off-by-one-first-n-chars', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'One Character Short', 25, 2, NULL, 'logic', '`first_n_chars(text, n)` should return the first `n` characters of `text`.

Example: `first_n_chars("hello", 3)` should return `"hel"`.', 'def first_n_chars(text, n):
    return text[0:n-1]
', 'def first_n_chars(text, n):
    return text[0:n]
', 'function', 'first_n_chars', 'Python slice bounds are already "up to but not including" the end value, so `text[0:n]` already gives exactly `n` characters - no further adjustment needed.', 'Before adding a `-1` or `+1` to a slice bound, check whether the slice already does what you think it does.', NULL, 'published', '3c147132ca9f6f7e7a4108a1a3febea3507bf8ec3fde2021316d90bd18ade815', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'off-by-one-first-n-chars'), 1, 'first_n_chars("hello", 3)', '(''hello'', 3)', NULL, NULL, 'returns', '"hel"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'off-by-one-first-n-chars'), 2, 'first_n_chars("hi", 2)', '(''hi'', 2)', NULL, NULL, 'returns', '"hi"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'off-by-one-first-n-chars'), 3, 'first_n_chars("python", 1)', '(''python'', 1)', NULL, NULL, 'returns', '"p"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'off-by-one-first-n-chars'), 1, 'Count the characters in the result - is it actually `n` characters long?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'off-by-one-first-n-chars'), 2, 'A slice `text[0:n]` already stops *before* position `n` - it does not need an extra `-1`.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'off-by-one-first-n-chars'), 3, 'Change `text[0:n-1]` to `text[0:n]`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'off-by-one-first-n-chars'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'off-by-one'), 'A slice `text[0:n]` already stops before index `n`, giving exactly `n` characters - subtracting an extra 1 cuts one character too many.', 'Remove the `-1`: use `text[0:n]`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'off-by-one-first-n-chars'), (SELECT id FROM bh_concepts WHERE slug = 'off-by-one'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('early-break-skips-remaining', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'Stopping at the First Negative', 26, 2, NULL, 'logic', '`count_positives(numbers)` should return how many numbers in the list are positive.

Example: `count_positives([1, -2, 3])` should return `2`.', 'def count_positives(numbers):
    count = 0
    for n in numbers:
        if n > 0:
            count += 1
        else:
            break
    return count
', 'def count_positives(numbers):
    count = 0
    for n in numbers:
        if n > 0:
            count += 1
    return count
', 'function', 'count_positives', '`break` means "stop looking entirely", while simply not matching a condition means "skip this one, keep going". Counting *all* matches in a list needs the second behaviour, not the first.', 'If a loop is meant to examine every item, check whether a `break` is cutting it short partway through.', NULL, 'published', '02e85af075cd4d075e1aed529f01b869c440404b2b528a301a708e51b17b7ef0', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'early-break-skips-remaining'), 1, 'count_positives([1, 2, 3])', '([1, 2, 3],)', NULL, NULL, 'returns', '3', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'early-break-skips-remaining'), 2, 'count_positives([1, -2, 3])', '([1, -2, 3],)', NULL, NULL, 'returns', '2', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'early-break-skips-remaining'), 3, 'count_positives([-1, 2, 3])', '([-1, 2, 3],)', NULL, NULL, 'returns', '2', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'early-break-skips-remaining'), 1, 'Try a list with a negative number *in the middle*, with more positives after it.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'early-break-skips-remaining'), 2, '`break` stops the whole loop the first time it hits a non-positive number, even if positives still come later.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'early-break-skips-remaining'), 3, 'Remove the `else: break` - just skip non-positive numbers and keep going.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'early-break-skips-remaining'), 1, 6, 7, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'loop-termination'), '`break` exits the loop entirely as soon as one non-positive number is seen, ignoring any positives that come after it.', 'Remove the `break` - a non-positive number should just be skipped, not stop the count.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'early-break-skips-remaining'), (SELECT id FROM bh_concepts WHERE slug = 'loop-termination'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('percentage-inverted', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'Percentage Calculated Upside Down', 27, 2, NULL, 'logic', '`percent_correct(correct, total)` should return what percentage of `total` questions were `correct`.

Example: `percent_correct(50, 100)` should return `50.0`.', 'def percent_correct(correct, total):
    return total / correct * 100
', 'def percent_correct(correct, total):
    return correct / total * 100
', 'function', 'percent_correct', 'Division is not symmetric - `a / b` and `b / a` give very different answers unless `a` equals `b`. When a formula involves a ratio or percentage, double-check which value is meant to be on top.', 'For any "percentage" or "ratio" calculation, say the formula out loud in words first ("part over whole") and check the code matches.', NULL, 'published', '0bca1cc5427d12275b2277d11a8505f8ff92f3ba254e46cae63dd706d212758a', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'percentage-inverted'), 1, 'percent_correct(50, 100)', '(50, 100)', NULL, NULL, 'returns', '50', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'percentage-inverted'), 2, 'percent_correct(1, 4)', '(1, 4)', NULL, NULL, 'returns', '25', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'percentage-inverted'), 3, 'percent_correct(3, 3)', '(3, 3)', NULL, NULL, 'returns', '100', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'percentage-inverted'), 1, 'Try `percent_correct(1, 4)` - 1 out of 4 should be 25%. What does this actually give?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'percentage-inverted'), 2, 'A percentage is "part divided by whole", not "whole divided by part" - which variable is the part here, and which is the whole?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'percentage-inverted'), 3, 'Swap the division: `correct / total * 100`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'percentage-inverted'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'division-direction'), 'The division is the wrong way round - it computes `total / correct` instead of `correct / total`.', 'Swap the numerator and denominator.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'percentage-inverted'), (SELECT id FROM bh_concepts WHERE slug = 'division-direction'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('wrong-fallback-value', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'A Fallback That Matches the Wrong Case', 28, 2, NULL, 'logic', '`get_discount(level)` should return the % discount for `"gold"` (20), `"silver"` (10), and `0` for anything else.

Example: `get_discount("bronze")` should return `0`.', 'def get_discount(level):
    if level == "gold":
        return 20
    elif level == "silver":
        return 10
    return 10
', 'def get_discount(level):
    if level == "gold":
        return 20
    elif level == "silver":
        return 10
    return 0
', 'function', 'get_discount', 'A copy-pasted value left over from an earlier branch is easy to miss, because the code still runs perfectly - it just quietly returns the wrong fallback for every case that wasn''t explicitly handled.', 'Check every fallback/default `return` against the brief specifically - it''s the easiest one to leave wrong after copy-pasting a branch.', NULL, 'published', 'a8859972b63724a391e303231648f0327791766a7574014fa25c114bcee8907d', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-fallback-value'), 1, 'get_discount("gold")', '(''gold'',)', NULL, NULL, 'returns', '20', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-fallback-value'), 2, 'get_discount("silver")', '(''silver'',)', NULL, NULL, 'returns', '10', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-fallback-value'), 3, 'get_discount("bronze")', '(''bronze'',)', NULL, NULL, 'returns', '0', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-fallback-value'), 1, 'Try a level that is neither `"gold"` nor `"silver"` - what discount does it get?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-fallback-value'), 2, 'The final `return` is meant to be the fallback for everything else - check its value against the brief.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-fallback-value'), 3, 'Change the final `return 10` to `return 0`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-fallback-value'), 1, 6, 6, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'return-values'), 'The fallback `return 10` accidentally copies silver''s discount instead of using the "anything else" value of `0`.', 'Change the final `return` to `0`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-fallback-value'), (SELECT id FROM bh_concepts WHERE slug = 'return-values'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('miscounted-matches', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'A Condition That Is Always True', 29, 3, NULL, 'logic', '`count_vowels(word)` should return how many vowels (a, e, i, o, u) are in `word`.

Example: `count_vowels("hello")` should return `2`.', 'def count_vowels(word):
    count = 0
    for letter in word:
        if letter == "a" or "e" or "i" or "o" or "u":
            count += 1
    return count
', 'def count_vowels(word):
    count = 0
    for letter in word:
        if letter in "aeiou":
            count += 1
    return count
', 'function', 'count_vowels', 'Writing `x == a or b or c` does *not* mean "x equals a, b, or c" - each `or` joins a whole separate condition, and a plain non-empty string like `"e"` is always truthy on its own. `in` is the correct way to check membership against several options at once.', 'To check "is this one of several values", use `x in (a, b, c)` or `x in "abc"` - never chain `==` with bare `or`.', 'What do you think `count_vowels("sky")` returns? Write it down before you run anything.', 'published', '75baed15821e00d9003dd1b0d2d02b7bc835623fc9946dfe21508bc368d99d20', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'miscounted-matches'), 1, 'count_vowels("hello")', '(''hello'',)', NULL, NULL, 'returns', '2', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'miscounted-matches'), 2, 'count_vowels("sky")', '(''sky'',)', NULL, NULL, 'returns', '0', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'miscounted-matches'), 3, 'count_vowels("aeiou")', '(''aeiou'',)', NULL, NULL, 'returns', '5', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'miscounted-matches'), 1, 'Try a word with *no* vowels at all, like "sky" - what count comes back?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'miscounted-matches'), 2, '`letter == "a" or "e" or "i" or "o" or "u"` is not asking "is letter one of these?" - it is five separate things joined by `or`, and most of them are just non-empty strings, which Python treats as true on their own.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'miscounted-matches'), 3, 'Use `if letter in "aeiou":` to check membership properly.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'miscounted-matches'), 1, 4, 4, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'operator-precedence'), '`letter == "a" or "e" or "i" or "o" or "u"` is parsed as `(letter == "a") or ("e") or ("i") or ("o") or ("u")` - every string after the first is just a non-empty string, which Python treats as truthy regardless of `letter`, so the whole condition is always `True`.', 'Use `letter in "aeiou"` to properly check whether `letter` is one of the vowels.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'miscounted-matches'), (SELECT id FROM bh_concepts WHERE slug = 'operator-precedence'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('swapped-even-odd-condition', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'Summing the Wrong Parity', 30, 2, NULL, 'logic', '`sum_evens(numbers)` should return the sum of the even numbers in the list.

Example: `sum_evens([1, 2, 3, 4])` should return `6`.', 'def sum_evens(numbers):
    total = 0
    for n in numbers:
        if n % 2 == 1:
            total += n
    return total
', 'def sum_evens(numbers):
    total = 0
    for n in numbers:
        if n % 2 == 0:
            total += n
    return total
', 'function', 'sum_evens', 'A modulo check for "even" and "odd" differ by exactly one comparison value - `== 0` versus `== 1` - easy to swap, and the code runs without any error either way.', 'When filtering by even/odd, double check the function''s name actually matches which remainder it tests for.', NULL, 'published', '8c6b406f784eabc4ffb2f95246c23468986e3483c845174310ab74c6491f3101', NOW());
