INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('wrong-comparison-for-minimum', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'Cheapest, or Most Expensive?', 31, 2, NULL, 'logic', '`cheapest(prices)` should return the smallest price in the list.

Example: `cheapest([5, 2, 8])` should return `2`.', 'def cheapest(prices):
    best = prices[0]
    for p in prices:
        if p > best:
            best = p
    return best
', 'def cheapest(prices):
    best = prices[0]
    for p in prices:
        if p < best:
            best = p
    return best
', 'function', 'cheapest', 'Finding a minimum and finding a maximum use the exact same loop shape - the only difference is a single comparison operator. It is easy to copy a "find the maximum" pattern and forget to flip it.', 'When adapting a "find the maximum" pattern into a "find the minimum" one (or vice versa), double check the comparison operator was actually flipped.', NULL, 'published', '513814408fcfa6ae69260c53cc71188f2a2910642fb6d4ff8da0733a3b84057d', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-comparison-for-minimum'), 1, 'cheapest([5, 2, 8])', '([5, 2, 8],)', NULL, NULL, 'returns', '2', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-comparison-for-minimum'), 2, 'cheapest([10])', '([10],)', NULL, NULL, 'returns', '10', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-comparison-for-minimum'), 3, 'cheapest([3, 3, 1])', '([3, 3, 1],)', NULL, NULL, 'returns', '1', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-comparison-for-minimum'), 1, 'The function is called "cheapest" - check the result is actually the smallest value, not the largest.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-comparison-for-minimum'), 2, '`if p > best: best = p` keeps the biggest value it has seen, which finds a maximum, not a minimum.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-comparison-for-minimum'), 3, 'Change `>` to `<`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-comparison-for-minimum'), 1, 4, 4, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'accumulators'), 'Keeping the value whenever `p > best` tracks the *largest* value seen, which finds a maximum - "cheapest" needs a minimum.', 'Change `>` to `<` so it keeps the smallest value instead.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-comparison-for-minimum'), (SELECT id FROM bh_concepts WHERE slug = 'accumulators'));

