Example: `is_valid_password("abc12345")` should return `True`.', 'def is_valid_password(password):
    return len(password) >= 8 or password.isalnum()
', 'def is_valid_password(password):
    return len(password) >= 8 and password.isalnum()
', 'function', 'is_valid_password', '`and` requires every condition to be true; `or` only needs one. "Both of these rules must hold" always means `and`, never `or` - a very easy pair to mix up since both read naturally in English.', 'Read requirements literally: "must be X and Y" needs `and`; "must be X or Y" needs `or` - they are not interchangeable.', NULL, 'published', 'd330490fa708be46fa183b204e45391b27d3e0d1f31717f06bce7c311dfca6eb', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-and-or-condition'), 1, 'is_valid_password("abc12345")', '(''abc12345'',)', NULL, NULL, 'returns', 'True', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-and-or-condition'), 2, 'is_valid_password("abc")', '(''abc'',)', NULL, NULL, 'returns', 'False', 'exact', 0);
