INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('wrong-and-or-condition-reversed', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'and Where or Was Needed', 33, 2, NULL, 'logic', '`can_ride(height_cm, has_adult)` should return `True` if the rider is tall enough (120cm or more), *or* accompanied by an adult.

Example: `can_ride(150, False)` should return `True`.', 'def can_ride(height_cm, has_adult):
    return height_cm >= 120 and has_adult
', 'def can_ride(height_cm, has_adult):
    return height_cm >= 120 or has_adult
', 'function', 'can_ride', 'This is the mirror image of mixing up `and` for `or` - here, a rule that should accept "either condition" was written to require "both". The English words "or" and "and" in the brief are exact instructions, not interchangeable phrasing.', 'When a brief says "either" or uses "or", check the code doesn''t quietly require both with `and`.', NULL, 'published', 'fc7706f19b47249636bc76b9d0d2e7516d44eecdeb18f28327e656e2eb13cb09', NOW());
