INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('average-of-wrong-count', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'Dividing by a Fixed Number', 38, 2, NULL, 'logic', '`class_average(scores)` should return the mean of the scores in the list.

Example: `class_average([50, 60, 70])` should return `60.0`.', 'def class_average(scores):
    total = sum(scores)
    return total / 100
', 'def class_average(scores):
    total = sum(scores)
    return total / len(scores)
', 'function', 'class_average', 'A mean is always "total divided by count" - using a fixed number instead of the real count only works by coincidence, for exactly one specific input size.', 'If a calculation divides by a literal number rather than something measured from the actual data (like `len(...)`), check whether that number can really be assumed fixed.', NULL, 'published', '6e6ff7f425b458798bf8cded98d43d6446b7c124867e59b9f1e1497bf528b1af', NOW());
