INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'average-of-wrong-count'), 2, 'class_average([100])', '([100],)', NULL, NULL, 'returns', '100', 'exact', 0);
