INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('swapped-win-loss-condition', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'Win and Loss Swapped', 39, 2, NULL, 'logic', '`game_result(my_score, their_score)` should return `"Win"` if `my_score` is higher, `"Loss"` if lower, and `"Draw"` if equal.

Example: `game_result(10, 5)` should return `"Win"`.', 'def game_result(my_score, their_score):
    if my_score < their_score:
        return "Win"
    elif my_score > their_score:
        return "Loss"
    else:
        return "Draw"
', 'def game_result(my_score, their_score):
    if my_score > their_score:
        return "Win"
    elif my_score < their_score:
        return "Loss"
    else:
        return "Draw"
', 'function', 'game_result', 'Comparisons and their labels have to agree - "Win" should mean *your* score is higher, not lower. Both branches here run without error; they are just confidently backwards.', 'For any "win/loss" or "higher/lower" style branch, check the comparison direction matches the label exactly, not just that there is one branch per outcome.', NULL, 'published', '271cfff48d2210549e3f78e4569190ea0add6f1285a0c01d278a4cf88926d886', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'swapped-win-loss-condition'), 1, 'game_result(10, 5)', '(10, 5)', NULL, NULL, 'returns', '"Win"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'swapped-win-loss-condition'), 2, 'game_result(3, 8)', '(3, 8)', NULL, NULL, 'returns', '"Loss"', 'exact', 0);
