INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('wrong-increment-amount', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'Minutes as a Fraction', 40, 2, NULL, 'logic', '`seconds_to_minutes(seconds)` should return how many whole minutes have elapsed.

Example: `seconds_to_minutes(125)` should return `2`.', 'def seconds_to_minutes(seconds):
    return seconds / 60
', 'def seconds_to_minutes(seconds):
    return seconds // 60
', 'function', 'seconds_to_minutes', '`/` always gives a float result, carrying any remainder as a fraction. `//` discards the remainder and gives a whole number - exactly what "whole minutes elapsed" means.', 'If a brief says "whole" anything, check for `//` rather than `/`.', NULL, 'published', 'd5f8073e9513a71a52ecd1e4d184cb689579560ec5b46992ba5208e4586970e0', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-increment-amount'), 1, 'seconds_to_minutes(125)', '(125,)', NULL, NULL, 'returns', '2', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-increment-amount'), 2, 'seconds_to_minutes(59)', '(59,)', NULL, NULL, 'returns', '0', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-increment-amount'), 3, 'seconds_to_minutes(180)', '(180,)', NULL, NULL, 'returns', '3', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-increment-amount'), 1, 'Check the type and exact value of the result - is it a whole number of minutes?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-increment-amount'), 2, '`/` gives an exact (possibly fractional) result; "whole minutes" wants the result rounded down to a whole number.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-increment-amount'), 3, 'Use `//` (integer/floor division) instead of `/`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-increment-amount'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'integer-vs-float-division'), '`/` gives the exact, possibly-fractional result (e.g. `2.0833...`) - the brief wants only whole minutes.', 'Use `//` for integer (floor) division.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-increment-amount'), (SELECT id FROM bh_concepts WHERE slug = 'integer-vs-float-division'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('plural-variable-mixup', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'The Current Item vs the Whole List', 41, 3, NULL, 'logic', '`longest_word(words)` should return the longest word in the list (the first one, if there is a tie).

Example: `longest_word(["cat", "elephant", "dog"])` should return `"elephant"`.', 'def longest_word(words):
    longest = ""
    for w in words:
        if len(w) > len(longest):
            longest = words
    return longest
', 'def longest_word(words):
    longest = ""
    for w in words:
        if len(w) > len(longest):
            longest = w
    return longest
', 'function', 'longest_word', 'Python can''t warn you when a name that happens to exist (like the function''s own parameter) is used by mistake instead of the loop variable - both are valid names, just not the one you meant.', 'When a loop variable and an outer variable have very similar names (singular/plural is a classic case), check every use of them carefully - a typo-like slip between them won''t raise any error.', 'What do you think `longest_word(["cat", "elephant", "dog"])` returns? Write it down before you run anything.', 'published', '89d71e9af99305b2664db22f0efa0462c6f94325e6147b1d3cc121e6a0c64d06', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'plural-variable-mixup'), 1, 'longest_word(["cat", "elephant", "dog"])', '([''cat'', ''elephant'', ''dog''],)', NULL, NULL, 'returns', '"elephant"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'plural-variable-mixup'), 2, 'longest_word(["a", "bb"])', '([''a'', ''bb''],)', NULL, NULL, 'returns', '"bb"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'plural-variable-mixup'), 3, 'longest_word(["same", "size"])', '([''same'', ''size''],)', NULL, NULL, 'returns', '"same"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'plural-variable-mixup'), 1, 'Look very closely at the assignment inside the loop - which name does it actually store?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'plural-variable-mixup'), 2, 'There are two very similarly-named things in scope here: the current word, and the entire list of words.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'plural-variable-mixup'), 3, 'Change `longest = words` to `longest = w` (the loop variable, not the whole list).');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'plural-variable-mixup'), 1, 5, 5, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'names-and-scope'), '`longest = words` stores the *entire list* (plural) instead of `w`, the current word (singular) - a one-letter difference in the name with a completely different meaning.', 'Change `words` to `w` on that line.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'plural-variable-mixup'), (SELECT id FROM bh_concepts WHERE slug = 'names-and-scope'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('wrong-order-of-operations', (SELECT id FROM bh_tracks WHERE slug = 'wrong-answer'), 'An Average Without Brackets', 42, 2, NULL, 'logic', '`average_of_two(a, b)` should return the average of `a` and `b`.

Example: `average_of_two(4, 6)` should return `5.0`.', 'def average_of_two(a, b):
    return a + b / 2
', 'def average_of_two(a, b):
    return (a + b) / 2
', 'function', 'average_of_two', 'Python follows the standard order of operations: multiplication and division happen before addition and subtraction, regardless of the order you wrote them in. Any formula that needs addition done *first* must say so with brackets.', 'Whenever a formula mixes `+`/`-` with `*`/`/`, check whether brackets are needed to force the order you actually want.', NULL, 'published', '3bb114c16dd77a55312734255a860aec9de75637915f85ab94d6ec31242cfc54', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-order-of-operations'), 1, 'average_of_two(4, 6)', '(4, 6)', NULL, NULL, 'returns', '5', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-order-of-operations'), 2, 'average_of_two(10, 0)', '(10, 0)', NULL, NULL, 'returns', '5', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-order-of-operations'), 3, 'average_of_two(3, 3)', '(3, 3)', NULL, NULL, 'returns', '3', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-order-of-operations'), 1, 'Work out `average_of_two(10, 0)` by hand, then compare it to what the code actually gives.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-order-of-operations'), 2, 'Python does division before addition unless you tell it otherwise - that is not the order "average" needs.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-order-of-operations'), 3, 'Wrap the addition in brackets: `(a + b) / 2`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-order-of-operations'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'operator-precedence'), 'Without brackets, `/` happens before `+` - this computes `a + (b / 2)`, not `(a + b) / 2`.', 'Add brackets around `a + b`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'wrong-order-of-operations'), (SELECT id FROM bh_concepts WHERE slug = 'operator-precedence'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('infinite-descent', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Infinite Descent', 1, 3, NULL, 'runtime', '`factorial(n)` should return `n!` (n factorial): `n * (n-1) * (n-2) * ... * 1`.

Example: `factorial(5)` should return `120`. By definition, `factorial(0)` and `factorial(1)` both return `1`.', 'def factorial(n):
    return n * factorial(n - 1)
', 'def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)
', 'function', 'factorial', 'Recursive functions need two things: a base case that returns without recursing, and a recursive case that''s guaranteed to move closer to that base case. This function only has the recursive case, so it never stops - it just keeps calling itself with smaller and smaller numbers until Python gives up.', 'Whenever you write a recursive function, write the base case first and check the recursive call actually moves towards it.', 'What do you think happens when you run `factorial(5)`? Will it finish? Write down what you expect before you run it.', 'published', '8cda8441bd441b79d4348d243b274fe7f2358ded3914d0f00021ccb64686a5ad', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'infinite-descent'), 1, 'factorial(5)', '(5,)', NULL, NULL, 'returns', '120', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'infinite-descent'), 2, 'factorial(3)', '(3,)', NULL, NULL, 'returns', '6', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'infinite-descent'), 3, 'factorial(1)', '(1,)', NULL, NULL, 'returns', '1', 'exact', 1);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'infinite-descent'), 4, 'factorial(0)', '(0,)', NULL, NULL, 'returns', '1', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'infinite-descent'), 1, 'This one crashes with a `RecursionError` - the function keeps calling itself and never stops.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'infinite-descent'), 2, 'Every recursive function needs a condition where it stops calling itself. Does this one have one?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'infinite-descent'), 3, 'Add a base case: if `n <= 1`, return `1` directly, before the recursive call.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'infinite-descent'), 1, 1, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'recursion'), 'There''s no base case, so `factorial` keeps calling itself with a smaller `n` forever, until Python''s recursion limit is hit.', 'Add `if n <= 1: return 1` before the recursive call.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'infinite-descent'), (SELECT id FROM bh_concepts WHERE slug = 'recursion'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('shared-default', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Shared Default', 2, 3, NULL, 'logic', 'Each call to `add_item` should start from a fresh, empty basket unless one is given.

Expected output:
```
[''apple'']
[''banana'']
```', 'def add_item(item, basket=[]):
    basket.append(item)
    return basket

print(add_item("apple"))
print(add_item("banana"))
', 'def add_item(item, basket=None):
    if basket is None:
        basket = []
    basket.append(item)
    return basket

print(add_item("apple"))
print(add_item("banana"))
', 'script', NULL, 'A default argument value is evaluated exactly once, when `def` runs - not fresh on every call. For an immutable default like a number or string this never matters, but a mutable default like a list or dict gets shared and silently mutated across every call that relies on it.', 'Never use a mutable value (`[]`, `{}`, a class instance) as a default argument - use `None` and create the real default inside the function body instead.', 'Each call leaves out the `basket` argument. What do you expect the two printed lines to look like?', 'published', '2d78064811ca3aa88e97a29acd15016cb3925e5f55dce354e16f48535ea5d6b5', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shared-default'), 1, 'two separate calls stay separate', NULL, NULL, '', 'stdout', '"[''apple'']\\n[''banana'']\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shared-default'), 2, 'two separate calls stay separate (repeat check)', NULL, NULL, '', 'stdout', '"[''apple'']\\n[''banana'']\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shared-default'), 1, 'This runs without errors, but the second line printed isn''t what you''d expect from "start fresh each time".');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shared-default'), 2, 'A default argument value is created only once, when the function is defined - not fresh on every call. What kind of default value could that cause problems for?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shared-default'), 3, 'Use `basket=None` as the default, then create a new empty list inside the function if `basket is None`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shared-default'), 1, 1, 1, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'mutable-defaults'), 'The default list `[]` is created once when the function is defined, and reused across every call that doesn''t supply its own basket - so items pile up across calls instead of starting fresh.', 'Default to `None`, and create a new list inside the function when no basket is given.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shared-default'), (SELECT id FROM bh_concepts WHERE slug = 'mutable-defaults'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('same-list-two-names', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Same List, Two Names', 3, 3, NULL, 'logic', 'Doubling a copy of a list should leave the original list unchanged.

Expected output:
```
[1, 2, 3]
[2, 4, 6]
```', 'original = [1, 2, 3]
doubled = original
for i in range(len(doubled)):
    doubled[i] = doubled[i] * 2
print(original)
print(doubled)
', 'original = [1, 2, 3]
doubled = original.copy()
for i in range(len(doubled)):
    doubled[i] = doubled[i] * 2
print(original)
print(doubled)
', 'script', NULL, 'Assigning a list to a new name doesn''t copy it - both names point at the exact same object in memory. Changing the contents through either name changes what both names see, which is surprising if you expected an independent copy.', 'If you need a genuinely separate list, use `.copy()`, `list(...)`, or a slice `[:]` - plain `=` never copies a list.', 'After `doubled = original`, are `original` and `doubled` separate lists, or two names for the same one? What do you expect printed?', 'published', '631841c23f9f6f2b0691361d6b266d14f96284af7059a436f2e28c82118db40d', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'same-list-two-names'), 1, 'original stays untouched', NULL, NULL, '', 'stdout', '"[1, 2, 3]\\n[2, 4, 6]\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'same-list-two-names'), 2, 'original stays untouched (repeat check)', NULL, NULL, '', 'stdout', '"[1, 2, 3]\\n[2, 4, 6]\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'same-list-two-names'), 1, 'This runs fine, but check both printed lines - is the first one what you expected?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'same-list-two-names'), 2, '`doubled = original` doesn''t make a new list - it makes `doubled` another name for the exact same list.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'same-list-two-names'), 3, 'Use `original.copy()` (or `list(original)`) to make a genuinely separate list.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'same-list-two-names'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'aliasing-and-copying'), '`doubled = original` makes `doubled` point at the same list object as `original`, so changing one through its index changes both.', 'Use `original.copy()` to create an independent list.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'same-list-two-names'), (SELECT id FROM bh_concepts WHERE slug = 'aliasing-and-copying'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('grid-surprise', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Grid Surprise', 4, 4, NULL, 'logic', 'Changing one cell of a grid should only affect that one cell.

Expected output:
```
[[1, 0, 0], [0, 0, 0], [0, 0, 0]]
```', 'grid = [[0] * 3] * 3
grid[0][0] = 1
print(grid)
', 'grid = [[0] * 3 for _ in range(3)]
grid[0][0] = 1
print(grid)
', 'script', NULL, 'Multiplying a list with `*` repeats references to the same object, not independent copies - this is harmless for immutable items like numbers, but for a list-of-lists, every "row" ends up being the exact same row, aliased three times over.', 'Never build a 2D grid with `[[...] * n] * m` - use a comprehension so each row is created fresh.', 'After `grid[0][0] = 1`, how many of the 9 cells do you expect to show `1`?', 'published', 'aad26edd514fa5f1814e44f59b8e304ebb026f46c2a966151563eef29a6686fc', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grid-surprise'), 1, 'only one cell changes', NULL, NULL, '', 'stdout', '"[[1, 0, 0], [0, 0, 0], [0, 0, 0]]\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grid-surprise'), 2, 'only one cell changes (repeat check)', NULL, NULL, '', 'stdout', '"[[1, 0, 0], [0, 0, 0], [0, 0, 0]]\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grid-surprise'), 1, 'Only one cell was changed in the code - but look at how many `1`s show up in the output.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grid-surprise'), 2, '`[[0] * 3] * 3` repeats the *same inner list* three times, not three independent lists.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grid-surprise'), 3, 'Use a list comprehension - `[[0] * 3 for _ in range(3)]` - to create three genuinely separate rows.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grid-surprise'), 1, 1, 1, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'aliasing-and-copying'), '`[[0] * 3] * 3` makes a list containing the *same* inner list object three times, so changing one row through an index changes every row.', 'Build the rows with a list comprehension so each one is a separate list.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'grid-surprise'), (SELECT id FROM bh_concepts WHERE slug = 'aliasing-and-copying'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('the-search-that-hangs', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'The Search That Hangs', 5, 4, NULL, 'logic', '`binary_search(items, target)` should return the index of `target` in the sorted list `items`, or `-1` if it isn''t there.

Example: `binary_search([1, 3, 5, 7, 9], 7)` should return `3`.', 'def binary_search(items, target):
    low, high = 0, len(items)
    while low < high:
        mid = (low + high) // 2
        if items[mid] == target:
            return mid
        elif items[mid] < target:
            low = mid
        else:
            high = mid
    return -1
', 'def binary_search(items, target):
    low, high = 0, len(items) - 1
    while low <= high:
        mid = (low + high) // 2
        if items[mid] == target:
            return mid
        elif items[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1
', 'function', 'binary_search', 'Binary search relies on the search range shrinking every single pass. If a new bound is set to `mid` itself rather than one step past it, the range can stop shrinking entirely when the target isn''t in the list - looping forever instead of giving up.', 'For any loop meant to narrow down a range, check by hand that the range can''t get stuck at the same size pass after pass.', NULL, 'published', '9e3b4c7e6fad8345fca5c1ba78b0077225e6bfd6ce8c7cb151086b2c0ff07260', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'the-search-that-hangs'), 1, 'binary_search([1, 3, 5, 7, 9], 7)', '([1, 3, 5, 7, 9], 7)', NULL, NULL, 'returns', '3', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'the-search-that-hangs'), 2, 'binary_search([1, 3, 5, 7, 9], 1)', '([1, 3, 5, 7, 9], 1)', NULL, NULL, 'returns', '0', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'the-search-that-hangs'), 3, 'binary_search([1, 2], 5)', '([1, 2], 5)', NULL, NULL, 'returns', '-1', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'the-search-that-hangs'), 1, 'At least one test gets stopped for taking too long - the search bounds aren''t narrowing down the way they should.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'the-search-that-hangs'), 2, 'When the target is smaller or larger than the middle item, how much does `low` or `high` actually move? Could `mid` ever equal `low` or `high` again on the next pass?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'the-search-that-hangs'), 3, 'Narrow the bounds past `mid`, not onto it: use `low = mid + 1` and `high = mid - 1`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'the-search-that-hangs'), 1, 7, 9, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'binary-search'), 'Setting `low = mid` or `high = mid` (instead of `mid + 1` / `mid - 1`) can leave the search bounds unchanged between passes, looping forever when the target isn''t present.', 'Move the bounds past `mid`: `low = mid + 1` and `high = mid - 1`, and start `high` at `len(items) - 1`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'the-search-that-hangs'), (SELECT id FROM bh_concepts WHERE slug = 'binary-search'));
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'the-search-that-hangs'), (SELECT id FROM bh_concepts WHERE slug = 'off-by-one'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('late-binding', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Late Binding', 6, 4, NULL, 'logic', 'Each function made in the loop should remember its *own* value of `i` at the time it was created.

Expected output:
```
[0, 1, 2]
```', 'makers = []
for i in range(3):
    makers.append(lambda: i)
print([m() for m in makers])
', 'makers = []
for i in range(3):
    makers.append(lambda i=i: i)
print([m() for m in makers])
', 'script', NULL, 'A closure remembers the *variable*, not the value it held at creation time. Since all three lambdas share the same loop variable `i`, and the loop has finished by the time any of them are called, they all see `i`''s final value. A default argument is evaluated once, at creation, which is how to capture the value instead.', 'If you create functions inside a loop that need to remember the loop variable''s value, capture it with a default argument: `lambda x=x: ...`.', 'Three lambdas are created, one per loop iteration. What do you expect calling all three, in order, to give?', 'published', '8416e56bc0e9651ca3521b3316d160fe0da0047e19b26c18758e39d4fbbf9561', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'late-binding'), 1, 'each lambda remembers its own i', NULL, NULL, '', 'stdout', '"[0, 1, 2]\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'late-binding'), 2, 'each lambda remembers its own i (repeat check)', NULL, NULL, '', 'stdout', '"[0, 1, 2]\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'late-binding'), 1, 'All three results come out the same - but they were created with three different values of `i`.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'late-binding'), 2, 'A lambda looks up `i` in its enclosing scope *when it''s called*, not when it''s created - and there''s only one `i` variable, shared by the whole loop.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'late-binding'), 3, 'Give the lambda its own parameter with a default: `lambda i=i: i`, capturing the current value at creation time.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'late-binding'), 1, 3, 3, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'closures'), 'The lambda doesn''t capture `i`''s value at creation time - it looks `i` up when called, by which point the loop has finished and `i` holds its final value for every lambda.', 'Use a default argument to capture the current value: `lambda i=i: i`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'late-binding'), (SELECT id FROM bh_concepts WHERE slug = 'closures'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('global-mistake', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Global Mistake', 7, 3, NULL, 'logic', '`record_score` should remember the highest score seen so far, across separate calls.

Expected output:
```
50
50
80
```', 'high_score = 0

def record_score(points):
    local_high = high_score
    if points > local_high:
        local_high = points
    return local_high

print(record_score(50))
print(record_score(30))
print(record_score(80))
', 'high_score = 0

def record_score(points):
    global high_score
    if points > high_score:
        high_score = points
    return high_score

print(record_score(50))
print(record_score(30))
print(record_score(80))
', 'script', NULL, 'Reading a global variable into a local one copies its current value - it doesn''t create a live link back to the original. Without `global`, any "updates" only change the local copy, which disappears when the function returns, leaving the real global untouched.', 'If a function needs to remember something between separate calls, it has to update a genuine global (with `global`) - a local copy resets every time.', 'Three scores are recorded in a row: 50, then 30, then 80. What do you expect printed each time?', 'published', 'caedc6ab358244af587b488d96946b0c5924de6e695916b41f6c24df03f054bf', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'global-mistake'), 1, 'high score persists across calls', NULL, NULL, '', 'stdout', '"50\\n50\\n80\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'global-mistake'), 2, 'high score persists across calls (repeat check)', NULL, NULL, '', 'stdout', '"50\\n50\\n80\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'global-mistake'), 1, 'The second line printed is lower than the first - but a *high* score should never go down.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'global-mistake'), 2, '`local_high` is a brand new local variable every call - does it actually update `high_score` for next time?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'global-mistake'), 3, 'Declare `global high_score` inside the function, and update `high_score` directly instead of a local copy.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'global-mistake'), 1, 4, 4, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'names-and-scope'), '`local_high` copies `high_score`''s value but never writes back to it, so the module-level `high_score` stays `0` forever and each call compares against that, not the real running high score.', 'Add `global high_score` and update `high_score` itself.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'global-mistake'), (SELECT id FROM bh_concepts WHERE slug = 'names-and-scope'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('used-up', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Used Up', 8, 4, NULL, 'logic', 'Listing the same filtered results twice should give the same answer both times.

Expected output:
```
[2, 4, 6]
[2, 4, 6]
```', 'def even_numbers(nums):
    return (n for n in nums if n % 2 == 0)

evens = even_numbers([1, 2, 3, 4, 5, 6])
print(list(evens))
print(list(evens))
', 'def even_numbers(nums):
    return [n for n in nums if n % 2 == 0]

evens = even_numbers([1, 2, 3, 4, 5, 6])
print(list(evens))
print(list(evens))
', 'script', NULL, 'Generators produce values lazily, one at a time, and don''t remember them afterwards - once consumed, they''re exhausted for good. A list holds all its values at once and can be read repeatedly, which is what''s needed here.', 'If something needs to be iterated over more than once, make sure it''s a list (or another reusable collection), not a one-shot generator.', '`list(evens)` is called twice on the same `evens`. What do you expect the second call to print?', 'published', 'e8c742acbb814da1a7833b8aa47913a2843a673df9c755f070d22d272c76c55d', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'used-up'), 1, 'listing twice gives the same result both times', NULL, NULL, '', 'stdout', '"[2, 4, 6]\\n[2, 4, 6]\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'used-up'), 2, 'listing twice gives the same result both times (repeat check)', NULL, NULL, '', 'stdout', '"[2, 4, 6]\\n[2, 4, 6]\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'used-up'), 1, 'The second printed line is empty - but nothing was removed from `evens` on purpose.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'used-up'), 2, 'A generator expression `(... for ...)` only produces its values once, in one pass. What happens once every value has been read?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'used-up'), 3, 'Return a list comprehension `[...]` instead of a generator expression `(...)`, so it can be listed more than once.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'used-up'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'iterators-and-generators'), 'A generator can only be stepped through once - the first `list(evens)` consumes every value, so the second one has nothing left to give.', 'Use a list comprehension `[n for n in nums if ...]` instead, which can be read as many times as needed.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'used-up'), (SELECT id FROM bh_concepts WHERE slug = 'iterators-and-generators'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('nearly-equal', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Nearly Equal', 9, 3, NULL, 'logic', '`adds_to_one(a, b, c)` should return `True` if the three numbers add up to (very close to) `1`.

Example: `adds_to_one(0.7, 0.2, 0.1)` should return `True`.', 'def adds_to_one(a, b, c):
    return a + b + c == 1.0
', 'import math

def adds_to_one(a, b, c):
    return math.isclose(a + b + c, 1.0)
', 'function', 'adds_to_one', 'Computers store `float` numbers in binary, and most decimal fractions (like 0.1) can''t be represented exactly in binary any more than 1/3 can be written exactly in decimal. The tiny rounding errors this creates mean exact equality (`==`) between floats is almost never the right check.', 'Never compare floats with `==` - use `math.isclose()` (or check the difference is smaller than a small tolerance) instead.', 'Do you expect `0.7 + 0.2 + 0.1` to be exactly equal to `1.0` in Python? Write down yes or no before running it.', 'published', '5bf2aab5c63b64dd7dd5e392024da80beda327a09b2f31a9996692ba4352993d', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nearly-equal'), 1, 'adds_to_one(0.7, 0.2, 0.1)', '(0.7, 0.2, 0.1)', NULL, NULL, 'returns', 'True', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nearly-equal'), 2, 'adds_to_one(0.6, 0.3, 0.1)', '(0.6, 0.3, 0.1)', NULL, NULL, 'returns', 'True', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nearly-equal'), 3, 'adds_to_one(1, 1, 1)', '(1, 1, 1)', NULL, NULL, 'returns', 'False', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nearly-equal'), 1, 'The first test fails even though `0.7 + 0.2 + 0.1` really does equal 1 on paper.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nearly-equal'), 2, 'Computers store decimal fractions like `0.1` approximately, in binary - try printing `0.7 + 0.2 + 0.1` directly and look closely at the result.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nearly-equal'), 3, 'Use `math.isclose(a + b + c, 1.0)` instead of `==`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nearly-equal'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'floating-point'), 'Floating-point numbers can''t represent most decimal fractions exactly, so `0.1 + 0.2 + 0.7` comes out as something like `0.9999999999999999`, not exactly `1.0`.', 'Use `math.isclose(...)` to compare with a small tolerance instead of `==`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nearly-equal'), (SELECT id FROM bh_concepts WHERE slug = 'floating-point'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('changing-while-iterating-dict', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Changing While Iterating', 10, 4, NULL, 'runtime', '`remove_zero_stock(stock)` should remove any item from the `stock` dictionary whose count is `0`, and return the dictionary.

Example: `remove_zero_stock({"pens": 0, "pencils": 5})` should return `{"pencils": 5}`.', 'def remove_zero_stock(stock):
    for item in stock:
        if stock[item] == 0:
            del stock[item]
    return stock
', 'def remove_zero_stock(stock):
    for item in list(stock.keys()):
        if stock[item] == 0:
            del stock[item]
    return stock
', 'function', 'remove_zero_stock', 'Unlike lists, Python actively detects a dictionary changing size while you iterate over it and raises an error rather than risk silently skipping or revisiting items. Looping over a separate list of the keys (taken before the loop starts) sidesteps the problem entirely.', 'Never add or remove keys from a dict while iterating directly over it - loop over `list(d.keys())` if you need to modify it as you go.', NULL, 'published', '04c77145e6f7f84cffd032f231c7fa1210cb37107ddf2a37d89d28b57a5f852c', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'changing-while-iterating-dict'), 1, 'remove_zero_stock({"pens": 0, "pencils": 5})', '({''pens'': 0, ''pencils'': 5},)', NULL, NULL, 'returns', '{"pencils": 5}', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'changing-while-iterating-dict'), 2, 'remove_zero_stock({"a": 1, "b": 2})', '({''a'': 1, ''b'': 2},)', NULL, NULL, 'returns', '{"a": 1, "b": 2}', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'changing-while-iterating-dict'), 3, 'remove_zero_stock({"a": 0, "b": 0})', '({''a'': 0, ''b'': 0},)', NULL, NULL, 'returns', '{}', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'changing-while-iterating-dict'), 1, 'This crashes with a `RuntimeError` about the dictionary changing size.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'changing-while-iterating-dict'), 2, 'Python won''t let you add or remove keys from a dictionary while you''re directly looping over it. Can you loop over something else instead - a snapshot of the keys, perhaps?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'changing-while-iterating-dict'), 3, 'Loop over `list(stock.keys())` instead of `stock` directly.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'changing-while-iterating-dict'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'mutating-while-iterating'), 'Python detects that the dictionary''s size changed mid-loop (from `del`) and refuses to continue, since it can no longer guarantee which items have been visited.', 'Loop over a snapshot of the keys instead: `for item in list(stock.keys()):`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'changing-while-iterating-dict'), (SELECT id FROM bh_concepts WHERE slug = 'mutating-while-iterating'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('sorted-wrong', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Sorted Wrong', 11, 3, NULL, 'logic', '`top_scorers(players)` takes a list of `(name, score)` tuples and should return the names of the 3 highest scorers, highest first.

Example: `top_scorers([("Al", 10), ("Bo", 30), ("Cy", 20), ("Di", 5)])` should return `["Bo", "Cy", "Al"]`.', 'def top_scorers(players):
    ranked = sorted(players, key=lambda p: p[1])
    return [name for name, score in ranked[:3]]
', 'def top_scorers(players):
    ranked = sorted(players, key=lambda p: p[1], reverse=True)
    return [name for name, score in ranked[:3]]
', 'function', 'top_scorers', '`sorted()` always sorts ascending (smallest first) unless told otherwise. Taking a slice from the front after sorting ascending gives you the smallest items, which is the opposite of "top" unless `reverse=True` is added.', 'After any `sorted()` call, check whether you want ascending or descending order, and whether `reverse=True` matches that.', NULL, 'published', 'c96c3ebe0c88c28ce451189a6fbfdffbba9aa1b40715d4cd28b068d39952fa2c', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sorted-wrong'), 1, 'top_scorers([("Al", 10), ("Bo", 30), ("Cy", 20), ("Di", 5)])', '([(''Al'', 10), (''Bo'', 30), (''Cy'', 20), (''Di'', 5)],)', NULL, NULL, 'returns', '["Bo", "Cy", "Al"]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sorted-wrong'), 2, 'top_scorers([("X", 1), ("Y", 2), ("Z", 3)])', '([(''X'', 1), (''Y'', 2), (''Z'', 3)],)', NULL, NULL, 'returns', '["Z", "Y", "X"]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sorted-wrong'), 3, 'top_scorers([("P", 100), ("Q", 50), ("R", 75), ("S", 10)])', '([(''P'', 100), (''Q'', 50), (''R'', 75), (''S'', 10)],)', NULL, NULL, 'returns', '["P", "R", "Q"]', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sorted-wrong'), 1, 'This returns the 3 *lowest* scorers instead of the 3 highest.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sorted-wrong'), 2, '`sorted()` arranges things smallest-to-largest by default. Does taking the first 3 of that give you the top, or the bottom?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sorted-wrong'), 3, 'Add `reverse=True` to `sorted(...)` so it goes largest-to-smallest.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sorted-wrong'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'sorting'), '`sorted()` defaults to ascending order, so taking the first 3 items gives the lowest scorers, not the highest.', 'Add `reverse=True`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sorted-wrong'), (SELECT id FROM bh_concepts WHERE slug = 'sorting'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('silent-failure', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Silent Failure', 12, 4, NULL, 'logic', '`safe_divide(a, b)` should return `a` divided by `b`.

Example: `safe_divide(10, 2)` should return `5.0`.', 'def safe_divide(a, b):
    try:
        resutl = a / b
        return result
    except:
        return None
', 'def safe_divide(a, b):
    return a / b
', 'function', 'safe_divide', 'A bare `except:` catches every exception, including the ones you never intended to - like a plain typo. That turns a loud, obvious crash (which would have pointed straight at the mistake) into a silent wrong answer, which is much harder to track down.', 'Avoid bare `except:` - catch only the specific exception types you actually expect, so unexpected bugs stay loud instead of disappearing silently.', NULL, 'published', '3e202917d57036990d54c2b47c830e925075870015958591cb58b42f6c108c6b', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'silent-failure'), 1, 'safe_divide(10, 2)', '(10, 2)', NULL, NULL, 'returns', '5', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'silent-failure'), 2, 'safe_divide(9, 3)', '(9, 3)', NULL, NULL, 'returns', '3', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'silent-failure'), 3, 'safe_divide(7, 2)', '(7, 2)', NULL, NULL, 'returns', '3.5', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'silent-failure'), 1, 'This never crashes, but it also never seems to return the right answer - it just gives back `None` every time.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'silent-failure'), 2, 'A bare `except:` catches *every* kind of error, including ones caused by ordinary typos elsewhere in the same `try` block. Is there a typo hiding in there?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'silent-failure'), 3, 'There''s a spelling mistake (`resutl` vs `result`) causing a `NameError` that the bare `except` is silently swallowing. Fix the typo, and prefer not catching errors you don''t expect.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'silent-failure'), 1, 3, 6, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'exception-handling'), 'A typo (`resutl` instead of `result`) causes a `NameError` every single call, but the bare `except:` catches it silently and returns `None`, hiding the real bug completely.', 'Fix the typo, and avoid bare `except:` clauses that can hide genuine bugs like this one.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'silent-failure'), (SELECT id FROM bh_concepts WHERE slug = 'exception-handling'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('equal-or-identical', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Equal or Identical', 13, 3, NULL, 'logic', '`same_contents(a, b)` should return `True` if two lists contain the same items in the same order, even if they are different list objects.

Example: `same_contents([1, 2, 3], [1, 2, 3])` should return `True`.', 'def same_contents(a, b):
    return a is b
', 'def same_contents(a, b):
    return a == b
', 'function', 'same_contents', '`==` asks "do these have the same value?"; `is` asks "are these the exact same object in memory?" Two separately built lists can hold identical values while being two completely different objects - which is the normal, expected case, not an edge case.', 'Use `==` to compare values (almost always what you want); reserve `is` for checking against `None` or confirming two names refer to the literal same object.', NULL, 'published', '9468ff7d79f67edee7cc7b2bd450032cbe01e9f8c5350295f115bf9cf18aae12', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'equal-or-identical'), 1, 'same_contents([1, 2, 3], [1, 2, 3])', '([1, 2, 3], [1, 2, 3])', NULL, NULL, 'returns', 'True', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'equal-or-identical'), 2, 'same_contents([1, 2], [1, 2])', '([1, 2], [1, 2])', NULL, NULL, 'returns', 'True', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'equal-or-identical'), 3, 'same_contents([1, 2], [2, 1])', '([1, 2], [2, 1])', NULL, NULL, 'returns', 'False', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'equal-or-identical'), 1, 'Two lists that clearly contain the same values still come back `False` - think about what''s actually being checked.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'equal-or-identical'), 2, '`is` checks whether two names point at the *exact same object* in memory, not whether their contents match.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'equal-or-identical'), 3, 'Use `==` instead of `is` to compare contents.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'equal-or-identical'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'identity-vs-equality'), '`is` checks object identity (are these literally the same object?), not equal contents - two separately-created lists with identical items are still different objects.', 'Use `==` to compare values instead of `is`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'equal-or-identical'), (SELECT id FROM bh_concepts WHERE slug = 'identity-vs-equality'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('nested-list-multiplication', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'A Board Made of the Same Row', 14, 3, NULL, 'logic', '`make_board(size)` should build a `size` x `size` grid of zeros, set the top-left cell to `1`, and return the grid - with every other cell still `0`.

Example: `make_board(2)` should return `[[1, 0], [0, 0]]`.', 'def make_board(size):
    board = [[0] * size] * size
    board[0][0] = 1
    return board
', 'def make_board(size):
    board = [[0] * size for _ in range(size)]
    board[0][0] = 1
    return board
', 'function', 'make_board', '`*` on a list repeats *references* to whatever is inside, not fresh copies of it. `[x] * n` gives you `n` names for the one `x` - entirely different from building `n` independent values.', 'Whenever you multiply a list containing a mutable item (like another list), check whether you actually wanted independent copies - a list comprehension usually does.', 'What do you think `make_board(3)` returns? Write it down before you run anything.', 'published', '69655acbb3a8aeb115dcb2c5f2fd751425a9a8fd3150694fc72cf4b3895b230e', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nested-list-multiplication'), 1, 'make_board(3)', '(3,)', NULL, NULL, 'returns', '[[1, 0, 0], [0, 0, 0], [0, 0, 0]]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nested-list-multiplication'), 2, 'make_board(2)', '(2,)', NULL, NULL, 'returns', '[[1, 0], [0, 0]]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nested-list-multiplication'), 3, 'make_board(1)', '(1,)', NULL, NULL, 'returns', '[[1]]', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nested-list-multiplication'), 1, 'Setting just `board[0][0]` seems to change more than one row - trace through what `[[0] * size] * size` actually builds.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nested-list-multiplication'), 2, '`[row] * size` repeats the *same* row object `size` times - it does not build `size` independent rows.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nested-list-multiplication'), 3, 'Use a list comprehension so each row is built separately: `[[0] * size for _ in range(size)]`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nested-list-multiplication'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'aliasing-and-copying'), '`[[0] * size] * size` makes a list containing the *same* inner list object `size` times, so changing one row through an index changes every row.', 'Build the rows with a list comprehension so each one is a separate list.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'nested-list-multiplication'), (SELECT id FROM bh_concepts WHERE slug = 'aliasing-and-copying'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('dict-fromkeys-shared-value', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Every Player Shares One Scoreboard Entry', 15, 3, NULL, 'logic', '`empty_scoreboard(players)` should build a dictionary of empty score lists, one independent list per player, add `10` to the first player''s list, and return the dictionary.

Example: `empty_scoreboard(["Ada", "Sam"])` should return `{"Ada": [10], "Sam": []}`.', 'def empty_scoreboard(players):
    board = dict.fromkeys(players, [])
    board[players[0]].append(10)
    return board
', 'def empty_scoreboard(players):
    board = {p: [] for p in players}
    board[players[0]].append(10)
    return board
', 'function', 'empty_scoreboard', '`dict.fromkeys(keys, value)` is convenient, but it only evaluates `value` once and reuses that exact object for every key - the same trap as a mutable default argument, just in a different disguise.', 'If a dictionary or list is being seeded with `fromkeys(...)` or `[x] * n` using a mutable starting value, check whether every entry is secretly the same object.', 'What do you think `empty_scoreboard(["Ada", "Sam"])` returns? Write it down before you run anything.', 'published', '44967346e108cf63402e6c9b8f916d2565e6bc27933359ba2deed9022eee7c87', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'dict-fromkeys-shared-value'), 1, 'empty_scoreboard(["Ada", "Sam"])', '([''Ada'', ''Sam''],)', NULL, NULL, 'returns', '{"Ada": [10], "Sam": []}', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'dict-fromkeys-shared-value'), 2, 'empty_scoreboard(["X", "Y", "Z"])', '([''X'', ''Y'', ''Z''],)', NULL, NULL, 'returns', '{"X": [10], "Y": [], "Z": []}', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'dict-fromkeys-shared-value'), 3, 'empty_scoreboard(["Solo"])', '([''Solo''],)', NULL, NULL, 'returns', '{"Solo": [10]}', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'dict-fromkeys-shared-value'), 1, 'Only the first player''s score should have changed - check whether the others stayed empty.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'dict-fromkeys-shared-value'), 2, '`dict.fromkeys(keys, value)` gives every key the exact same `value` object - for a mutable default like `[]`, that means one shared list, not one each.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'dict-fromkeys-shared-value'), 3, 'Use a dict comprehension instead: `{p: [] for p in players}`, which builds a fresh list for every player.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'dict-fromkeys-shared-value'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'mutable-defaults'), '`dict.fromkeys(players, [])` gives every player the *same* list object - appending to one player''s list appends to all of them.', 'Build the dictionary with a comprehension so each player gets their own independent list.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'dict-fromkeys-shared-value'), (SELECT id FROM bh_concepts WHERE slug = 'mutable-defaults'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('sort-returns-none', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Losing the List to .sort()', 16, 3, NULL, 'logic', '`sorted_names(names)` should return `names` sorted alphabetically.

Example: `sorted_names(["Bea", "Ada", "Cal"])` should return `["Ada", "Bea", "Cal"]`.', 'def sorted_names(names):
    names = names.sort()
    return names
', 'def sorted_names(names):
    names.sort()
    return names
', 'function', 'sorted_names', '`.sort()` is an in-place method: it rearranges the list itself and hands back `None` as a reminder that nothing new was created. It is one of several common methods that silently return `None` - the bug only shows up if you reassign the result.', 'If a value turns out to be `None` right after calling `.sort()`, `.append()`, `.reverse()`, `.extend()` or similar, check whether you reassigned its result instead of just calling it.', 'What do you think `sorted_names(["Bea", "Ada", "Cal"])` returns? Write it down before you run anything.', 'published', 'd31736bffdb8da3b99cadb7c0665e1096824e8529d4878c6f83e018acaa818f7', NOW());
