INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sort-returns-none'), 2, 'sorted_names(["Z", "A"])', '([''Z'', ''A''],)', NULL, NULL, 'returns', '["A", "Z"]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'sort-returns-none'), 3, 'sorted_names(["Solo"])', '([''Solo''],)', NULL, NULL, 'returns', '["Solo"]', 'exact', 1);
