INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('append-returns-none', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Losing the List to .append()', 17, 3, NULL, 'logic', '`add_and_return(items, value)` should add `value` to the end of `items` and return the updated list.

Example: `add_and_return([1, 2], 3)` should return `[1, 2, 3]`.', 'def add_and_return(items, value):
    items = items.append(value)
    return items
', 'def add_and_return(items, value):
    items.append(value)
    return items
', 'function', 'add_and_return', 'Like `.sort()`, `.append()` is an in-place mutator - it changes the list you already have rather than building a new one, so it has nothing meaningful to return.', 'Never write `x = x.append(...)` (or `.sort()`, `.reverse()`, `.extend()`, `.remove()`, `.insert()`) - call the method, then use `x` on its own afterwards.', NULL, 'published', '369a6d17c54185369d9093281a83d85add3f3594173cb8d4d10e87548a11bb89', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'append-returns-none'), 1, 'add_and_return([1, 2], 3)', '([1, 2], 3)', NULL, NULL, 'returns', '[1, 2, 3]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'append-returns-none'), 2, 'add_and_return([], "x")', '([], ''x'')', NULL, NULL, 'returns', '["x"]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'append-returns-none'), 3, 'add_and_return([0], 0)', '([0], 0)', NULL, NULL, 'returns', '[0, 0]', 'exact', 1);
