INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('reverse-returns-none', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Losing the List to .reverse()', 18, 3, NULL, 'logic', '`reversed_queue(queue)` should return `queue` with its items in reverse order.

Example: `reversed_queue([1, 2, 3])` should return `[3, 2, 1]`.', 'def reversed_queue(queue):
    queue = queue.reverse()
    return queue
', 'def reversed_queue(queue):
    queue.reverse()
    return queue
', 'function', 'reversed_queue', 'Python is consistent about this: methods that change a list in place (`sort`, `reverse`, `append`, `extend`, `insert`, `remove`) always return `None`, as a signal that the useful result is the change itself, not a new value.', 'Learn the short list of common in-place list methods that return `None`, and never assign their result to anything.', NULL, 'published', '2f65eb2db8a24055fbb81aec8d51cc95f569edfc3efd79aa57c559ead5cc024e', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'reverse-returns-none'), 1, 'reversed_queue([1, 2, 3])', '([1, 2, 3],)', NULL, NULL, 'returns', '[3, 2, 1]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'reverse-returns-none'), 2, 'reversed_queue(["a", "b"])', '([''a'', ''b''],)', NULL, NULL, 'returns', '["b", "a"]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'reverse-returns-none'), 3, 'reversed_queue([9])', '([9],)', NULL, NULL, 'returns', '[9]', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'reverse-returns-none'), 1, 'This is the same family of bug as `.sort()` and `.append()` - check what this method actually hands back.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'reverse-returns-none'), 2, '`.reverse()` flips the list in place and returns `None`.');
