INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('default-dict-argument-shared-across-calls', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'A Log That Remembers Between Calls', 19, 4, NULL, 'logic', 'This program adds two separate log entries and prints the second one on its own.

Example output: `{''b'': 2}`', 'def add_entry(key, value, log={}):
    log[key] = value
    return log

first = add_entry("a", 1)
second = add_entry("b", 2)
print(second)
', 'def add_entry(key, value, log=None):
    if log is None:
        log = {}
    log[key] = value
    return log

first = add_entry("a", 1)
second = add_entry("b", 2)
print(second)
', 'script', NULL, 'A default argument value is created exactly once, when Python reads the `def` line - not fresh for every call. For an immutable default (a number, a string) this never matters, but a mutable default (a list or dict) is the *same object* every single time, quietly accumulating state across unrelated calls.', 'Never use a mutable value (`[]`, `{}`, `set()`) directly as a default argument - default to `None` and build the real one inside the function.', 'What do you think gets printed? Write it down before you run anything.', 'published', 'aa36d726775c138aa4192f85ee14afb3e9627d6284862c96c44543d21710c5a1', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'default-dict-argument-shared-across-calls'), 1, 'prints only the second entry', NULL, NULL, '', 'stdout', '"{''b'': 2}\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'default-dict-argument-shared-across-calls'), 2, 'prints only the second entry (repeat check)', NULL, NULL, '', 'stdout', '"{''b'': 2}\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'default-dict-argument-shared-across-calls'), 1, '`second` was built from a call that only mentioned `"b"` - check whether `"a"` has snuck in anyway.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'default-dict-argument-shared-across-calls'), 2, 'The default `log={}` is created once, the moment the function is defined - every call that relies on the default shares that exact same dictionary.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'default-dict-argument-shared-across-calls'), 3, 'Default to `None`, and create a fresh `{}` inside the function only when no `log` was supplied.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'default-dict-argument-shared-across-calls'), 1, 1, 1, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'mutable-defaults'), 'The default `log={}` is created once at definition time and shared by every call that does not supply its own - so entries from earlier calls leak into later ones.', 'Default to `None` and build a fresh dictionary inside the function body when needed.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'default-dict-argument-shared-across-calls'), (SELECT id FROM bh_concepts WHERE slug = 'mutable-defaults'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('closure-nonlocal-missing', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'A Counter That Cannot Count', 20, 4, NULL, 'runtime', 'This program builds a counter and calls it twice, printing each result.

Example output:
```
1
2
```', 'def make_counter():
    count = 0
    def increment():
        count += 1
        return count
    return increment

counter = make_counter()
print(counter())
print(counter())
', 'def make_counter():
    count = 0
    def increment():
        nonlocal count
        count += 1
        return count
    return increment

counter = make_counter()
print(counter())
print(counter())
', 'script', NULL, 'An inner function can *read* a variable from an enclosing function automatically, but as soon as it *assigns* to that name, Python treats it as a brand new local variable for that inner function - unless you explicitly say `nonlocal name` to mean "the outer one".', 'If an inner function needs to change (not just read) a variable from the function that contains it, it needs an explicit `nonlocal` declaration.', NULL, 'published', 'ed6a31171597e97443ff0395476e51dde8c31d102d2c351224e1294853eb2bc0', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'closure-nonlocal-missing'), 1, 'prints 1 then 2', NULL, NULL, '', 'stdout', '"1\\n2\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'closure-nonlocal-missing'), 2, 'prints 1 then 2 (repeat check)', NULL, NULL, '', 'stdout', '"1\\n2\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'closure-nonlocal-missing'), 1, 'This crashes the first time `counter()` is called - the error is about a local variable with no value yet.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'closure-nonlocal-missing'), 2, '`count += 1` assigns to `count`, which makes Python treat it as a new local variable inside `increment` - not the `count` from the outer function.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'closure-nonlocal-missing'), 3, 'Add `nonlocal count` as the first line of `increment`, telling Python to use the outer function''s `count`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'closure-nonlocal-missing'), 1, 3, 3, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'closures'), '`count += 1` makes `count` local to `increment`, so it tries to read `count` before that local ever has a value - it does not automatically reach out to the enclosing function''s `count`.', 'Add `nonlocal count` before using it, so `increment` modifies the outer variable instead of creating its own.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'closure-nonlocal-missing'), (SELECT id FROM bh_concepts WHERE slug = 'closures'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('recursive-base-case-wrong-value', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'A Base Case With the Wrong Value', 21, 3, NULL, 'logic', '`sum_list(numbers)` should return the sum of all the numbers in the list, recursively.

Example: `sum_list([1, 2, 3])` should return `6`.', 'def sum_list(numbers):
    if not numbers:
        return 1
    return numbers[0] + sum_list(numbers[1:])
', 'def sum_list(numbers):
    if not numbers:
        return 0
    return numbers[0] + sum_list(numbers[1:])
', 'function', 'sum_list', 'A recursive function''s base case is not just "when to stop" - its return value directly becomes part of the final combined answer. Getting the base case''s *value* wrong (not just its condition) throws off every result built from it.', 'Test a recursive function on the smallest possible input *on its own* (an empty list, zero, and so on) and check the base case value by hand.', NULL, 'published', 'cdbbe712116cf2d5b16df2df15c56cd05c6b006cb8379bc577e9f7d04f4bcfdb', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'recursive-base-case-wrong-value'), 1, 'sum_list([1, 2, 3])', '([1, 2, 3],)', NULL, NULL, 'returns', '6', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'recursive-base-case-wrong-value'), 2, 'sum_list([])', '([],)', NULL, NULL, 'returns', '0', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'recursive-base-case-wrong-value'), 3, 'sum_list([5])', '([5],)', NULL, NULL, 'returns', '5', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'recursive-base-case-wrong-value'), 1, 'Try it on an empty list first, on its own - what should the sum of nothing be?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'recursive-base-case-wrong-value'), 2, 'The base case return value gets added in at the very end of the recursion, once for every call - a wrong base case throws the whole total off.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'recursive-base-case-wrong-value'), 3, 'Change the base case to `return 0`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'recursive-base-case-wrong-value'), 1, 3, 3, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'recursion'), 'The base case for an empty list returns `1` instead of `0` - since every recursive call eventually bottoms out at this base case, every call to `sum_list` ends up one too high.', 'Return `0` for the empty-list base case, the identity value for addition.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'recursive-base-case-wrong-value'), (SELECT id FROM bh_concepts WHERE slug = 'recursion'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('zip-silently-truncates', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'zip() Drops the Leftovers', 22, 3, NULL, 'logic', '`pair_up(names, scores)` should pair each name with its score. If the lists are different lengths, the extra items should be padded with `None` rather than dropped.

Example: `pair_up(["Ada", "Sam", "Bo"], [10, 20])` should return `[["Ada", 10], ["Sam", 20], ["Bo", None]]`.', 'def pair_up(names, scores):
    return [list(pair) for pair in zip(names, scores)]
', 'from itertools import zip_longest

def pair_up(names, scores):
    return [list(pair) for pair in zip_longest(names, scores)]
', 'function', 'pair_up', '`zip()` is "as long as the shortest sequence" by design, which is exactly right when the lists are genuinely meant to be the same length - but a silent, wrong assumption when they might not be.', 'Before using `zip()`, check whether the two sequences are guaranteed to be the same length - if not, consider `zip_longest()`.', 'What do you think `pair_up(["Ada", "Sam", "Bo"], [10, 20])` returns? Write it down before you run anything.', 'published', '07d2ff2b0aaa711afb41719b35b527167c7cfe25d9852d612c809b361aa6cdff', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'zip-silently-truncates'), 1, 'pair_up(["Ada", "Sam", "Bo"], [10, 20])', '([''Ada'', ''Sam'', ''Bo''], [10, 20])', NULL, NULL, 'returns', '[["Ada", 10], ["Sam", 20], ["Bo", None]]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'zip-silently-truncates'), 2, 'pair_up(["X", "Y"], [1, 2])', '([''X'', ''Y''], [1, 2])', NULL, NULL, 'returns', '[["X", 1], ["Y", 2]]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'zip-silently-truncates'), 3, 'pair_up(["Solo"], [])', '([''Solo''], [])', NULL, NULL, 'returns', '[["Solo", None]]', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'zip-silently-truncates'), 1, 'Try it with lists of different lengths - does every name end up with an entry, even without a matching score?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'zip-silently-truncates'), 2, '`zip()` stops as soon as the *shortest* input runs out - it silently drops whatever is left over in the longer one.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'zip-silently-truncates'), 3, 'Use `itertools.zip_longest()` instead, which pads the shorter list with `None`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'zip-silently-truncates'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'zip-and-enumerate'), '`zip()` stops at the length of the shorter iterable, silently discarding any extra items in the longer one - no error, no warning.', 'Use `itertools.zip_longest()` to keep every item, padding missing ones with `None`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'zip-silently-truncates'), (SELECT id FROM bh_concepts WHERE slug = 'zip-and-enumerate'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('enumerate-starting-index', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Off by One With enumerate()', 23, 3, NULL, 'logic', '`numbered_list(items)` should return each item labelled with its 1-based position, like `"1: apple"`.

Example: `numbered_list(["apple", "pear"])` should return `["1: apple", "2: pear"]`.', 'def numbered_list(items):
    return [f"{i}: {item}" for i, item in enumerate(items)]
', 'def numbered_list(items):
    return [f"{i}: {item}" for i, item in enumerate(items, start=1)]
', 'function', 'numbered_list', '`enumerate(items)` matches how Python indexes things internally (from `0`), which is often not what a human-facing "1st, 2nd, 3rd" numbering wants - `enumerate(items, start=1)` fixes that directly, without a separate `+1` scattered through the code.', 'If output is meant to be human-numbered from 1, use `enumerate(..., start=1)` rather than adding 1 to the result every time it is used.', NULL, 'published', '4b199dac73e608a89a6d300faf17a2a487359a3e7e2078ea6af625647ffe5101', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'enumerate-starting-index'), 1, 'numbered_list(["apple", "pear"])', '([''apple'', ''pear''],)', NULL, NULL, 'returns', '["1: apple", "2: pear"]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'enumerate-starting-index'), 2, 'numbered_list(["x"])', '([''x''],)', NULL, NULL, 'returns', '["1: x"]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'enumerate-starting-index'), 3, 'numbered_list(["a", "b", "c"])', '([''a'', ''b'', ''c''],)', NULL, NULL, 'returns', '["1: a", "2: b", "3: c"]', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'enumerate-starting-index'), 1, 'Check the number attached to the very first item - should a "1st item" be labelled `0`?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'enumerate-starting-index'), 2, '`enumerate()` counts from `0` by default, same as list indexing.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'enumerate-starting-index'), 3, 'Pass `start=1` to `enumerate()`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'enumerate-starting-index'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'zip-and-enumerate'), '`enumerate()` numbers items starting at `0` unless told otherwise - the brief wants human-friendly 1-based numbering.', 'Pass `start=1` to `enumerate()`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'enumerate-starting-index'), (SELECT id FROM bh_concepts WHERE slug = 'zip-and-enumerate'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('bool-int-hash-collision', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'True Looks Exactly Like 1', 24, 4, NULL, 'logic', '`distinct_values(items)` should return how many distinct values are in `items`, counting `True` and `1` as different values.

Example: `distinct_values([1, True, 2])` should return `3`.', 'def distinct_values(items):
    return len(set(items))
', 'def distinct_values(items):
    seen_types_and_values = {(type(x), x) for x in items}
    return len(seen_types_and_values)
', 'function', 'distinct_values', '`bool` is a subclass of `int` in Python - `True` really is `1`, and `False` really is `0`, as far as equality, hashing, and arithmetic are concerned. This is usually convenient (you can `sum()` a list of booleans to count `True`s) but it is a trap for anything that relies on telling `1` and `True` apart.', 'If `True`/`False` need to be treated as genuinely different from `1`/`0`, you cannot rely on `==`, `in`, or a plain `set`/`dict` - check the type explicitly too.', 'What do you think `distinct_values([1, True, 2])` returns? Write it down before you run anything.', 'published', 'bba831c609bd9a30606b8c9dc6688fd201d85a09263de7806c17740b46be6f20', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bool-int-hash-collision'), 1, 'distinct_values([1, True, 2])', '([1, True, 2],)', NULL, NULL, 'returns', '3', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bool-int-hash-collision'), 2, 'distinct_values([0, False, 1])', '([0, False, 1],)', NULL, NULL, 'returns', '3', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bool-int-hash-collision'), 3, 'distinct_values([1, 2, 3])', '([1, 2, 3],)', NULL, NULL, 'returns', '3', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bool-int-hash-collision'), 1, 'Try a list containing both `1` and `True` together - does the count treat them as one value or two?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bool-int-hash-collision'), 2, 'In Python, `True == 1` and `hash(True) == hash(1)` - a `set` or `dict` genuinely cannot tell them apart on their own.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bool-int-hash-collision'), 3, 'Track the *type* alongside the value, e.g. using `(type(x), x)` pairs, not just the value on its own.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bool-int-hash-collision'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'bool-is-int'), 'Python''s `bool` is actually a subtype of `int` - `True` equals `1` and hashes the same way, so a plain `set` merges them into a single entry.', 'Include the type alongside the value (e.g. `(type(x), x)`) so `True` and `1` are kept distinct.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bool-int-hash-collision'), (SELECT id FROM bh_concepts WHERE slug = 'bool-is-int'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('tuple-sort-wrong-field', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Sorting Records by the Wrong Field', 25, 3, NULL, 'logic', '`rank_by_score(students)` should return the list of `[name, score]` pairs sorted by score, highest first.

Example: `rank_by_score([["Bea", 70], ["Ada", 90]])` should return `[["Ada", 90], ["Bea", 70]]`.', 'def rank_by_score(students):
    return sorted(students, reverse=True)
', 'def rank_by_score(students):
    return sorted(students, key=lambda s: s[1], reverse=True)
', 'function', 'rank_by_score', 'Python compares lists (and tuples) left to right, like comparing words in a dictionary - the first element dominates the comparison unless it ties. To sort by a different field, you need an explicit `key` that picks it out.', 'When sorting a list of multi-field records, ask: am I sorting by the field I actually mean, or just by whichever field happens to come first?', 'What order do you think `rank_by_score([["Bea", 70], ["Ada", 90]])` comes back in? Write it down before you run anything.', 'published', '615bca4f22184024ceaa9c08d3716a94006c660fbd4c0b54496a6cbc6cb5c552', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'tuple-sort-wrong-field'), 1, 'rank_by_score([["Bea", 70], ["Ada", 90]])', '([[''Bea'', 70], [''Ada'', 90]],)', NULL, NULL, 'returns', '[["Ada", 90], ["Bea", 70]]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'tuple-sort-wrong-field'), 2, 'rank_by_score([["Zed", 10], ["Amy", 99]])', '([[''Zed'', 10], [''Amy'', 99]],)', NULL, NULL, 'returns', '[["Amy", 99], ["Zed", 10]]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'tuple-sort-wrong-field'), 3, 'rank_by_score([["Solo", 5]])', '([[''Solo'', 5]],)', NULL, NULL, 'returns', '[["Solo", 5]]', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'tuple-sort-wrong-field'), 1, 'Use a name that would sort alphabetically "first" but has a low score - does it end up ranked top anyway?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'tuple-sort-wrong-field'), 2, 'Sorting these pairs without a `key` compares them by their *first* item first (the name), only checking the score as a tie-break.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'tuple-sort-wrong-field'), 3, 'Add `key=lambda s: s[1]` to sort by the score specifically.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'tuple-sort-wrong-field'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'sorting'), 'Without a `key`, each `[name, score]` pair is compared element by element starting with the first one (the name) - the score is only used to break ties between identical names.', 'Sort using `key=lambda s: s[1]` to compare by score specifically.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'tuple-sort-wrong-field'), (SELECT id FROM bh_concepts WHERE slug = 'sorting'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('floating-point-accumulation', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Small Errors Adding Up', 26, 3, NULL, 'logic', '`total_exact(deposit, times)` should return whether adding `deposit` to itself `times` times gives (for all practical purposes) the same result as `deposit * times`.

Example: `total_exact(0.1, 10)` should return `True` (they are equal enough, even though floating-point rounding means they are not bit-for-bit identical).', 'def total_exact(deposit, times):
    total = 0
    for _ in range(times):
        total += deposit
    return total == deposit * times
', 'import math

def total_exact(deposit, times):
    total = 0
    for _ in range(times):
        total += deposit
    return math.isclose(total, deposit * times)
', 'function', 'total_exact', 'Floating-point numbers cannot represent most decimal fractions exactly. A single `0.1 + 0.1 + 0.1` already drifts slightly from `0.3` - repeating that addition many times only makes the gap more likely to matter, which is why financial and scientific code almost never compares floats with `==`.', 'If a loop repeatedly adds floating-point numbers, don''t compare the running total to an exact target with `==` - use `math.isclose()`.', 'What do you think `total_exact(0.1, 10)` returns? Write it down before you run anything.', 'published', '385201c040fb2dcc82043c894a36cbfb0d8b378d5bca5f467c74699b2148be9f', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'floating-point-accumulation'), 1, 'total_exact(0.1, 10)', '(0.1, 10)', NULL, NULL, 'returns', 'True', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'floating-point-accumulation'), 2, 'total_exact(1, 3)', '(1, 3)', NULL, NULL, 'returns', 'True', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'floating-point-accumulation'), 3, 'total_exact(0.1, 7)', '(0.1, 7)', NULL, NULL, 'returns', 'True', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'floating-point-accumulation'), 1, 'Try adding `0.1` to itself a few times by hand in the Playground and compare it to `0.1 * 3` with `==`.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'floating-point-accumulation'), 2, 'Repeated floating-point addition can build up a tiny rounding error that an exact `==` never forgives.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'floating-point-accumulation'), 3, 'Compare with `math.isclose(...)` instead of `==`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'floating-point-accumulation'), 1, 4, 4, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'floating-point'), 'Adding `0.1` repeatedly accumulates tiny rounding errors that an exact `==` comparison never tolerates, even though the values are "the same" for any practical purpose.', 'Use `math.isclose(...)` for a tolerant comparison instead of `==`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'floating-point-accumulation'), (SELECT id FROM bh_concepts WHERE slug = 'floating-point'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('deep-vs-shallow-copy', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'A Copy That Still Shares Its Insides', 27, 4, NULL, 'logic', '`duplicate_grid(grid)` should return an independent copy of a 2D grid (a list of lists) - changing a cell in the copy should never affect the original.

Example: for `grid = [[1, 2], [3, 4]]`, changing the copy''s `[0][0]` should leave `grid[0][0]` as `1`.', 'import copy

def duplicate_grid(grid):
    new_grid = copy.copy(grid)
    new_grid[0][0] = 99
    return grid[0][0]
', 'import copy

def duplicate_grid(grid):
    new_grid = copy.deepcopy(grid)
    new_grid[0][0] = 99
    return grid[0][0]
', 'function', 'duplicate_grid', 'A shallow copy duplicates one level of container, but anything mutable *inside* it - like the rows of a 2D list - is still shared between the original and the copy. A deep copy duplicates all the way down, so nothing is shared at any level.', 'For a list of lists (or any nested mutable structure), `copy.copy()` or `list(x)` or `x[:]` is rarely enough - reach for `copy.deepcopy()`.', 'What do you think this returns for `grid = [[1, 2], [3, 4]]`? Write it down before you run anything.', 'published', 'd1713abf6cad039cedc201583ec94dab838359f3341aeea6a45b6ebd6a5b3366', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'deep-vs-shallow-copy'), 1, 'duplicate_grid([[1, 2], [3, 4]])', '([[1, 2], [3, 4]],)', NULL, NULL, 'returns', '1', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'deep-vs-shallow-copy'), 2, 'duplicate_grid([[5]])', '([[5]],)', NULL, NULL, 'returns', '5', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'deep-vs-shallow-copy'), 3, 'duplicate_grid([[0, 0], [0, 0]])', '([[0, 0], [0, 0]],)', NULL, NULL, 'returns', '0', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'deep-vs-shallow-copy'), 1, 'This function changes `new_grid` and then checks `grid` - they are meant to be independent. Are they?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'deep-vs-shallow-copy'), 2, '`copy.copy()` only makes a shallow copy - it copies the outer list, but the *inner* lists inside it are still shared with the original.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'deep-vs-shallow-copy'), 3, 'Use `copy.deepcopy()` instead, which copies every level, not just the outer one.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'deep-vs-shallow-copy'), 1, 4, 4, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'aliasing-and-copying'), '`copy.copy()` (a shallow copy) duplicates the outer list only - the inner row lists are still the *same objects* as in the original, so mutating a row through the copy mutates it in the original too.', 'Use `copy.deepcopy()` to copy every nested level independently.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'deep-vs-shallow-copy'), (SELECT id FROM bh_concepts WHERE slug = 'aliasing-and-copying'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('string-method-return-ignored', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Strings Do Not Change Themselves', 28, 3, NULL, 'logic', '`clean_name(name)` should return `name` with leading/trailing spaces removed and converted to title case.

Example: `clean_name("  ada lovelace  ")` should return `"Ada Lovelace"`.', 'def clean_name(name):
    name.strip()
    name.title()
    return name
', 'def clean_name(name):
    name = name.strip()
    name = name.title()
    return name
', 'function', 'clean_name', 'Strings are immutable - no string method ever changes the string you call it on. Every one of them (`.strip()`, `.upper()`, `.replace()`, `.title()`, and so on) returns a brand new string, which is silently thrown away unless you capture it.', 'If calling a string method seems to have no effect, check whether you reassigned its return value - the original string genuinely cannot change.', 'What do you think `clean_name("  ada lovelace  ")` returns? Write it down before you run anything.', 'published', '7f09bed2dd62379db6cf4038bb3cab51b3a717a50c15d52a04764e9e94410943', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'string-method-return-ignored'), 1, 'clean_name("  ada lovelace  ")', '(''  ada lovelace  '',)', NULL, NULL, 'returns', '"Ada Lovelace"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'string-method-return-ignored'), 2, 'clean_name("sam")', '(''sam'',)', NULL, NULL, 'returns', '"Sam"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'string-method-return-ignored'), 3, 'clean_name("  BO  ")', '(''  BO  '',)', NULL, NULL, 'returns', '"Bo"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'string-method-return-ignored'), 1, 'Check the returned text carefully - are the spaces actually gone, and is it really title case?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'string-method-return-ignored'), 2, 'Strings are immutable in Python - `.strip()` and `.title()` return a *new* string, they never change the original in place.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'string-method-return-ignored'), 3, 'Reassign the result each time: `name = name.strip()` and `name = name.title()`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'string-method-return-ignored'), 1, 2, 3, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'string-methods'), '`.strip()` and `.title()` return new strings rather than changing `name` in place - calling them without reassigning the result does nothing to `name` itself.', 'Reassign the result of each call back to `name`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'string-method-return-ignored'), (SELECT id FROM bh_concepts WHERE slug = 'string-methods'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('multiple-return-unpack-wrong-order', (SELECT id FROM bh_tracks WHERE slug = 'deep-bugs'), 'Unpacked in the Wrong Order', 29, 3, NULL, 'logic', '`bmi_category(weight_kg, height_m)` should return `"underweight"`, `"normal"` or `"overweight"` based on BMI = weight / height^2 (under 18.5 is underweight, 18.5-25 is normal, over 25 is overweight).

Example: `bmi_category(70, 1.8)` should return `"normal"`.', 'def compute_bmi(weight_kg, height_m):
    return height_m, weight_kg

def bmi_category(weight_kg, height_m):
    weight, height = compute_bmi(weight_kg, height_m)
    bmi = weight / (height ** 2)
    if bmi < 18.5:
        return "underweight"
    elif bmi <= 25:
        return "normal"
    return "overweight"
', 'def compute_bmi(weight_kg, height_m):
    return weight_kg, height_m

def bmi_category(weight_kg, height_m):
    weight, height = compute_bmi(weight_kg, height_m)
    bmi = weight / (height ** 2)
    if bmi < 18.5:
        return "underweight"
    elif bmi <= 25:
        return "normal"
    return "overweight"
', 'function', 'bmi_category', 'When a function returns multiple values, there''s no label attached to each one - the caller matches them up purely by *position*. If the function''s return order and the caller''s unpacking order ever disagree, values get silently swapped with no error.', 'When unpacking multiple return values, check the exact order they were returned in, not just the names you are unpacking them into.', 'What do you think `bmi_category(70, 1.8)` returns? Write it down before you run anything.', 'published', '76aa0071dc5a2c5fddd599839135e8b32570533545bc61d36591957efdd663c7', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'multiple-return-unpack-wrong-order'), 1, 'bmi_category(70, 1.8)', '(70, 1.8)', NULL, NULL, 'returns', '"normal"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'multiple-return-unpack-wrong-order'), 2, 'bmi_category(50, 1.6)', '(50, 1.6)', NULL, NULL, 'returns', '"normal"', 'exact', 0);
