INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'multiple-return-unpack-wrong-order'), 1, 'Compare the order of the values returned by `compute_bmi` to the order they get unpacked into.');
