INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'quiz-scorer'), 3, 'Lower-case both sides before comparing: `answers[i].lower() == correct_answers[i].lower()`.');
