INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('word-frequency-counter', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Word Frequency Counter', 15, 4, NULL, 'mixed', '`word_frequencies(text)` should return a dictionary mapping each word (lowercased) to how many times it appears.

Example: `word_frequencies("The cat sat. The cat ran.")` should return `{"the": 2, "cat": 2, "sat.": 1, "ran.": 1}`.', 'def word_frequencies(text):
    counts = {}
    words = text.split(" ")
    for word in words:
        word = word.lower()
        if word in counts:
            counts[word] = counts[word] + 1
    return counts
', 'def word_frequencies(text):
    counts = {}
    words = text.split(" ")
    for word in words:
        word = word.lower()
        if word in counts:
            counts[word] = counts[word] + 1
        else:
            counts[word] = 1
    return counts
', 'function', 'word_frequencies', 'A frequency counter needs both cases handled: "I have seen this before, add one" and "this is the first time, start at one". Handling only the first case silently drops every word that only appears once.', 'When building up counts in a dictionary, check both the "already seen" and "first time seen" paths are handled.', 'What do you think `word_frequencies("a a b")` returns? Write it down before you run anything.', 'published', 'cb61a0ae1407e063a9692df0f92f76db24a7180c467cb7b9fce9dd9669454702', NOW());
