INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('student-report-generator', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Student Report Generator', 16, 5, NULL, 'mixed', '`build_report(students)` takes a list of `[name, scores]` pairs and returns a list of `[name, average, pass_fail]`, where `pass_fail` is `"Pass"` if the average is 50 or above, else `"Fail"`.

Example: `build_report([["Ada", [80, 90]], ["Sam", [30, 40]]])` should return `[["Ada", 85.0, "Pass"], ["Sam", 35.0, "Fail"]]`.', 'def average(scores):
    total = 0
    for s in scores:
        total = s
    return total / len(scores)

def pass_or_fail(avg):
    if avg > 50:
        return "Pass"
    return "Fail"

def build_report(students):
    report = []
    for name, scores in students:
        avg = average(scores)
        result = pass_or_fail(avg)
        report.append([name, avg, result])
    return report
', 'def average(scores):
    total = 0
    for s in scores:
        total += s
    return total / len(scores)

def pass_or_fail(avg):
    if avg >= 50:
        return "Pass"
    return "Fail"

def build_report(students):
    report = []
    for name, scores in students:
        avg = average(scores)
        result = pass_or_fail(avg)
        report.append([name, avg, result])
    return report
', 'function', 'build_report', 'This combines a broken accumulator (the running total is never actually accumulated) with a boundary mistake in a completely separate function - fixing one does not fix the other, and the broken average has to be fixed first before the pass/fail boundary can even be meaningfully tested.', 'In a multi-step pipeline, verify each stage independently (does the average alone look right?) before judging the stages built on top of it.', 'What do you think `build_report([["Sam", [50, 50]]])` returns? Write it down before you run anything.', 'published', 'f92c9eb1aed74ef8c6a08e7e216ff99fb2c180b773d0358142b76e2964745644', NOW());
