INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'student-report-generator'), 2, 8, 8, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'off-by-one'), '`avg > 50` excludes an average of exactly 50, but the brief says 50 or above should pass.', 'Change `>` to `>=`.');
