INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('temperature-batch-convert', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Temperature Batch Converter', 17, 4, NULL, 'mixed', '`celsius_list_to_fahrenheit(temps)` should convert a list of Celsius temperatures to Fahrenheit, using `F = C * 9/5 + 32`.

Example: `celsius_list_to_fahrenheit([0, 100])` should return `[32.0, 212.0]`.', 'def to_fahrenheit(celsius):
    return celsius * 9 / 5 + 32

def celsius_list_to_fahrenheit(temps):
    result = []
    for t in temps
        result.append(to_fahrenheit(t))
    return result
', 'def to_fahrenheit(celsius):
    return celsius * 9 / 5 + 32

def celsius_list_to_fahrenheit(temps):
    result = []
    for t in temps:
        result.append(to_fahrenheit(t))
    return result
', 'function', 'celsius_list_to_fahrenheit', 'Even a program whose logic is entirely correct (the conversion formula here is right) still won''t run at all if a block header is missing its colon - syntax errors block everything else from being checked.', 'Always get the code running at all before worrying about whether the formula itself is correct.', NULL, 'published', 'eae51e8327f583a220bd80d8261c32bc6d9bc25323a1f25ef1e1a8677c30aa06', NOW());
