INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('library-catalog-search', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Library Catalog Search', 18, 4, NULL, 'mixed', '`find_books_by_author(catalog, author)` should return the titles of every book in `catalog` (a list of `[title, author]` pairs) written by `author`, matching case-insensitively.

Example: `find_books_by_author([["Dune", "Herbert"], ["Emma", "Austen"]], "herbert")` should return `["Dune"]`.', 'def find_books_by_author(catalog, author):
    titles = []
    for title, book_author in catalog:
        if book_author == author:
            titles.append(title)
    return title
', 'def find_books_by_author(catalog, author):
    titles = []
    for title, book_author in catalog:
        if book_author.lower() == author.lower():
            titles.append(title)
    return titles
', 'function', 'find_books_by_author', 'A singular/plural naming mixup and a missing case-normalisation are independent mistakes here - fixing the return value alone would still leave author matching broken for any differently-cased input.', 'When a function builds a list in a loop, double check it actually returns that list - not a leftover loop variable with a similar name.', 'What do you think `find_books_by_author([["Dune", "Herbert"], ["Emma", "Austen"]], "herbert")` returns? Write it down before you run anything.', 'published', '8fc563af6f91394567cfefd3f51ca53962a562fd50ba1665d1bc664e26b185b5', NOW());
