INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('playlist-shuffle-manager', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Playlist Manager', 19, 4, NULL, 'mixed', '`move_to_front(playlist, song)` should move `song` to the front of the playlist (leaving the rest in order) and return the new playlist, without changing the list it was given.

Expected output:
```
[''a'', ''b'', ''c'']
[''c'', ''a'', ''b'']
```', 'def move_to_front(playlist, song):
    playlist.remove(song)
    playlist.insert(0, song)
    return playlist

original = ["a", "b", "c"]
moved = move_to_front(original, "c")
print(original)
print(moved)
', 'def move_to_front(playlist, song):
    new_playlist = playlist.copy()
    new_playlist.remove(song)
    new_playlist.insert(0, song)
    return new_playlist

original = ["a", "b", "c"]
moved = move_to_front(original, "c")
print(original)
print(moved)
', 'script', NULL, 'This function''s return value is actually correct - the bug is a side effect the brief explicitly rules out ("without changing the list it was given"). In-place list methods always mutate whatever object you call them on, which is the caller''s own list unless you copy it first.', 'If a function must not change its argument, check every mutating method call (`.remove()`, `.insert()`, `.append()`, `.sort()`, ...) is operating on a copy, not the original.', 'After calling `move_to_front(original, "c")`, do you think `original` itself is unchanged? Write down yes or no before you run anything.', 'published', '86e5e43b931e7cd963200858c4be169a2ee3a62ed57d49ab3f6532bbcf924123', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'playlist-shuffle-manager'), 1, 'original list stays untouched', NULL, NULL, '', 'stdout', '"[''a'', ''b'', ''c'']\\n[''c'', ''a'', ''b'']\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'playlist-shuffle-manager'), 2, 'original list stays untouched (repeat check)', NULL, NULL, '', 'stdout', '"[''a'', ''b'', ''c'']\\n[''c'', ''a'', ''b'']\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'playlist-shuffle-manager'), 1, 'The returned playlist order is actually fine - the bug is about what else gets changed as a side effect.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'playlist-shuffle-manager'), 2, '`playlist.remove(...)` and `.insert(...)` both mutate the list in place - and `playlist` here is the exact same list object the caller passed in.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'playlist-shuffle-manager'), 3, 'Make a copy first - `new_playlist = playlist.copy()` - and mutate that instead of `playlist` directly.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'playlist-shuffle-manager'), 1, 2, 3, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'aliasing-and-copying'), '`.remove()` and `.insert()` mutate `playlist` in place, and since lists are passed by reference, this also mutates whatever list the caller passed in - even though "moving to front" was only meant to affect the returned copy.', 'Copy `playlist` first, and perform the remove/insert on the copy.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'playlist-shuffle-manager'), (SELECT id FROM bh_concepts WHERE slug = 'aliasing-and-copying'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('contact-dedup', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Contact List Deduplication', 20, 5, NULL, 'mixed', '`deduplicate_contacts(contacts)` should return the contacts list with duplicate emails removed (keeping the first occurrence), comparing emails case-insensitively.

Example: `deduplicate_contacts([["Ada", "a@x.com"], ["Sam", "A@X.com"]])` should return `[["Ada", "a@x.com"]]`.', 'def deduplicate_contacts(contacts):
    seen_emails = []
    result = []
    for name, email in contacts:
        if email not in seen_emails:
            result.append([name, email])
        seen_emails.append(email)
    return result
', 'def deduplicate_contacts(contacts):
    seen_emails = []
    result = []
    for name, email in contacts:
        if email.lower() not in seen_emails:
            result.append([name, email])
            seen_emails.append(email.lower())
    return result
', 'function', 'deduplicate_contacts', 'Both the check and the thing being checked against need to agree on case-sensitivity - normalising one side but not the other is just as broken as normalising neither.', 'When de-duplicating case-insensitively, check that every place an item is compared *and* every place it is recorded both apply the same normalisation.', 'What do you think `deduplicate_contacts([["Ada", "a@x.com"], ["Sam", "A@X.com"]])` returns? Write it down before you run anything.', 'published', '97b756c62de8f2df3c5199c051a20065cf4eb7696c64c1e773c67f0b7cbdead9', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'contact-dedup'), 1, 'deduplicate_contacts([["Ada", "a@x.com"], ["Sam", "A@X.com"]])', '([[''Ada'', ''a@x.com''], [''Sam'', ''A@X.com'']],)', NULL, NULL, 'returns', '[["Ada", "a@x.com"]]', 'exact', 0);
