INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('palindrome-checker-detailed', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Palindrome Checker', 21, 4, NULL, 'mixed', '`is_palindrome(text)` should return whether `text` reads the same forwards and backwards, ignoring case and spaces.

Example: `is_palindrome("Was it a car or a cat I saw")` should return `True`.', 'def clean(text):
    result = ""
    for ch in text:
        if ch != " ":
            result = result + ch
    return result

def is_palindrome(text):
    cleaned = clean(text)
    return cleaned == cleaned[::-1]
', 'def clean(text):
    result = ""
    for ch in text:
        if ch != " ":
            result = result + ch.lower()
    return result

def is_palindrome(text):
    cleaned = clean(text)
    return cleaned == cleaned[::-1]
', 'function', 'is_palindrome', 'The slicing trick `text[::-1]` to reverse a string is correct here - the bug is entirely in the cleaning step, which handles one normalisation (spaces) but forgets the other the brief explicitly asked for (case).', 'When a brief lists several things to normalise ("ignoring case and spaces"), check the code actually handles every one of them, not just the first.', 'What do you think `is_palindrome("Was it a car or a cat I saw")` returns? Write it down before you run anything.', 'published', '9661a7702c33eb2ced433e04ef4d6878da1dd020ed13ab807e5fab4e2989632d', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'palindrome-checker-detailed'), 1, 'is_palindrome("Was it a car or a cat I saw")', '(''Was it a car or a cat I saw'',)', NULL, NULL, 'returns', 'True', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'palindrome-checker-detailed'), 2, 'is_palindrome("hello")', '(''hello'',)', NULL, NULL, 'returns', 'False', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'palindrome-checker-detailed'), 3, 'is_palindrome("Noon")', '(''Noon'',)', NULL, NULL, 'returns', 'True', 'exact', 1);
