INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'palindrome-checker-detailed'), 2, '`clean` removes spaces but never changes the letter case, even though the brief says to ignore case.');
