INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('word-counter-detailed', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Detailed Word Counter', 22, 4, NULL, 'mixed', '`text_stats(text)` should return `[word_count, longest_word]` for the given text.

Example: `text_stats("the quick brown fox")` should return `[4, "quick"]`.', 'def text_stats(text):
    words = text.split(" ")
    longest = ""
    for word in words:
        if len(word) > len(longest):
            longest = word
    return [len(words - 1), longest]
', 'def text_stats(text):
    words = text.split(" ")
    longest = ""
    for word in words:
        if len(word) > len(longest):
            longest = word
    return [len(words), longest]
', 'function', 'text_stats', 'The word-count logic itself didn''t need any adjustment at all - `len(words)` already gives the right count. The `- 1` looks like a leftover attempt at an off-by-one fix that was never actually needed, and it does not even apply to a list in the first place.', 'Before "fixing" an off-by-one with a quick `-1` or `+1`, check the original value was actually off by one in the first place - and that the operation is even valid for the type involved.', NULL, 'published', 'd904a2562c2e3fcb8b3796d747b9b7bef0d09de2048923370d6226de8a8891a4', NOW());
