INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'word-counter-detailed'), 2, '`words` is a list - you cannot subtract a number from a list. The count should just be the length of the list itself.');
