INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('shift-cipher-wraparound', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Shift Cipher With Wraparound', 23, 5, NULL, 'mixed', '`shift_encode(text, shift)` should shift every lowercase letter forward by `shift` places in the alphabet, wrapping around from `z` back to `a`. Non-letters pass through unchanged.

Example: `shift_encode("xyz", 3)` should return `"abc"`.', 'def shift_encode(text, shift):
    result = ""
    for ch in text:
        if ch.isalpha():
            code = ord(ch) - ord("a") + shift
            new_code = code % 26 + ord("a")
            result += chr(new_code)
        else:
            result = ch
    return result
', 'def shift_encode(text, shift):
    result = ""
    for ch in text:
        if ch.isalpha():
            code = ord(ch) - ord("a") + shift
            new_code = code % 26 + ord("a")
            result += chr(new_code)
        else:
            result += ch
    return result
', 'function', 'shift_encode', 'The wraparound shift arithmetic itself (`% 26`) is correct here - the bug is a classic accumulator mistake in the *other* branch, which silently discards everything built up so far whenever a non-letter is encountered.', 'In a loop building up a string or list, check every branch uses `+=`/`.append()` consistently - a single stray `=` resets everything accumulated before it.', 'What do you think `shift_encode("ab 1", 1)` returns? Write it down before you run anything.', 'published', '7e7959ea3100a621eb8007f1d3dabc7189cddc4b321ef9dcd4ef828c39c19cfa', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shift-cipher-wraparound'), 1, 'shift_encode("xyz", 3)', '(''xyz'', 3)', NULL, NULL, 'returns', '"abc"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shift-cipher-wraparound'), 2, 'shift_encode("abc", 1)', '(''abc'', 1)', NULL, NULL, 'returns', '"bcd"', 'exact', 0);
