INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shift-cipher-wraparound'), 3, 'Change `result = ch` to `result += ch` in the `else` branch.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'shift-cipher-wraparound'), 1, 9, 9, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'accumulators'), '`result = ch` overwrites the entire result built so far with just the current non-letter character, throwing away everything before it.', 'Change `result = ch` to `result += ch`.');
