INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('template-filler', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Letter Template Filler', 24, 4, NULL, 'mixed', '`fill_template(template, values)` should replace every `{key}` placeholder in `template` with the matching value from the `values` dictionary.

Example: `fill_template("Hi {name}, you are {age}", {"name": "Ada", "age": 12})` should return `"Hi Ada, you are 12"`.', 'def fill_template(template, values):
    result = template
    for key in values:
        placeholder = "{" + key + "}"
        result = result.replace(placeholder, values[key])
    return result
', 'def fill_template(template, values):
    result = template
    for key in values:
        placeholder = "{" + key + "}"
        result = result.replace(placeholder, str(values[key]))
    return result
', 'function', 'fill_template', 'String methods like `.replace()` are strict about their argument types - they don''t automatically convert a number into its text representation for you, even though that conversion is usually exactly what you want.', 'Before handing a dictionary value to a string method, consider whether it could ever be something other than a string - and convert it explicitly if so.', 'What do you think `fill_template("Hi {name}, you are {age}", {"name": "Ada", "age": 12})` does - does it run cleanly? Write your guess down before you run anything.', 'published', '17df1c492c631de93294a9cfebc09380963c7974639f87c6d14bc8be269d2e86', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'template-filler'), 1, 'fill_template("Hi {name}, you are {age}", {"name": "Ada", "age": 12})', '(''Hi {name}, you are {age}'', {''name'': ''Ada'', ''age'': 12})', NULL, NULL, 'returns', '"Hi Ada, you are 12"', 'exact', 0);
