INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'template-filler'), 3, 'fill_template("no placeholders", {})', '(''no placeholders'', {})', NULL, NULL, 'returns', '"no placeholders"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'template-filler'), 1, 'Try filling in a placeholder whose value is a number, like `age` here - does it crash?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'template-filler'), 2, '`.replace()` needs both its arguments to be strings - a dictionary value that is a number will not work directly.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'template-filler'), 3, 'Convert the value to a string first: `str(values[key])`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'template-filler'), 1, 5, 5, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'types-and-conversion'), '`.replace()` requires its replacement to be a string - passing a non-string value (like the integer `12`) crashes with a `TypeError`.', 'Convert the value with `str(...)` before passing it to `.replace()`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'template-filler'), (SELECT id FROM bh_concepts WHERE slug = 'types-and-conversion'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('bubble-sort-implementation', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Bubble Sort', 25, 5, NULL, 'mixed', '`bubble_sort(numbers)` should return a new list with the numbers sorted in ascending order, without changing the original list.

Expected output:
```
[5, 2, 4, 1]
[1, 2, 4, 5]
```', 'def bubble_sort(numbers):
    result = numbers
    n = len(result)
    for i in range(n):
        for j in range(n - i - 1):
            if result[j] > result[j + 1]:
                result[j], result[j + 1] = result[j + 1], result[j]
    return result

original = [5, 2, 4, 1]
sorted_list = bubble_sort(original)
print(original)
print(sorted_list)
', 'def bubble_sort(numbers):
    result = numbers.copy()
    n = len(result)
    for i in range(n):
        for j in range(n - i - 1):
            if result[j] > result[j + 1]:
                result[j], result[j + 1] = result[j + 1], result[j]
    return result

original = [5, 2, 4, 1]
sorted_list = bubble_sort(original)
print(original)
print(sorted_list)
', 'script', NULL, 'The bubble sort algorithm itself is implemented correctly here - swapping adjacent out-of-order pairs, repeatedly, is exactly right. The bug is entirely about aliasing: forgetting to copy before sorting in place.', 'When a sorting function is meant to return a new, sorted list without touching the original, check it copies the input before any in-place swaps.', 'After calling `bubble_sort(original)`, do you think `original` itself changed too? Write down yes or no before you run anything.', 'published', 'c5ad2f64aef7f804cfd316d5f70627dba8c164a5048ed257e1ffa1268ff46801', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bubble-sort-implementation'), 1, 'original list stays untouched', NULL, NULL, '', 'stdout', '"[5, 2, 4, 1]\\n[1, 2, 4, 5]\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bubble-sort-implementation'), 2, 'original list stays untouched (repeat check)', NULL, NULL, '', 'stdout', '"[5, 2, 4, 1]\\n[1, 2, 4, 5]\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bubble-sort-implementation'), 1, 'The sorting algorithm itself works correctly - the bug is about what else gets changed along the way.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bubble-sort-implementation'), 2, '`result = numbers` does not copy the list - `result` and `numbers` are the same object, so sorting "result" in place also rearranges the caller''s original list.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bubble-sort-implementation'), 3, 'Use `numbers.copy()` to create an independent list before sorting it.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bubble-sort-implementation'), 1, 2, 2, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'aliasing-and-copying'), '`result = numbers` makes `result` just another name for the same list - sorting it in place also sorts the original list the caller passed in, which the brief says should not happen.', 'Copy the list first with `numbers.copy()`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'bubble-sort-implementation'), (SELECT id FROM bh_concepts WHERE slug = 'aliasing-and-copying'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('linear-search-with-count', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Linear Search With a Comparison Count', 26, 4, NULL, 'mixed', '`search_with_count(items, target)` should return `[index, comparisons]` - the index of `target` in `items` (or `-1` if not found), and how many comparisons were made.

Example: `search_with_count([5, 3, 8, 1], 8)` should return `[2, 3]`.', 'def search_with_count(items, target):
    comparisons = 0
    for i in range(len(items)):
        if items[i] == target:
            comparisons = comparisons + 1
            return [i, comparisons]
    return [-1, comparisons]
', 'def search_with_count(items, target):
    comparisons = 0
    for i in range(len(items)):
        comparisons = comparisons + 1
        if items[i] == target:
            return [i, comparisons]
    return [-1, comparisons]
', 'function', 'search_with_count', 'Counting "how many comparisons were made" needs the counter to increase on every attempt, not just the one that happened to succeed - moving the increment inside the `if` silently undercounts every search that does not match on the first try.', 'When counting attempts rather than successes, check the increment runs for every attempt, not only the ones that match a condition.', 'What do you think `search_with_count([5, 3, 8, 1], 8)` returns for the comparison count? Write it down before you run anything.', 'published', '89330e4da3788822d8bb65bc96ac66bf9f61db1837aafc3255b080e6846396f7', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'linear-search-with-count'), 1, 'search_with_count([5, 3, 8, 1], 8)', '([5, 3, 8, 1], 8)', NULL, NULL, 'returns', '[2, 3]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'linear-search-with-count'), 2, 'search_with_count([5, 3, 8, 1], 99)', '([5, 3, 8, 1], 99)', NULL, NULL, 'returns', '[-1, 4]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'linear-search-with-count'), 3, 'search_with_count([], 1)', '([], 1)', NULL, NULL, 'returns', '[-1, 0]', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'linear-search-with-count'), 1, 'Search for a value that is found on the third try - does the comparison count come out as 3?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'linear-search-with-count'), 2, '`comparisons` is only increased inside the `if items[i] == target:` branch, so items that were checked and did *not* match never get counted.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'linear-search-with-count'), 3, 'Move `comparisons = comparisons + 1` so it runs on every loop iteration, before the `if` check.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'linear-search-with-count'), 1, 4, 5, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'accumulators'), 'Incrementing `comparisons` only happens inside the `if` branch, so only the single comparison that actually matched gets counted - every comparison that did *not* match is left out.', 'Increment `comparisons` on every loop iteration, before checking for a match.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'linear-search-with-count'), (SELECT id FROM bh_concepts WHERE slug = 'accumulators'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('stack-simulation', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Stack Simulation', 27, 5, NULL, 'mixed', '`run_operations(operations)` simulates a stack: each operation is `["push", value]` or `["pop"]`. It should return the final stack contents as a list, bottom to top. Popping an empty stack should be ignored (not crash).

Example: `run_operations([["push", 1], ["push", 2], ["pop"]])` should return `[1]`.', 'def run_operations(operations):
    stack = []
    for op in operations:
        if op[0] == "push":
            stack.append(op[1])
        elif op[0] == "pop":
            stack.pop(0)
    return stack
', 'def run_operations(operations):
    stack = []
    for op in operations:
        if op[0] == "push":
            stack.append(op[1])
        elif op[0] == "pop":
            if stack:
                stack.pop()
    return stack
', 'function', 'run_operations', 'A stack and a queue are both built on a list, but they pop from opposite ends - mixing them up gives genuinely different (but not obviously "wrong looking") behaviour. Separately, any operation on a list needs a guard for the empty case if it should not crash.', 'For stack/queue code, double-check which end `.pop()` is actually removing from, and whether empty-collection edge cases are guarded against.', 'What do you think `run_operations([["push", 1], ["push", 2], ["pop"]])` returns? Write it down before you run anything.', 'published', '00908c5a6800fee021b56f74908ddbe6aeeaeb9a3dd73fc745b60c26febfaaa0', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'stack-simulation'), 1, 'run_operations([["push", 1], ["push", 2], ["pop"]])', '([[''push'', 1], [''push'', 2], [''pop'']],)', NULL, NULL, 'returns', '[1]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'stack-simulation'), 2, 'run_operations([["pop"], ["push", 5]])', '([[''pop''], [''push'', 5]],)', NULL, NULL, 'returns', '[5]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'stack-simulation'), 3, 'run_operations([["push", 1], ["push", 2], ["push", 3], ["pop"]])', '([[''push'', 1], [''push'', 2], [''push'', 3], [''pop'']],)', NULL, NULL, 'returns', '[1, 2]', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'stack-simulation'), 1, 'Push three items, then pop once - which item is actually removed, the top or the bottom?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'stack-simulation'), 2, 'A stack pops from the *top* (the end of the list), but `.pop(0)` removes from the *front*. Separately, check what happens when popping an empty stack.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'stack-simulation'), 3, 'Change `stack.pop(0)` to `stack.pop()`, and check `if stack:` before popping.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'stack-simulation'), 1, 6, 6, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'indexing'), '`.pop(0)` removes from the *front* of the list, but a stack is meant to pop from the *top* (the end) - this is actually behaving like a queue, not a stack.', 'Use `.pop()` with no argument to remove from the end.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'stack-simulation'), 2, 6, 6, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'indexing'), 'Popping when the stack is already empty crashes with an `IndexError`, but the brief says it should just be ignored.', 'Check `if stack:` before popping.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'stack-simulation'), (SELECT id FROM bh_concepts WHERE slug = 'indexing'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('queue-simulation', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Queue Simulation', 28, 4, NULL, 'mixed', '`serve_next(queue)` should remove and return the person at the front of the queue, or `None` if the queue is empty - without crashing either way.

Example: for `queue = ["Ada", "Sam"]`, `serve_next(queue)` should return `"Ada"`.', 'def serve_next(queue):
    return queue.pop(0)
', 'def serve_next(queue):
    if not queue:
        return None
    return queue.pop(0)
', 'function', 'serve_next', 'This one is a single, clean missing-guard bug: the queue logic itself (`.pop(0)` for front-removal) is correct, it just needed an empty check added.', 'Any function working on a collection that might be empty needs an explicit empty-check if it should not crash.', NULL, 'published', 'd0248b2b6dddaefd97f14dfdbaafa10afd95619b7ecf6a422afe808aad658545', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'queue-simulation'), 1, 'serve_next(["Ada", "Sam"])', '([''Ada'', ''Sam''],)', NULL, NULL, 'returns', '"Ada"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'queue-simulation'), 2, 'serve_next(["Solo"])', '([''Solo''],)', NULL, NULL, 'returns', '"Solo"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'queue-simulation'), 3, 'serve_next([])', '([],)', NULL, NULL, 'returns', 'None', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'queue-simulation'), 1, 'Try calling this on an empty queue - what happens?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'queue-simulation'), 2, 'There is nothing at position 0 of an empty list to remove.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'queue-simulation'), 3, 'Check `if not queue:` first and return `None` in that case.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'queue-simulation'), 1, 2, 2, 'runtime', (SELECT id FROM bh_concepts WHERE slug = 'indexing'), 'Calling `.pop(0)` on an empty list crashes with an `IndexError`, but the brief says this should return `None` instead.', 'Check whether `queue` is empty before popping from it.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'queue-simulation'), (SELECT id FROM bh_concepts WHERE slug = 'indexing'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('gcd-lcm-calculator', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'GCD and LCM Calculator', 29, 5, NULL, 'mixed', '`gcd_and_lcm(a, b)` should return `[gcd, lcm]` for two positive integers.

Example: `gcd_and_lcm(12, 18)` should return `[6, 36]`.', 'def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def gcd_and_lcm(a, b):
    g = gcd(a, b)
    l = (a + b) // g
    return [g, l]
', 'def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def gcd_and_lcm(a, b):
    g = gcd(a, b)
    l = a * b // g
    return [g, l]
', 'function', 'gcd_and_lcm', 'The Euclidean algorithm for GCD here is correctly implemented. The LCM formula itself uses the wrong operator - addition instead of multiplication - giving a completely different (and wrong) number even though the code runs without error.', 'When a formula combines several values, check each operator against the actual mathematical definition - a wrong operator often still produces a plausible-looking number.', 'What do you think `gcd_and_lcm(12, 18)` returns? Write it down before you run anything.', 'published', '5ca56296f207c95987deb0e81931a88ffaf86baa6341da0749d9b17a3acd8dfc', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'gcd-lcm-calculator'), 1, 'gcd_and_lcm(12, 18)', '(12, 18)', NULL, NULL, 'returns', '[6, 36]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'gcd-lcm-calculator'), 2, 'gcd_and_lcm(7, 5)', '(7, 5)', NULL, NULL, 'returns', '[1, 35]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'gcd-lcm-calculator'), 3, 'gcd_and_lcm(4, 4)', '(4, 4)', NULL, NULL, 'returns', '[4, 4]', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'gcd-lcm-calculator'), 1, 'Work out the LCM formula by hand for `gcd_and_lcm(12, 18)` and compare it to what the code actually computes.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'gcd-lcm-calculator'), 2, 'The LCM formula is `a * b // gcd`, but the code uses `a + b` instead of `a * b`.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'gcd-lcm-calculator'), 3, 'Change `(a + b) // g` to `a * b // g`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'gcd-lcm-calculator'), 1, 8, 8, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'wrong-operator'), 'The LCM formula needs `a * b // g`, but this adds `a` and `b` instead of multiplying them.', 'Change `(a + b) // g` to `a * b // g`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'gcd-lcm-calculator'), (SELECT id FROM bh_concepts WHERE slug = 'wrong-operator'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('fibonacci-sequence-generator', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Fibonacci Sequence Generator', 30, 4, NULL, 'mixed', '`fibonacci_sequence(n)` should return the first `n` numbers of the Fibonacci sequence (starting `0, 1, 1, 2, 3, ...`).

Example: `fibonacci_sequence(5)` should return `[0, 1, 1, 2, 3]`.', 'def fibonacci_sequence(n):
    if n == 0:
        return []
    sequence = [1, 1]
    for i in range(n - 2):
        sequence.append(sequence[-1] + sequence[-2])
    return sequence[:n]
', 'def fibonacci_sequence(n):
    if n == 0:
        return []
    sequence = [0, 1]
    for i in range(n - 2):
        sequence.append(sequence[-1] + sequence[-2])
    return sequence[:n]
', 'function', 'fibonacci_sequence', 'The loop and the final slice are both correct here - the bug is entirely in the two starting values the sequence is seeded with, which quietly shifts every single output by one position along the real sequence.', 'For any sequence built from fixed starting values, check those seed values against the very first few terms the brief describes.', 'What do you think `fibonacci_sequence(5)` returns? Write it down before you run anything.', 'published', 'acec83935368ae7f8faebd9a8c85ab673a7b4af61f191953f775b978fccb7d4a', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'fibonacci-sequence-generator'), 1, 'fibonacci_sequence(5)', '(5,)', NULL, NULL, 'returns', '[0, 1, 1, 2, 3]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'fibonacci-sequence-generator'), 2, 'fibonacci_sequence(1)', '(1,)', NULL, NULL, 'returns', '[0]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'fibonacci-sequence-generator'), 3, 'fibonacci_sequence(0)', '(0,)', NULL, NULL, 'returns', '[]', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'fibonacci-sequence-generator'), 1, 'The Fibonacci sequence is supposed to start `0, 1, 1, 2, 3, ...` - check what the very first number in the result actually is.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'fibonacci-sequence-generator'), 2, 'The sequence is seeded as `[1, 1]` instead of `[0, 1]` - every value comes out one step further along the real sequence than it should.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'fibonacci-sequence-generator'), 3, 'Change the starting seed to `[0, 1]`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'fibonacci-sequence-generator'), 1, 4, 4, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'off-by-one'), 'The sequence is seeded with `[1, 1]` instead of `[0, 1]` - every number produced is shifted one place further along the real Fibonacci sequence than it should be.', 'Seed the sequence with `[0, 1]` instead of `[1, 1]`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'fibonacci-sequence-generator'), (SELECT id FROM bh_concepts WHERE slug = 'off-by-one'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('number-guessing-game-logic', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Number Guessing Game Logic', 31, 4, NULL, 'mixed', '`check_guess(secret, guess)` should return `"Too high"`, `"Too low"`, or `"Correct"`.

Example: `check_guess(50, 70)` should return `"Too high"`.', 'def check_guess(secret, guess):
    if guess > secret:
        return "Too low"
    elif guess < secret:
        return "Too high"
    else:
        return "Correct"
', 'def check_guess(secret, guess):
    if guess > secret:
        return "Too high"
    elif guess < secret:
        return "Too low"
    else:
        return "Correct"
', 'function', 'check_guess', 'The comparisons themselves are exactly right - it''s purely the labels attached to each outcome that got swapped, which is easy to do and easy to miss since the code still runs with no error.', 'For any "too high/too low" style feedback, test with a guess that is obviously on one side and check the message matches, not just that a message comes back.', NULL, 'published', '61647e38a9c1031f86557a91ae8e88916b50921289b5ba28788e86d87605d721', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'number-guessing-game-logic'), 1, 'check_guess(50, 70)', '(50, 70)', NULL, NULL, 'returns', '"Too high"', 'exact', 0);
