INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'number-guessing-game-logic'), 3, 'Swap `"Too low"` and `"Too high"` between the two branches.');
