INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('matrix-transpose', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Matrix Transpose', 32, 5, NULL, 'mixed', '`transpose(matrix)` should return the transpose of a rectangular matrix (rows become columns).

Example: `transpose([[1, 2, 3], [4, 5, 6]])` should return `[[1, 4], [2, 5], [3, 6]]`.', 'def transpose(matrix):
    rows = len(matrix)
    cols = len(matrix[0])
    result = [[0] * rows] * cols
    for r in range(rows):
        for c in range(cols):
            result[c][r] = matrix[r][c]
    return result
', 'def transpose(matrix):
    rows = len(matrix)
    cols = len(matrix[0])
    result = [[0] * rows for _ in range(cols)]
    for r in range(rows):
        for c in range(cols):
            result[c][r] = matrix[r][c]
    return result
', 'function', 'transpose', 'The transpose algorithm (swapping row and column indexes) is correct - the bug is entirely in how the empty result grid gets built, the same nested-list-multiplication trap as building any 2D grid.', 'Whenever you build an empty 2D grid with `[[...]] * n`, check it actually creates independent rows, not `n` names for the same one.', 'What do you think `transpose([[1, 2], [3, 4]])` returns? Write it down before you run anything.', 'published', '3cd95070f76a20a96c1b7b2b698194782dd862d955c4e0814c24abc868264a41', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'matrix-transpose'), 1, 'transpose([[1, 2, 3], [4, 5, 6]])', '([[1, 2, 3], [4, 5, 6]],)', NULL, NULL, 'returns', '[[1, 4], [2, 5], [3, 6]]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'matrix-transpose'), 2, 'transpose([[1, 2], [3, 4]])', '([[1, 2], [3, 4]],)', NULL, NULL, 'returns', '[[1, 3], [2, 4]]', 'exact', 0);
