INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'matrix-transpose'), 1, 'Try a matrix with more than one row that actually differ, like `[[1, 2], [3, 4]]` - does every value end up in the right place?');
