INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('run-length-encoding', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Run-Length Encoding', 33, 5, NULL, 'mixed', '`encode(text)` should compress runs of repeated characters, returning a list of `[character, count]` pairs.

Example: `encode("aaabbc")` should return `[["a", 3], ["b", 2], ["c", 1]]`.', 'def encode(text):
    if not text:
        return []
    result = []
    current = text[0]
    count = 1
    for ch in text[1:]:
        if ch == current:
            count += 1
        else:
            result.append([current, count])
            current = ch
            count = 1
    return result
', 'def encode(text):
    if not text:
        return []
    result = []
    current = text[0]
    count = 1
    for ch in text[1:]:
        if ch == current:
            count += 1
        else:
            result.append([current, count])
            current = ch
            count = 1
    result.append([current, count])
    return result
', 'function', 'encode', 'This is a common "off the end" loop bug: logic that only reacts to a *change* will always miss whatever was still accumulating when the loop runs out of input - the last group needs to be flushed out manually once the loop is done.', 'In a loop that only records a result when something *changes*, check whether the final, still-accumulating state ever gets recorded after the loop ends.', 'What do you think `encode("aaabbc")` returns - specifically, does the last letter make it into the result? Write it down before you run anything.', 'published', '96a9b7fcaf1ac6083f467c745202bb3ce5cff2a82815ec9c3ddad57d1d90ff68', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'run-length-encoding'), 1, 'encode("aaabbc")', '(''aaabbc'',)', NULL, NULL, 'returns', '[["a", 3], ["b", 2], ["c", 1]]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'run-length-encoding'), 2, 'encode("x")', '(''x'',)', NULL, NULL, 'returns', '[["x", 1]]', 'exact', 0);
