INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'run-length-encoding'), 1, 'Check the very last character of the input - does it show up in the result at all?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'run-length-encoding'), 2, 'The current run only ever gets added to `result` when a *different* character is found - the final run never has a "different character" after it to trigger that.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'run-length-encoding'), 3, 'After the loop finishes, append the final `[current, count]` pair once more.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'run-length-encoding'), 1, 13, 13, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'loop-termination'), 'The current run is only recorded when a *different* character ends it - the very last run in the text has nothing after it to trigger that, so it never gets added.', 'Append the final run to `result` once more, after the loop has finished.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'run-length-encoding'), (SELECT id FROM bh_concepts WHERE slug = 'loop-termination'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('unit-converter-multi', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Multi-Unit Length Converter', 34, 4, NULL, 'mixed', '`convert_length(value, from_unit, to_unit)` should convert a length between `"cm"`, `"m"` and `"km"`.

Example: `convert_length(150, "cm", "m")` should return `1.5`.', 'def to_cm(value, unit):
    if unit == "cm":
        return value
    elif unit == "m":
        return value * 100
    elif unit == "km":
        return value * 100000

def from_cm(value, unit):
    if unit == "cm":
        return value
    elif unit == "m":
        return value / 100
    elif unit == "km":
        return value * 100000

def convert_length(value, from_unit, to_unit):
    cm = to_cm(value, from_unit)
    return from_cm(cm, to_unit)
', 'def to_cm(value, unit):
    if unit == "cm":
        return value
    elif unit == "m":
        return value * 100
    elif unit == "km":
        return value * 100000

def from_cm(value, unit):
    if unit == "cm":
        return value
    elif unit == "m":
        return value / 100
    elif unit == "km":
        return value / 100000

def convert_length(value, from_unit, to_unit):
    cm = to_cm(value, from_unit)
    return from_cm(cm, to_unit)
', 'function', 'convert_length', 'Converting to a bigger unit always means dividing (the same real-world length becomes a smaller number), and converting to a smaller unit always means multiplying - this bug applied the multiply from the "to cm" direction without flipping it for the "from cm" direction.', 'For unit conversions, check which direction you are converting - "to a bigger unit" should always shrink the number, never grow it.', 'What do you think `convert_length(100000, "cm", "km")` returns? Write it down before you run anything.', 'published', '250d436affcae46c9e8ef3358099e84e7068345c9200d3b99d48e8bce9edd257', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unit-converter-multi'), 1, 'convert_length(150, "cm", "m")', '(150, ''cm'', ''m'')', NULL, NULL, 'returns', '1.5', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unit-converter-multi'), 2, 'convert_length(100000, "cm", "km")', '(100000, ''cm'', ''km'')', NULL, NULL, 'returns', '1', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unit-converter-multi'), 3, 'convert_length(2, "km", "m")', '(2, ''km'', ''m'')', NULL, NULL, 'returns', '2000', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unit-converter-multi'), 1, 'Try converting a large cm value into km - does the result actually get smaller, as converting to a bigger unit should?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unit-converter-multi'), 2, '`from_cm` converts cm into metres by *dividing*, but into km by *multiplying* - only one of those directions is correct.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unit-converter-multi'), 3, 'Change `value * 100000` to `value / 100000` in the km branch of `from_cm`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unit-converter-multi'), 1, 14, 14, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'division-direction'), 'Converting *from* centimetres *to* kilometres should divide (a km is much bigger than a cm), but this multiplies instead - the same mistake as the `m` branch, just the wrong operation in the other direction.', 'Change `value * 100000` to `value / 100000`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'unit-converter-multi'), (SELECT id FROM bh_concepts WHERE slug = 'division-direction'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('calculator-with-history', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Calculator With History', 35, 5, NULL, 'mixed', '`calculate(expression_list, history=None)` takes a list of `[a, operator, b]` expressions, evaluates each one, appends the result to a history list, and returns the history. Calling it again without passing a history should start a fresh one, not continue the old one.

Expected output:
```
[5]
[9]
```', 'def apply_op(a, operator, b):
    if operator == "+":
        return a + b
    elif operator == "-":
        return a - b
    elif operator == "*":
        return a * b
    elif operator == "/":
        return a / b

def calculate(expression_list, history=[]):
    for a, operator, b in expression_list:
        result = apply_op(a, operator, b)
        history.append(result)
    return history

first = calculate([[2, "+", 3]])
second = calculate([[10, "-", 1]])
print(first)
print(second)
', 'def apply_op(a, operator, b):
    if operator == "+":
        return a + b
    elif operator == "-":
        return a - b
    elif operator == "*":
        return a * b
    elif operator == "/":
        return a / b

def calculate(expression_list, history=None):
    if history is None:
        history = []
    for a, operator, b in expression_list:
        result = apply_op(a, operator, b)
        history.append(result)
    return history

first = calculate([[2, "+", 3]])
second = calculate([[10, "-", 1]])
print(first)
print(second)
', 'script', NULL, 'The arithmetic dispatch in `apply_op` is entirely correct - the bug is the classic mutable default argument trap, applied to a "history" list that is supposed to start fresh each time it is not explicitly continued.', 'Any function that builds up a list/dict across calls using a default argument needs the `None`-then-build-inside pattern if each call should be independent by default.', 'If you call `calculate([[2, "+", 3]])` and then `calculate([[10, "-", 1]])` separately, do you think the second call''s history includes anything from the first? Write yes or no before you run anything.', 'published', '8df37a49f30e0579a3e549c09a001cc75ad6903b5334730212df9634ad8c0502', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'calculator-with-history'), 1, 'two separate calls stay separate', NULL, NULL, '', 'stdout', '"[5]\\n[9]\\n"', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'calculator-with-history'), 2, 'two separate calls stay separate (repeat check)', NULL, NULL, '', 'stdout', '"[5]\\n[9]\\n"', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'calculator-with-history'), 1, 'Each test here calls `calculate` completely fresh, with no history passed in - should any of them see results from a different call?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'calculator-with-history'), 2, '`history=[]` is a mutable default argument - it is created once and shared by every call that does not supply its own.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'calculator-with-history'), 3, 'Default `history` to `None`, and create a fresh `[]` inside the function when needed.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'calculator-with-history'), 1, 11, 11, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'mutable-defaults'), 'The default `history=[]` is created once and shared across every call that relies on it - results from one call to `calculate` can leak into a later, unrelated call.', 'Default `history` to `None` and build a fresh list inside the function.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'calculator-with-history'), (SELECT id FROM bh_concepts WHERE slug = 'mutable-defaults'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('todo-list-manager', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Todo List Manager', 36, 4, NULL, 'mixed', '`complete_task(tasks, task_name)` should mark the task with the matching name as `"done": True` in the list of task dictionaries, and return the updated list. Task names should match exactly.

Example: `complete_task([{"name": "Essay", "done": False}], "Essay")` should return `[{"name": "Essay", "done": True}]`.', 'def complete_task(tasks, task_name):
    for task in tasks:
        if task["name"] == task_name:
            task["done"] = True
            return tasks
    return tasks
', 'def complete_task(tasks, task_name):
    for task in tasks:
        if task["name"] == task_name:
            task["done"] = True
    return tasks
', 'function', 'complete_task', 'An early `return` the moment a match is found is a very natural thing to write, but it quietly assumes names are always unique - which the brief never actually promised. Letting the loop run to completion marks every match, not just the first.', 'Before returning early the moment a loop finds one match, check whether the brief actually guarantees there is only ever one.', 'If two tasks happen to have the same name, do you think both get marked done, or just one? Write your guess before you run anything.', 'published', '4856b26c7f58c3182f39e216827d1f3fba22403f67ebcc19add7fafadbc9066b', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'todo-list-manager'), 1, 'complete_task([{"name": "Essay", "done": False}], "Essay")', '([{''name'': ''Essay'', ''done'': False}], ''Essay'')', NULL, NULL, 'returns', '[{"name": "Essay", "done": True}]', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'todo-list-manager'), 2, 'complete_task([{"name": "A", "done": False}, {"name": "B", "done": False}], "B")', '([{''name'': ''A'', ''done'': False}, {''name'': ''B'', ''done'': False}], ''B'')', NULL, NULL, 'returns', '[{"name": "A", "done": False}, {"name": "B", "done": True}]', 'exact', 0);
