INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'todo-list-manager'), 2, 'Returning immediately inside the loop, the moment one match is found, stops the loop from checking the rest of the list.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'todo-list-manager'), 3, 'Remove the early `return tasks` inside the loop - let it keep checking every task, and return once at the end.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'todo-list-manager'), 1, 5, 5, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'loop-termination'), 'Returning as soon as the first match is found stops checking the rest of the list - if more than one task happens to share the same name, only the first one gets marked done.', 'Remove the early return inside the loop so every matching task gets updated.');
