INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('form-validation-checks', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Signup Form Validation', 37, 5, NULL, 'mixed', '`validate_signup(username, age)` should return a list of error messages: `"Username too short"` if under 3 characters, `"Must be 13 or older"` if under 13. Return an empty list if everything is valid.

Example: `validate_signup("ab", 10)` should return `["Username too short", "Must be 13 or older"]`.', 'def validate_signup(username, age):
    errors = []
    if len(username) < 3:
        errors.append("Username too short")
    if age < 13:
        errors = ["Must be 13 or older"]
    return errors
', 'def validate_signup(username, age):
    errors = []
    if len(username) < 3:
        errors.append("Username too short")
    if age < 13:
        errors.append("Must be 13 or older")
    return errors
', 'function', 'validate_signup', 'Building up a list of independent error messages needs every check to *add* to the list, not replace it - a single `=` where `.append()` was meant wipes out everything collected by earlier checks.', 'When accumulating multiple independent results (errors, matches, totals) in one list, check every single place that updates it uses `.append()`/`+=`, not plain `=`.', 'What do you think `validate_signup("ab", 10)` returns? Write it down before you run anything.', 'published', '69c730a34626d577c18d1ca513ddc5b15bffb0bb0b2df473fef365aa12eb98a8', NOW());
