INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'form-validation-checks'), 2, 'validate_signup("Ada", 20)', '(''Ada'', 20)', NULL, NULL, 'returns', '[]', 'exact', 0);
