INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('leaderboard-top-n', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Leaderboard Top N', 38, 5, NULL, 'mixed', '`top_n_players(scores, n)` takes a dictionary of `{name: score}` and returns the names of the top `n` players, highest score first.

Example: `top_n_players({"Ada": 90, "Sam": 70, "Bo": 85}, 2)` should return `["Ada", "Bo"]`.', 'def top_n_players(scores, n):
    names = list(scores.keys())
    names.sort()
    return names[:n]
', 'def top_n_players(scores, n):
    names = list(scores.keys())
    names.sort(key=lambda name: scores[name], reverse=True)
    return names[:n]
', 'function', 'top_n_players', 'Having the scores available in a separate dictionary doesn''t help unless the sort is explicitly told to look them up - sorting the names list on its own just sorts the names.', 'When ranking one list by values stored in a separate dictionary, check the sort actually has a `key` that looks those values up.', 'What do you think `top_n_players({"Ada": 90, "Sam": 70, "Bo": 85}, 2)` returns? Write it down before you run anything.', 'published', '2553cd2dbc465dd0e609a6e894e761bbf8b0d2648b7ca60fa4f90605adffc8c9', NOW());
