INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'leaderboard-top-n'), 1, 3, 3, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'key-functions'), 'Sorting the names list with no `key` sorts alphabetically - it never looks at `scores` at all, so the "leaderboard" order has nothing to do with actual performance.', 'Sort with `key=lambda name: scores[name], reverse=True` to rank by score.');
