INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('anagram-checker', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Anagram Checker', 39, 4, NULL, 'mixed', '`are_anagrams(word1, word2)` should return whether the two words are anagrams of each other (contain exactly the same letters, ignoring case and spaces).

Example: `are_anagrams("listen", "silent")` should return `True`.', 'def clean(word):
    result = ""
    for ch in word:
        if ch != " ":
            result += ch.lower()
    return result

def are_anagrams(word1, word2):
    a = clean(word1)
    b = clean(word2)
    return a == b
', 'def clean(word):
    result = ""
    for ch in word:
        if ch != " ":
            result += ch.lower()
    return result

def are_anagrams(word1, word2):
    a = clean(word1)
    b = clean(word2)
    return sorted(a) == sorted(b)
', 'function', 'are_anagrams', 'Cleaning the text (removing spaces, lower-casing) was done correctly - the actual anagram check was missing. Sorting both words'' letters puts them into a canonical order that makes direct comparison meaningful.', 'To check two collections contain "the same items in any order", sort both and compare - plain `==` only matches identical order.', 'What do you think `are_anagrams("listen", "silent")` returns? Write it down before you run anything.', 'published', '3307f6f33bd10b74137e19eea1b7c1b60e36b77630823694ae0a6605056c34fe', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'anagram-checker'), 1, 'are_anagrams("listen", "silent")', '(''listen'', ''silent'')', NULL, NULL, 'returns', 'True', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'anagram-checker'), 2, 'are_anagrams("hello", "world")', '(''hello'', ''world'')', NULL, NULL, 'returns', 'False', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'anagram-checker'), 3, 'are_anagrams("Dormitory", "Dirty Room")', '(''Dormitory'', ''Dirty Room'')', NULL, NULL, 'returns', 'True', 'exact', 1);
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'anagram-checker'), 1, 'Try two words that really are anagrams, like "listen" and "silent" - do they get recognised?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'anagram-checker'), 2, 'Comparing the cleaned text directly with `==` checks whether the letters are in the *same order*, not whether they are the same letters rearranged.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'anagram-checker'), 3, 'Sort the letters of both before comparing: `sorted(a) == sorted(b)`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'anagram-checker'), 1, 11, 11, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'sorting'), '`a == b` checks the letters are in the exact same order - two anagrams have the same letters, but usually in a different order, so they would only match by coincidence.', 'Compare sorted versions of both: `sorted(a) == sorted(b)`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'anagram-checker'), (SELECT id FROM bh_concepts WHERE slug = 'sorting'));

INSERT INTO bh_puzzles (slug, track_id, title, sort_order, difficulty, xp, bug_type, brief_md, buggy_code, fixed_code, entry_mode, entry_name, explanation_md, spot_it_md, predict_prompt_md, status, verified_hash, verified_at) VALUES ('simple-budget-tracker', (SELECT id FROM bh_tracks WHERE slug = 'boss-fights'), 'Simple Budget Tracker', 40, 5, NULL, 'mixed', '`apply_transactions(balance, transactions)` takes a starting balance and a list of `[type, amount]` transactions (`"deposit"` or `"withdrawal"`), and returns the final balance. A withdrawal that would make the balance negative should be skipped.

Example: `apply_transactions(100, [["deposit", 50], ["withdrawal", 30]])` should return `120`.', 'def apply_transactions(balance, transactions):
    for kind, amount in transactions:
        if kind == "deposit":
            balance += amount
        elif kind == "withdrawal":
            if balance - amount >= 0:
                balance -= amount
    return amount
', 'def apply_transactions(balance, transactions):
    for kind, amount in transactions:
        if kind == "deposit":
            balance += amount
        elif kind == "withdrawal":
            if balance - amount >= 0:
                balance -= amount
    return balance
', 'function', 'apply_transactions', 'The deposit/withdrawal logic (including the guard against a negative balance) is entirely correct here - the bug is purely in which variable gets returned at the end, easy to mistype when both `balance` and `amount` are in scope and get updated throughout the loop.', 'When a function tracks more than one running value, double check the final `return` names the one that actually matters, not just any variable that happens to be in scope.', 'What do you think `apply_transactions(100, [["deposit", 50], ["withdrawal", 30]])` returns? Write it down before you run anything.', 'published', '4ecf76e8c2a8fc29f1021adb1dab8b7f78e581dc77a9e7010db4b23744057356', NOW());
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'simple-budget-tracker'), 1, 'apply_transactions(100, [["deposit", 50], ["withdrawal", 30]])', '(100, [[''deposit'', 50], [''withdrawal'', 30]])', NULL, NULL, 'returns', '120', 'exact', 0);
INSERT INTO bh_puzzle_tests (puzzle_id, sort_order, label, args_py, kwargs_py, stdin_text, expect_kind, expect_py, compare_mode, is_hidden) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'simple-budget-tracker'), 2, 'apply_transactions(50, [["withdrawal", 100]])', '(50, [[''withdrawal'', 100]])', NULL, NULL, 'returns', '50', 'exact', 0);
