INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'simple-budget-tracker'), 1, 'Check what exactly gets returned - is it the running balance, or just the amount from the very last transaction?');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'simple-budget-tracker'), 2, '`return amount` returns the loop variable from the last transaction processed, not the actual running `balance`.');
INSERT INTO bh_hints (puzzle_id, tier, hint_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'simple-budget-tracker'), 3, 'Return `balance` instead of `amount`.');
INSERT INTO bh_puzzle_bugs (puzzle_id, sort_order, line_start, line_end, bug_type, concept_id, what_md, fix_md) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'simple-budget-tracker'), 1, 8, 8, 'logic', (SELECT id FROM bh_concepts WHERE slug = 'names-and-scope'), 'The function returns `amount` (the last transaction''s amount) instead of `balance` (the actual running total) - a mixup between two similarly-used loop variables.', 'Return `balance` instead of `amount`.');
INSERT INTO bh_puzzle_concepts (puzzle_id, concept_id) VALUES ((SELECT id FROM bh_puzzles WHERE slug = 'simple-budget-tracker'), (SELECT id FROM bh_concepts WHERE slug = 'names-and-scope'));

